window.__D("text/likkutei-sichot/c000",{"p":[[1301410066,"<h3>שיחה א</h3>\nא. \"בעשרה<sup data-n=\"1\">1</sup> מאמרות נברא העולם ומה ת\"ל והלא במאמר אחד יכול להבראות אלא להפרע מן הרשעים שמאבדין את העולם שנברא בעשרה מאמרות וליתן שכר טוב לצדיקים שמקיימין את העולם שנברא בעשרה מאמרות\".\nוידועה הקושיא<sup data-n=\"2\">2</sup> — הרי הקב\"ה הוא עצם הטוב וטבע<sup data-n=\"3\">3</sup> הטוב להטיב, ואיך אפ\"ל דמה שהקב\"ה ברא את העולם בעשרה מאמרות הוא כדי \"להפרע מן הרשעים שמאבדין את העולם שנברא בעשרה מאמרות\"?!\nוביותר תמוה — שהמשנה מקדימה ענין זה לפני \"וליתן שכר טוב לצדיקים\", כאילו שהענין ד\"להפרע מן הרשעים\" דוקא הוא עיקר כוונת הבריאה בעשרה מאמרות?\nדבפשטות הי' צ\"ל לכאורה בסדר הפוך: עיקר בריאת העולם (בעש\"מ) — שכמובן בריאתו היא למען קיומו — הוא ליתן שכר טוב לצדיקים שמקיימים את העולם, אלא שבכדי שתהי' אפשריות הבחירה, צריך להיות גם הענין ד\"להפרע מן הרשעים שמאבדין את העולם\".\n— ומובן שאין לדמות נדו\"ד להא שארז\"ל<sup data-n=\"4\">4</sup> בתחילה עלה במחשבה לברוא את העולם במדת הדין ראה שאין העולם מתקיים שיתף עמו מדת הרחמים — הרי, שמדת הדין היתה בראש ותחילת המחשבה בבריאת העולם —\nכי (נוסף ע\"ז דשם מדובר לפני הבריאה, אבל הבריאה בפועל היתה על ידי אשר \"שיתף עמו מדת הרחמים\"<sup data-n=\"5\">5</sup>, הרי) מה שעלה במחשבה לברוא את העולם במדת הדין אין פירושו שהמכוון העיקרי הוא (לדון ו)לענוש את הנבראים, אלא להיפך, \"זהו<sup data-n=\"6\">6</sup> בחי' תכלית הטוב\"<sup data-n=\"7\">*6</sup> — שע\"י אימת הדין ויראת העונש יימנעו מלהיות חוטאים ורשעים<sup data-n=\"8\">7</sup>; משא\"כ במשנתנו מודגש כי הבריאה בעשרה מאמרות היא \"להפרע מן הרשעים\".\nב. במפרשים<sup data-n=\"9\">8</sup> תירצו ע\"פ דיוק לשון המשנה \"להפרע מן הרשעים\" (ולא — \"להעניש את הרשעים\"), שכוונת המשנה היא — שהקב\"ה רוצה (לא במיתתן של",[["1","1","משנה אבות רפ\"ה."],["2","2","נחלת אבות (להאברבנאל) כאן, הובא במדרש שמואל ד\"ה ובאלו הפירושים."],["3","3","מאמרי אדה\"ז — אתהלך לאזניא (ע' קפו). עטרת ראש שער ר\"ה פ\"ח, וד\"ה אתה אחד לאדהאמ\"צ (מאמרי אדהאמ\"צ קונטרסים ע' ה) — בשם הע\"ח. עמה\"מ שער שעשועי המלך רפ\"א. שער היחוד והאמונה פ\"ד (עט, א). ועוד."],["4","4","פרש\"י פרשתנו בתחלתו ד\"ה ברא אלקים. וראה פסיקתא רבתי פ' בחדש השביעי (ב). ב\"ר פי\"ב, טו."],["5","5","ובלשון רש\"י \"הקדים מדת רחמים כו'\"."],["6","6","כמפורש בכ\"מ (אצל עונש) \"וכל ישראל ישמעו ויראו ולא יוסיפו לעשות\" וכיו\"ב (ראה יג, יב. שופטים יז, יג. יט, כ. תצא כא, כא), ובפרש\"י (שופטים יז, יג) — פשש\"מ — שמפני זה היו מעכבין הדין (כשחמור ביותר) \"עד הרגל\"; וכן בנוגע לשכר (רמב\"ם הל' תשובה רפ\"ט בארוכה). וראה בארוכה ד\"ה שובה ישראל תרנ\"ט (ושם, \"שיש יתרון במדה\"ד על מדת החסד ורחמים בג' דברים\". ע\"ש). — ראה לקמן הערה 47."],["7","*6","ל' ד\"ה שובה ישראל שם (ע' כז)."],["8","7","ועפמש\"נ ומבשרי אחזה אלוקה (איוב יט, כו): חושך שבטו שונא בנו (משלי יג, כד) ולעולם תהא שמאל דוחה וימין מקרבת (סוטה מז, א). ובכ\"מ."],["9","8","מדרש שמואל כאן בתחלתו ד\"ה ואפשר עוד."]]],[1301410067,"רשעים, להענישם \"בדרך נקמה להשמיד להרוג ולאבד\", כ\"א) \"להאריך אפי' ולגבות דילי'<sup data-n=\"10\">9</sup> — בדרך פרעון\"; כי \"אלו הי' נברא העולם במאמר אחד לבד אז הרשעים המאבדים את העולם ברשעתם. . הם פוגמים אותו המאמר שבו נברא העולם. . ולא נשאר דבר בלתי פגום כי הכל נברא במאמר אחד ואין מקום להאריך אפו עליהם. . כי כבר פגמו את הכל. אמנם עתה נברא בעשרה מאמרות. . כדי להפרע מן הרשעים בדרך פרעון ולא בדרך נקמה\".\nאמנם, פירוש זה מסביר רק שגם הענין ד\"להפרע מן הרשעים\" הוא תוצאת טובו וחסדו של הקב\"ה (שרוצה להאריך אף גם לרשעים<sup data-n=\"11\">10</sup>), אבל עדיין אינו מתרץ כלל מה שהתנא מקדים פרעון הרשעים לשכר הצדיקים. שהרי הענין ד\"להפרע מן הרשעים\" הוא סו\"ס טעם נוסף בכוונת בריאת העולם בעשרה מאמרות (כדי שתבוא תועלת גם לרשעים), אבל עיקרו, לכאורה, הוא בשביל נתינת שכר לצדיקים, שכר גדול יותר כי מקיימין את העולם שנברא בעשרה מאמרות.\nג. ויובן בהקדם קושיא כללית:\nבהמשך הפרק מובאים כמה דברים שמספרם עשרה — וצריך ביאור: מדוע לא הובא דבר הכי עיקרי — שהתורה ניתנה בעשרת הדברות?\n[ואין לומר שזהו משום שבדבר זה אין חידוש, כי מפורש בתורה שהם \"עשרת הדברים\"<sup data-n=\"12\">11</sup> — כי גם בין הדברים המפורטים ישנם כאלה שידוע ומפורש שהם במספר עשרה, ולדוגמא: \"עשרה<sup data-n=\"13\">12</sup> נסיונות נסו אבותינו כו' שנאמר<sup data-n=\"14\">13</sup> וינסו אותי זה עשר פעמים\"<sup data-n=\"15\">14</sup>].\nובפרט ע\"פ מאמר חז\"ל<sup data-n=\"16\">15</sup> עה\"פ<sup data-n=\"17\">16</sup> \"עשרה עשרה הכף בשקל הקודש\", שהעשרה מאמרות מכוונים כנגד עשרת הדברות<sup data-n=\"18\">17</sup>, דמזה מוכח שהמספר דעשרה מאמרות (שבו פתח התנא) שייך להמספר דעשרת הדברות.\nד. וי\"ל נקודת הביאור בכל זה:\nהטעם שהתנא מפרט את אלה הדברים הקבועים במספר עשרה, הוא להדגיש בזה את גודל חשיבותם של דברים אלו — כי עשר הוא \"מספר השלם\". וכפי שאנו מוצאים שלימות מספר זה בנוגע לכמה ענינים, וכמובא בספרים<sup data-n=\"19\">18</sup>; לדוגמא: א) כל דבר הוא בעל שלש קוטרים, אורך רוחב ועומק, וכל אחד מהם כלול מג', ראש תוך סוף (סת\"ר), וביחד עם המקום ה\"סובלם\" הרי זה מספר עשר. ובלשון הרמב\"ם<sup data-n=\"20\">19</sup>: העצם וט' המקרים. ב) בחיי האדם, שכל עשר שנים הן תקופה בפ\"ע, כסיום הפרק \"בן עשרים כו' בן שלשים כו'\"; ג) בנפש האדם — שיש לה עשר כחות<sup data-n=\"21\">20</sup>;",[["10","9","ל' חז\"ל — ב\"ר פס\"ז, ד. ירושלמי ביצה פ\"ג ה\"ח. ועוד."],["11","10","ולהעיר מתוס' ב\"ק נ, ריש ע\"ב."],["12","11","תשא לד, כח. ואתחנן ד, יג. עקב יוד, ד."],["13","12","סוף משנה ד."],["14","13","שלח יד, כב."],["15","14","אבל י\"ל שאינה חלוקה בפ\"ע כ\"א המשך לתחילת המשנה עשרה נסים; או להמשנה שלפנ\"ז עשרה נסיונות, שזה הי' הנתינת כח לישראל — ראה מדרש שמואל שם."],["16","15","זח\"ג יא, ב ואילך. וראה גם זח\"ב מג, רע\"א. צג, סע\"ב."],["17","16","נשא ז, פו."],["18","17","ובזח\"ג שם מפרט השייכות דכל דיבור למאמר המתאים. וראה בארוכה פרדס שער ב פ\"ג. ואכ\"מ."],["19","18","ראה פרדס שער ב פ\"אב (וראה גם שער ח פכ\"ה). ראב\"ע לשמות ג, טו."],["20","19","ספר מלות ההגיון שער יו\"ד."],["21","20","<a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ\"ג</a>. ועוד."]]],[1301410068,"והשלימות שבמספר עשרה היא גם בעניני מצוות: בהצטרף יחדיו עשרה מישראל הרי זו עדה קדושה (וכל בי עשרה שכינתא שריא<sup data-n=\"22\">21</sup>); בכמה ענינים — \"העשירי יהי' קודש\"<sup data-n=\"23\">22</sup>. ועוד<sup data-n=\"24\">23</sup>.\nאשר עפ\"ז מובן שהמספר עשרה (מספר שלם) של הדברים המפורטים בהמשניות (דפרק זה), מורה על חשיבות שלהם ומעלת שלימותם של דברים אלו.\nאמנם כ\"ז הוא בדברים דבריאת העולם, היות ונקבע בעולם ששלימות היא במספר עשרה; אבל התורה היא למעלה מהעולם, ולכן אין מקום לומר שנתינתה בעשרת הדברות — מורה על מעלתה וחשיבותה, כדלקמן.\nה. הסברת הענין:\nסיבת הדבר, ששלימות כל ענין היא כשהוא במספר עשרה, הוא לפי שכך הוטבע בהבריאה מהבורא ית' — שהקב\"ה ברא את עולמו בעשרה מאמרות המכוונים (כנזכר במפרשי המשנה כאן<sup data-n=\"25\">24</sup>) נגד עשר ספירות העליונות, ומזה נמשך ונקבע בכל העולמות (בלשון הידוע: בכל סדר ההשתלשלות) ששלימותם היא כאשר הם במספר עשרה.\nאמנם אין פירוש הדברים שהשלימות דמספר עשרה הוא ענין הכרחי בעצם — כי ח\"ו לומר שיש דבר שהקב\"ה מוכרח בו —\nאלא שכך עלה ברצונו יתברך, בבחירתו החפשית, להאציל עשר ספירות, \"עשר ולא ט' עשר ולא יא\"<sup data-n=\"26\">25</sup>, וכתוצאה מזה היא השלימות דמספר עשר בכל עניני העולם<sup data-n=\"27\">26</sup>. והיינו שזהו דבר המסובב לאחרי שעלה ברצונו של הקב\"ה לבחור במספר עשר, ומזה — שלימותו דהמספר בכל עולם ובכל מדריגה; אבל לפני (ולמעלה מן) עליית רצון זה (להאציל עשר ספירות) הרי אין שייך לומר שהשלימות היא במספר עשר דוקא או במספר אחר וכו'<sup data-n=\"28\">27</sup>\n[ואילו בחר הקב\"ה לברוא את העולם במספר אחר של ספירות — ע\"ד לשון המשנה כאן \"במאמר אחד יכול להבראות\" — אז היתה השלימות במספר זה דוקא].\nועפ\"ז יובן גם בנוגע למספר העשרה שבתורה (עשרת הדברות):\nידוע מאמר חז\"ל<sup data-n=\"29\">28</sup> שהתורה היא כלי אומנתו של הקב\"ה — \"דיפתראות ופינקסאות\", שעל ידם ברא הקב\"ה את העולם. ומובן, שאין הכוונה רק לבריאת עולם הזה הגשמי, אלא בריאת כל",[["22","21","סנהדרין לט, א. וראה אגה\"ק סכ\"ג."],["23","22","בחוקותי כז, לב."],["24","23","וראה מדרש מעשה תורה אות יוד. ולהעיר גם מפי' הר\"מ בוטריל לספר יצירה פ\"א מ\"א (יד, ד. טז, א ואילך)."],["25","24","ראה מדרש שמואל כאן ד\"ה והחסיד ז\"ל בסופו. וראה גם זח\"ב מב, ב ואילך."],["26","25","ספר יצירה פ\"א מ\"ד."],["27","26","וכן צ\"ל בנוגע לטעם הפרדס ש\"ב פ\"ו ועוד — שכ\"ז הוא לאחרי שעלה ברצונו ונעשה זה גדר העולם (האצילות) כו'. וראה אוה\"ת על מרז\"ל וענינים ע' סט. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201087\" data-slug=\"likkutei-sichot\" data-id=\"1300201087\">לקו\"ש ח\"כ ע' 87</a> הערה 13 בשוה\"ג."],["28","27","ובדוגמת כללות ענין הבריאה, שאף שנאמרו כמה טעמים ע\"ז בזהר וע\"ח (בגין דישתמודעון, שיתגלו שלימות כוחותיו וכו' — ראה המשך תרס\"ו בתחלתו (ע' ד ואילך). המשך ר\"ה תש\"ב פט\"ז ואילך. ועוד) — ה\"ז לאחרי שנתלבש באורות וכלים דאצילות, אבל שרשו ומקורו הוא למעלה מהטעם לגמרי, כמאמר אדה\"ז שהוא מצד התאווה שלמעלה מטעם (ראה המשך תרס\"ו שם (ע' ז ואילך) ותש\"ב שם (פי\"ט). ועוד)."],["29","28","ב\"ר בתחלתו."]]],[1301410069,"העולמות היא על ידי התורה. ומזה, שגם גדרי העולם (כולל גם זה ששלימות עניניו מוגדרת במספר עשרה) נבראו על ידי התורה.\nובזה יובן, דמה שהתורה ניתנה במספר עשרה (\"עשרת הדברות\"), אין זה משום, מסובב מהשלימות שבמספר זה, כ\"א להיפך — להיות התורה ה\"דיפתראות\" של כל הבריאה, הרי מספר העשרה שבה ניתפרטה, הוא המסבב שלימותו של מספר זה בכל עניני הבריאה. והיינו, שבהן ועל ידן (דמספר עשרה שבתורה) — גילוי רצונו ית' (שלמעלה מטעם) שכל סדר ההשתלשלות יהי' מוגדר ובא לשלימותו במספר עשרה,\nע\"ד בהמשל, שהדיפתראות מבטאים ומגלים את רצונו של האומן הבונה את הבית.\nולכן, אין למנות הענין דעשרת הדברות שבתורה בין הדברים (שבמשניות אלו) שהם במספר עשרה — כיון שמספר זה (בתורה) לא בא לגלות מעלה וחשיבות בתורה, כ\"א להיפך, כנ\"ל — החשיבות דמספר עשר באה ומסובבת מזה שהדברות שבתורה הן במספר עשר דוקא, כתוצאה מזה נעשה מספר \"עשר\" חשוב (ולא שעשה\"ד הם חשובים ביותר בגלל שהם במספר עשר).\nו. והנה, לא זו בלבד שהשלימות דמספר עשרה אינו ענין המוכרח בסדר הבריאה, וסיבתו (הראשונה) היא רק רצונו ובחירתו ית' (שלמעלה מטעם) — אלא עוד זאת, שגם לאחרי שהוקבע כן בטבע הבריאה, אין הקב\"ה ח\"ו מוכרח בזה, וביכלתו לשנות כו'.\nכלומר: עם היות שלאחרי שנברא העולם על ידי עשרה מאמרות (המכוונות כנגד העשר ספירות) הרי כל עולם ועולם (וכל דבר ודבר) שלימותו מוגדרת במספר עשרה (ואי אפשר לנו לצייר אחרת) — ועד שגם עניני תורה ויהדות מוגדרים במספר זה דוקא (כנ\"ל) — מ\"מ, זהו רק מצדנו, הנבראים, שנבראו מעשרה מאמרות; אבל מצד הקב\"ה שאינו מוכרח ברצונו ח\"ו, הרי גם לאחרי שקבע כן בעולמו, ביכלתו ית' לשנות, לברוא, או לעשות ענין בהבריאה ששלימותו אינו במספר עשר, ויתרה מזה — ענין שאינו בגדרי הבריאה בכלל.\n[ע\"ד כללות ענין הנסים שבאים לשדד מערכות הטבע: עם היות שהעולם מתנהג לפי חוקי הטבע, וכמש\"נ בתורה<sup data-n=\"30\">29</sup> \"זרע. . ויום ולילה לא ישבותו\" — מ\"מ הרי פשוט שזהו רק לפי שכן קבע הקב\"ה, אבל אינו ענין הכרחי כלל וכלל ח\"ו אצלו ויכול לשנות גדרי הטבע כפי שיעלה ברצונו ית'; ולפעמים עושה הקב\"ה נסים לשדד מערכות הטבע, שבזה נראה לעין כל אשר גם לאחרי קביעתם של חוקי הטבע, אין הקב\"ה מוכרח בהם ח\"ו, וביכלתו ית' לשנות כו'<sup data-n=\"31\">30</sup>].\nוזהו ג\"כ אחד מהפירושים בדברי התנא כאן \"בעשרה מאמרות נברא העולם כו' והלא במאמר אחד יכול להבראות\": אין כוונת התנא בזה להשמיענו רק מה שהי' יכול להיות בעבר, כ\"א לומר ג\"כ שגם עתה (שנברא העולם בעשרה מאמרות) ישנה יכולת זו<sup data-n=\"32\">31</sup>,",[["30","29","נח ח, כב."],["31","30","להעיר מחינוך מצוה כא, דמה שבא לנו מצות רבות על זכירת יציאת מצרים \"לפי שהוא לנו אות ומופת גמור בחידוש העולם וכי יש אלוקה כו' ובידו לשנות כפי שיחפוץ בכל זמן מהזמנים כמו שעשה במצרים ששינה טבעי העולם בשבילנו כו'\". ועד\"ז בכ\"מ."],["32","31","ראה אוה\"ת שם ע' נב."]]],[1301410070,"אלא שמכיון שיכולת זו היא למעלה מן העשרה מאמרות שבהם נברא העולם, הרי גם פעולתה היא בענין שאינו לפי גדרי העולם. כדלקמן.\nז. שני ענינים הנ\"ל בנוגע להבריאה [(א) אשר עניני והנהגות הבריאה כולם הם באופן דלא ישבותו (כולל — השלימות דמספר עשרה, מאחר שנבראו על ידי העשרה מאמרות); (ב) \"במאמר אחד יכול להבראות\" — יכולתו ית' שאינה מוגדרת בשום גדר, ופועלת בעולם לא לפי גדרי העולם] — ישנם גם בעבודת האדם:\nא) האדם הוא נברא מוגבל ומוגדר בגדרי וסדרי הבריאה — ובלשון חז\"ל<sup data-n=\"33\">32</sup> אין סומכין על הנס. ב) מאחר שנשמת כל איש ישראל היא \"חלק אלקה ממעל ממש\"<sup data-n=\"34\">33</sup>, לכן בכחו \"להגיע\" ולעבוד את השם<sup data-n=\"35\">34</sup> באופן שלמעלה מן הבריאה.\nובכללות (וגם כפי שהעולם במילואו נברא, והאדם בשלימותו), הם שני סוגי העבודה — עבודת הצדיקים ועבודת התשובה — שהחילוק ביניהם הוא<sup data-n=\"36\">35</sup>: עבודת הצדיקים היא בסדר של איש ישר הולך — האלקים עשה את האדם ישר<sup data-n=\"37\">36</sup> — עבודה מסודרה כפי סדרי התורה; עבודת הבעלי תשובה: דאף מי שחטא ופגם ועבר את הדרך ר\"ל, העברה על דרכי התורה, על ידי התשובה הוא חוזר ושב ומתקרב אל הקב\"ה ומתדבק (\"לדבקה\") בו ומקיים מצוותיו בחילא יתיר<sup data-n=\"38\">37</sup>.\nועד\"ז הוא בנוגע לפעולתם בעניני העולם: עבודת הצדיקים פועלת והיא רק בדברים המותרים ע\"פ תורה, שהוא עוסק בהם לשם שמים וכו', אבל לא בדברים האסורים, שאין לצדיק מגע ומשא עמהם והוא דוחה אותם בתכלית הדחי'<sup data-n=\"39\">38</sup>. ועבודת הבעלי תשובה — ע\"י התשובה<sup data-n=\"40\">39</sup> הזדונות נעשו לו כזכיות<sup data-n=\"41\">40</sup>.\nוכן הוא גם בנוגע לחילוקי דרגות דהנשמה בקשר לעבודת הצדיקים ועבודת התשובה — דמעלתה של עבודת התשובה היא בזה שבאה מצד בחי' יחידה שבנפש דוקא<sup data-n=\"42\">41</sup>: עבודת הצדיקים, שהיא השלימות דעבודת ה' על פי סדר שצ\"ל רגיל בחיים דבנ\"י — קשורה (בעיקר) עם העבודה בכחות (הגלויים ד)הנפש שהם במספר עשר (וכנ\"ל, שהשלימות בכל עניני הבריאה תלוי' במספר עשר דוקא); אבל עבודת התשובה שהיא למעלה מסדר הרגיל\n— רגיל עד כ\"כ שהאומר אחטא ואשוב אין מספיקין בידו לעשות תשובה<sup data-n=\"43\">42</sup> —\nהיא באופן ד\"בכל מאדך\"<sup data-n=\"44\">43</sup>, למעלה ממדידה והגבלה דמספר עשר (וכחות הנפש), ולכן היא שייכת לבחי' אחד<sup data-n=\"45\">44</sup>,",[["33","32","ראה פסחים סד, ב."],["34","33","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["35","34","כיון ש\"אני נבראתי לשמש את קוני\" (קידושין בסופה)."],["36","35","בהבא לקמן ראה גם ד\"ה ביום השמע\"צ תש\"מ סוס\"ג (סה\"מ מלוקט ח\"א ע' שסו) ואילך. וש\"נ."],["37","36","ל' הכתוב — קהלת ז, כט."],["38","37","זח\"א קכט, ב. אגה\"ת ספ\"ח."],["39","38","ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381156\" data-slug=\"likkutei-torah\" data-id=\"4001381156\">לקו\"ת שה\"ש ו, ד</a>."],["40","39","ראה בארוכה דרמ\"צ קצא, א."],["41","40","יומא פו, ב."],["42","41","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380824\" data-slug=\"likkutei-torah\" data-id=\"4001380824\">לקו\"ת ראה כז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381325\" data-slug=\"likkutei-torah\" data-id=\"4001381325\">שה\"ש מט, ב</a>. ועוד."],["43","42","יומא פה, ב."],["44","43","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380873\" data-slug=\"likkutei-torah\" data-id=\"4001380873\">לקו\"ת תצא לט, סע\"א</a>. שה\"ש שם. ובארוכה ד\"ה שובה תרנ\"ט. ובכ\"מ. — וראה שע\"ת לאדהאמ\"צ ח\"ב חינוך פמ\"ח, שאמיתית ענין \"בכל מאדך\" הוא בבע\"ת דוקא."],["45","44","להעיר מזח\"א (קכט, סע\"א ואילך) דתשובה היא \"בשעתא חדא כו' ברגע חדא כו' מה דלא הוה. . לצד\"ג כו'\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181130\" data-slug=\"likkutei-sichot\" data-id=\"1300181130\">לקו\"ש חי\"ח ע' 121</a> ואילך."]]],[1301410071,"שבאה מבחי' יחידה שבנפש הנקראת \"אחת\" (כדאיתא בתוס'<sup data-n=\"46\">45</sup>).\nח. ומעתה יבוארו דברי המשנה \"בעשרה מאמרות כו' להפרע מן הרשעים כו'\":\nנזכר לעיל דיוק המפרשים בלשון המשנה \"להפרע מן הרשעים\" (ולא — \"להעניש\"), שהכוונה בזה היא — \"לגבות דילי' בדרך פרעון\". כלומר, אין הכוונה (לענוש את החוטא לשם) נקמה, אלא עונש המביא את החוטא \"לפרוע\" את ה\"חוב\" שמחוייב \"לשלם\" עבור מעשהו הרע.\nדהנה כל נשמה ירדה למטה בשליחותו של הקב\"ה לעשות לו ית' דירה בתחתונים<sup data-n=\"47\">46</sup>, והוא — על ידי קיום התומ\"צ. אמנם מי שחטא ופגם ועבר את הדרך ר\"ל, הרי נעשה עי\"ז \"בעל חוב\" להקב\"ה, כי צריך הוא להשלים את השליחות המוטלת עליו.\nותשלום חוב זה הוא ענין התשובה, שבה ועל ידה הוא מתקן כל החסרונות שפעל על ידי חטאיו. וזהו תוכן הענין ד\"להפרע מן הרשעים\", שהקב\"ה תובע מן הרשעים שישלמו לו כביכול החוב — על ידי עשיית תשובה [וזהו ג\"כ ענין העונשים כפשוטו, שתכליתם אינה בשביל העונש עצמו, אלא כדי להביא את האדם לידי תשובה<sup data-n=\"48\">47</sup>].\nועפ\"ז יש לפרש בעומק יותר המשך דברי התנא \"(להפרע מן הרשעים) שמאבדין את העולם שנברא בעשרה מאמרות\" — שגם זה (שהרשעים \"מאבדין את העולם שנברא בעשרה מאמרות\") יש בזה גם ענין למעליותא, בהתאם להעילוי שבעבודת התשובה, שע\"י התשובה בונים \"עולם חדש\"<sup data-n=\"49\">48</sup> — הנהגה יום יומית בחילא יתיר דוקא, ועד שצמאה נפשם ביתר עוז מצמאון נפשות הצדיקים<sup data-n=\"50\">49</sup>.\nוזהו \"להפרע מן הרשעים שמאבדין את העולם שנברא בעשרה מאמרות\" — ש\"פרעון\" הרשעים הוא בזה, שהם מאבדין ומבטלים את המדידה וההגבלה שבעולם (מצד זה שנברא ב\"עשרה מאמרות\"), כי על ידי התשובה מתגלה בעולם יכלתו ית' שלמעלה מן העשרה מאמרות (ועשר ספירות), שאינה מוגדרת בגדר הבריאה והיא המנהגת את העולם — ע\"ד שיהי' גם בגשמיות העולם לעת\"ל שארץ ישראל תוציא גלוסקאות וכלי מילת<sup data-n=\"51\">50</sup> וכיו\"ב.\nט. ועפ\"ז יבואר המשך דברי המשנה:\nבתחילת המשנה אומר התנא \"בעשרה מאמרות נברא העולם ומה ת\"ל והלא במאמר אחד יכול להבראות\" — שבזה מבאר (כנ\"ל) שני הענינים שבאופן הבריאה: (א) ההגבלה שישנה בהבריאה מצד זה שנברא בעשרה מאמרות, (ב) ביחד עם זה ישנו ה\"מאמר אחד (שבו)",[["46","45","מנחות יח, א ד\"ה עד אחת."],["47","46","תנחומא נשא טז. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>."],["48","47","ולאט לאט דוקא — כמפורש בהכתובים דפ' בחוקותי (כו: יח. כא. כג (ובפרש\"י). כז. ועוד), והובא להלכה — ראה רמב\"ם ריש הל' תעניות. וכן מפורש לגבי עונש על היחיד — ראה רמב\"ם סוף הל' טומאת צרעת. קדושין כ, א (וש\"נ), הובא בפרש\"י בהר כו, א. ובכ\"מ."],["49","48","נוסף ע\"ז שהאדם נעשה מציאות חדשה — בלשון הרמב\"ם (הל' תשובה פ\"ב ה\"ד) \"אני אחר ואיני אותו האיש שעשה אותן המעשים\", ונעשה ענין חדש בעולם — שזדונות נעשו לזכיות, כנ\"ל —\nהנה גם סדר ואופן עבודתו שלאח\"ז — \"עולם\" שלו — הוא באופן חדש, כבפנים."],["50","49","<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז</a>."],["51","50","שבת ל, סע\"ב. וש\"נ. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."]]],[1301410072,"יכול להבראות\", יכלתו ית' שאינו מוגדר בשום גדר, שגם היא פועלת בהבריאה, כנ\"ל<sup data-n=\"52\">51</sup>;\nובהתאם לזה ממשיך בשני סוגי העבודה — העבודה ד\"להפרע מן הרשעים שמאבדין את העולם שנברא בעשרה מאמרות\", כלומר עבודת התשובה הבאה מה\"מאמר אחד יכול להבראות\" (ולכן היא מבטלת את ההגבלה שנשתלשלה מהעשרה מאמרות למטה)<sup data-n=\"53\">52</sup>;\n\"וליתן שכר טוב לצדיקים שמקיימין את העולם שנברא בעשרה מאמרות\" — שעל ידי עבודתם בקיום התומ\"צ, פועלים קיום וחיזוק (בעשרה מאמרות, ועי\"ז) בהבריאה עצמה.\nועפ\"ז מתורץ מדוע הקדים התנא \"להפרע מן הרשעים\" לפני \"וליתן שכר טוב לצדיקים\" — כי נוסף ע\"ז שעבודת התשובה היא למעלה מעבודת הצדיקים (כמאמר: מקום שבעלי תשובה עומדין אין צדיקים גמורין יכולין לעמוד בו<sup data-n=\"54\">53</sup>) — הנה גם בנוגע לפעולתה בעניני העולם (שנברא בעשרה מאמרות) יש מעלה בעבודת התשובה<sup data-n=\"55\">54</sup>, שדוקא על ידה גם ענינים של \"זדונות\" נהפכים לזכיות, כך שגם דברים תחתונים אלו (\"תחתון שאין תחתון למטה ממנו\") נעשים \"דירה\" לו ית'.\n<span data-k=\"q\">(משיחת ש\"פ חו\"ב תשמ\"ב) </span>",[["52","51","מובן שכ\"ז צ\"ל (דוגמתו) בתורה (ואסתכל באורייתא וברא עלמא), ועד להלכה פסוקה, והם: א) פס\"ד ב\"ד, ב) ב\"ד עונשין לצורך שעה אם רואים שהעם פרוצים בעבירות (טושו\"ע חו\"מ ס\"ב עיי\"ש)."],["53","52","אבל גם ענין זה הוא טעם לבריאת העולם בעשרה מאמרות (כפשטות הפירוש בהמשנה) — כי העילוי ב\"פרעון חוב\" הרשעים (ע\"י תשובה) מתבטא בזה שישנן המדידות כו' דהעשרה מאמרות, וע\"י עבודת התשובה הבע\"ת הם \"מאבדין את העולם שנברא בעשרה מאמרות\" (ביטול המדידות כו' שמצד העש\"מ). וראה בארוכה ד\"ה שובה תרנ\"ט (הנ\"ל הערה 6) ועוד, שהאהבה ד\"בכל מאדך\" באה על ידי המיצר דוקא (וראה שם בסוף המאמר \"ואם הי' נברא העולם במדה\"ד הי' העבודה התמידית בבחינת רצוא. . בבחינת ביטול כל עצמותו וכמו ענין התשובה כו'\")."],["54","53","רמב\"ם הל' תשובה פ\"ז ה\"ד, מברכות לד, ב. זח\"א שם."],["55","54","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380610\" data-slug=\"likkutei-torah\" data-id=\"4001380610\">לקו\"ת (בלק עג, סע\"א</a>. לקו\"ת ראה שם). ועוד, שזהו תכלית הכוונה בירידת הנשמה למטה שנעשה בחי' בע\"ת."]]],[1301410073,"<h3>שיחה ב</h3>\nא. עה\"פ<sup data-n=\"56\">1</sup> \"ויעש אלקים את שני המאורות הגדולים את המאור הגדול גו' ואת המאור הקטן גו'\" אי' בגמרא<sup data-n=\"57\">2</sup>: \"ר\"ש בן פזי רמי כתיב ויעש אלקים את שני המאורות הגדולים וכתיב את המאור הגדול ואת המאור הקטן (דמשמע שניהם גדולים וכתיב הקטן — רש\"י), אמרה ירח לפני הקב\"ה רבש\"ע אפשר לשני מלכים שישתמשו בכתר אחד (בתמי') אמר לה לכי ומעטי את עצמך\"<sup data-n=\"58\">3</sup>.\nוממשיך, שע\"ז טענה הלבנה \"רבש\"ע הואיל ואמרתי לפניך דבר הגון אמעיט את עצמי (בתמי') כו'\"<sup data-n=\"59\">4</sup>, וע\"ז פייס הקב\"ה את הלבנה בכמה אופנים, כדלקמן סעיף ג.\nוהנה לכאורה לא ברור אם טענת הלבנה (\"אפשר לשני מלכים שישתמשו בכתר אחד\") היתה טענה צודקת:\nמזה שטענת הלבנה נקראת בכמה מקומות בשם \"קטרוג\"<sup data-n=\"60\">5</sup> כלפי מעלה (כביכול), המורה על דבר בלתי רצוי, נראה לכאורה שלא היתה טענה צודקת. וכן משמע לכאורה מזה שהלבנה הוצרכה למעט את עצמה (שזהו \"עונש\" על טענתה, בלשון רש\"י<sup data-n=\"61\">6</sup> \"נתמעטה הלבנה על שקטרגה ואמרה אי אפשר כו'\"), ולא שינוי אחר מהשמש שאין בהשינוי עונש (דאת\"ל שצדקה בטענתה, אמאי נענשה?).\nאבל מהמשך דברי הגמ', שהקב\"ה פייס את הלבנה לאחר שטענה \"הואיל ואמרתי לפניך דבר הגון אמעיט את עצמי\", משמע, שתוכן טענתה הוא \"דבר הגון\" (לא רק בעיני הלבנה, אלא) לפי אמיתית הענין<sup data-n=\"62\">7</sup>.\nב. גם בתוכן הענין צריך ביאור:\nאת\"ל שטענה זו נכונה היא — תמוה ביותר: איך אפ\"ל שמלכתחילה ברא הקב\"ה את שני המאורות באופן שיש מקום לטענה (בצדק) שבריאתם אינה כראוי (שיהיו שני מלכים משתמשים בכתר אחד)? ובפרט שמפורש בחז\"ל<sup data-n=\"63\">8</sup> ש\"עולם על מליאתו נברא\", ואילו לפי דברי הלבנה נמצא, שתיכף בעת שנבראו הי' דבר בלתי מושלם בבריאת העולם ע\"י הקב\"ה.\n[ואף שאיתא במדרש<sup data-n=\"64\">9</sup> ש\"כל מה שנברא בששת ימי בראשית צריכים עשי' כגון החרדל צריך למתוק התורמוסים צריך למתוק החיטין צריכין להטחן אפילו אדם צריך תיקון\" — \"הדא הוא דכתיב<sup data-n=\"65\">10</sup> אשר ברא אלקים לעשות אשר ברא ועשה אין כתיב כאן אלא לעשות",[["56","1","פרשתנו א, טז."],["57","2","חולין ס, ריש ע\"ב."],["58","3","ראה לקמן הערה 54 השייכות לשנת העיבור (כשנה זו (דהדפסת השיחה) — תשמ\"ט)."],["59","4","וראה פדר\"א פ\"ו. פרש\"י עה\"פ. ועוד."],["60","5","פרש\"י עה\"פ. ועד\"ז במדרש כונן (נדפס באוצר מדרשים (אייזנשטיין) ח\"א ע' 254). וראה פדר\"א שם."],["61","6","פרשתנו עה\"פ."],["62","7","וכן מוכח מפשטות סיום הגמרא \"אמר הקב\"ה הביאו כפרה עלי שמיעטתי את הירח\"."],["63","8","ב\"ר פי\"ד, ז. וראה שם פי\"ב, ו. פי\"ג, ג (וביפ\"ת שם)."],["64","9","ב\"ר פי\"א, ו. — התיווך עם מרז\"ל שבהערה שלפנ\"ז נת' בארוכה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251014\" data-slug=\"likkutei-sichot\" data-id=\"1300251014\">לקו\"ש חכ\"ה ע' 14</a> ואילך."],["65","10","פרשתנו ב, ג."]]],[1301410074,"לומר שהכל צריך תיקון\"<sup data-n=\"66\">11</sup> — הרי פשוט שיש חילוק גדול בין הנבראים שנבראו לכתחילה באופן בלתי מתוקן בכוונה ועל מנת שהאדם יוסיף בתיקונם בכדי שיהיו מוכנים עבורו (כמו בדוגמא הנ\"ל שהחרדל צריך למיתוק וחיטים לטחינה) — ובין בריאת דבר שהקב\"ה עצמו הוצרך כביכול מיד לשנותו ולתקנו].\nועכצ\"ל שבריאת המאורות באופן ד\"שני המאורות הגדולים\" (\"שני מלכים משתמשים בכתר אחד\") אין בה שום חסרון (ואדרבה, כן צריך להיות, שלכן לעת\"ל שוב יהי' \"אור הלבנה כאור החמה\"<sup data-n=\"67\">12</sup>). וקשה, כנ\"ל — איך אפ\"ל שטענת הלבנה היא \"דבר הגון\"?\nג. ולאידך גיסא — יש להבין טענת הלבנה \"אפשר לשני מלכים שישתמשו בכתר אחד\" — שמשמעה שרצתה לעצמה כתר מלוכה גדול יותר:\nהחמה והלבנה נבראו במאמר השם \"יהי מאורות ברקיע השמים להבדיל<sup data-n=\"68\">13</sup> בין היום ובין הלילה גו' להאיר על הארץ\"<sup data-n=\"69\">14</sup> — ופשיטא שנשלם רצון הבורא בבריאתם, וכמש\"נ<sup data-n=\"70\">15</sup> \"וירא אלקים את כל אשר עשה והנה טוב מאוד\", שכל דבר שהקב\"ה בראו נעשה בהתאם למטרתו שבשבילה נברא<sup data-n=\"71\">16</sup>; וגם פשוט וברור שכל הברואים אין ענינם ומטרתם אלא להשלים רצון הבורא, וא\"כ איך יתכן, כפי שמשמע בפשטות, שהלבנה קינאה לכבודה ותבעה לעצמה כתר גדול יותר?\nוביותר תמוה: לאחרי שהקב\"ה אמר ללבנה \"לכי ומעטי את עצמך\", הוצרך לפייסה, כהמשך דברי הגמרא שאמר לה \"לכי ומשול ביום ובלילה\"; ולא עוד אלא שלא נתפייסה בזה וטענה \"שרגא בטיהרא מאי אהני\", והקב\"ה הוסיף לרצותה עוד: \"זיל לימנו בך ישראל ימים ושנים\"; וגם זה לא הספיק לה בטענה \"יומא נמי אי אפשר דלא מנו בי' תקופותא (תקופות נמנין לחמה ועל התקופה מעברין את השנה כו' — רש\"י) כו'\"! — דלכאורה טענה זו היא ממדת הקנאה הגרועה, דמאי איכפת לה שימנו התקופות בשמש, כיון שמשלה לא יוגרע כלום, ואדרבה, דוקא בה תלוי רובו ועיקרו של מנין הימים<sup data-n=\"72\">17</sup> — ועד כ\"כ, שלאחרי שאמר הקב\"ה \"זיל ליקרו צדיקי בשמיך כו'\" ו\"חזי' דלא קא מיתבא דעתה אמר הקב\"ה הביאו כפרה עלי שמיעטתי את הירח כו'\"!\nועכצ\"ל שמיעוט הלבנה הוא חלק",[["66","11","ל' (פירוש המיוחס ל)רש\"י לב\"ר שם."],["67","12","ישעי' ל, כו."],["68","13","וצ\"ע איך היתה ההבדלה קודם שנתמעטה הלבנה.\n— בבחיי פינחס (כח, טו קרוב לסופו) \"שהיו מתחלה שוין באורם ממש והי' אור הלבנה גדול כאור השמש ואח\"כ מעטה הבורא ית' לתועלת העולם ולישובם שאילו לא מעטה הי' הזמן כולו יום\". וצ\"ע לכאורה, שהרי מפורש בכתוב, שתחילת בריאת המאורות היתה כדי \"להבדיל בין היום ובין הלילה\".\nולהעיר, שלכמה מפרשים (ראה הנסמן לקמן הערה 19. בחיי פינחס שם. ועוד) \"אין הכוונה שהי' אור הלבנה בתחלת הבריאה גדול כאור השמש אלא שנבראו שניהם בגדלן (כמו שהם עתה)\", אלא שבתחילה נבראה הלבנה באופן \"שהי' השמש עלי' פנים בפנים\", ואח\"כ אמר לה הקב\"ה שגם \"האור הזה בעצמו הבא לך מהשמש. . בלכתך תהי מתמעטת\" (לשון הבחיי שם). ע\"ש.\nוראה לקמן בסוף הסעיף והערה *20."],["69","14","א, ידטו."],["70","15","א, לא."],["71","16","ראה מו\"נ ח\"ג פי\"ג. שם פכ\"ה."],["72","17","ראה מאמר שני המאורות (להרי\"א מהאמעל. דפוס צילום — קה\"ת, תשל\"ב) ח\"א סי\"ג ד\"ה אמרה לי'."]]],[1301410075,"מסדר ואופן<sup data-n=\"73\">18</sup> בריאת המאורות שבששת ימי בראשית<sup data-n=\"74\">19</sup>, כלומר: גם בתחילה היתה כוונת הבורא שיהיו באופן דמאור הגדול ומאור הקטן [וכלשון הכתוב \"ויעש אלקים את שני המאורות גו' את המאור הגדול גו' ואת המאור הקטן גו'\", שפשטות משמעות הכתוב היא<sup data-n=\"75\">20</sup>, שמלכתחילה נבראו שני המאורות בכוונה שיהי' אחד מהם גדול ואחד מהם קטן], אלא שסדר בריאתם הי' צ\"ל (כאילו נאמר) בשני שלבים, שמלכתחילה עשה אלקים \"שני המאורות הגדולים\", ואח\"כ ע\"י מיעוט הלבנה נתחלקו להיות מאור הגדול ומאור הקטן<sup data-n=\"76\">*20</sup>; אלא שהיות שהסיבה והצורך בשינוי זה הם מצד מציאות הלבנה (כדלקמן), לכן בא המיעוט ע\"י \"טענת\" הלבנה<sup data-n=\"77\">21</sup>.\nד. ויש לבאר זה בהקדם הידוע ד\"אסתכל בה באורייתא וברא עלמא\"<sup data-n=\"78\">22</sup>, שכל דבר ודבר שבעולם, מקורו בתורה (שהיא הדיפתראות<sup data-n=\"79\">23</sup> שמהן נברא העולם), שכן הוא גם במאורות הגדולים (השמש והלבנה), שישנם תחילה בתורה, ועל פי תוכנם כפי שהם בתורה, נמשך ונשתלשל ענינם בשמש ולבנה בגשמיות כפשוטם.\nולפ\"ז י\"ל, שאופן בריאת המאורות — שבתחילה נבראו בשווה, \"שני המאורות הגדולים\", ואח\"כ על ידי \"טענת\" הלבנה \"אי אפשר לשני מלכים שישתמשו בכתר אחד\" מיעטה הלבנה את עצמה — יובן ע\"פ ביאור תוכן ענין שמש ולבנה כפי שהם בתורה:\nמבואר בשל\"ה<sup data-n=\"80\">24</sup>, ששני המאורות (כפי שהם בתורה) הן תושב\"כ ותושבע\"פ, וכמרומז גם במדרש<sup data-n=\"81\">25</sup> עה\"פ<sup data-n=\"82\">26</sup> ויהי שם עם ה' מ' יום ומ' לילה, \"מנין הי' יודע משה אימתי יום אלא כשהקב\"ה הי' מלמדו תורה בכתב הי' יודע שהוא יום וכשהי' מלמדו על פה משנה ותלמוד הי' יודע שהוא לילה\".\nוטעם הדבר שתושבע\"פ נקראת \"המאור הקטן\", כי \"תורה שבע\"פ היא המקבלת מתושב\"כ וכמו שאמר בגמ' מנלן",[["73","18","ועד\"ז צ\"ל בכמה דברים כיו\"ב בוימ\"ב, כמו בעץ פרי (פרשתנו א, יא) שהיא לא עשתה כן אלא ותוצא הארץ וגו' עץ עושה פרי ולא העץ פרי לפיכך כו' נפקדה גם היא על עונה (פרש\"י שם מב\"ר פ\"ה, ט), או דברי אגדה בנוגע לויתן ובן זוגו (פרש\"י שם, כא. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051019\" data-slug=\"likkutei-sichot\" data-id=\"1300051019\">לקו\"ש ח\"ה ע' 19</a> ואילך ובהערות). ולפנ\"ז בכללות הבריאה, \"שבתחילה עלה במחשבה לבראותו במדת הדין וראה שאין העולם מתקיים והקדים מדת רחמים ושתפו למדת הדין\" (רש\"י בראשית א, א ד\"ה ברא. וראה ב\"ר פי\"ב, טו. מדרש אגדה עה\"פ) — ראה משכיל לדוד לפרש\"י שם."],["74","19","ראה גם תשובת הרשב\"א (הובאה בהכותב לע\"י שבועות ט, א). תורת העולה (להרמ\"א) ח\"ג פכ\"ב."],["75","20","ראה ראב\"ע פרשתנו עה\"פ. ריב\"א עה\"ת. ועוד."],["76","*20","ועפ\"ז מתורץ בפשטות מש\"נ \"יהי' מאורות גו' להבדיל בין היום ובין הלילה\", אף שבתחילה היו שניהם \"מאורות הגדולים\" — כי מלכתחילה נבראו בכוונה שתומ\"י אח\"כ ייעשו \"המאור הגדול. . המאור הקטן\", כבפנים."],["77","21","בביאור דברי הגמ' ראה מפרשי הש\"ס וע\"י שם. מפרשי הש\"ס וע\"י שבועות ט, א. חדושי אגדות מהר\"ל שם (ובאר הגולה באר הד' — ע' נד ואילך). בחיי פינחס כח, טו. תורת העולה שם ובפמ\"ט. פרדס שער מיעוט הירח. וע\"ד החסידות — אוה\"ת בראשית לז, א ואילך. סה\"מ אעת\"ר ע' קצט ואילך. מאמר שני המאורות הנ\"ל. ועוד."],["78","22","זח\"ב קסא, אב."],["79","23","ב\"ר בתחלתה."],["80","24","בהקדמה — טז, סע\"א (\"כבר כתבו חכמי האמת\"). במס' שבועות שלו (קצא, א). וראה לקו\"ת שה\"ש יא, ד. אוה\"ת בראשית יד, א. לו, סע\"ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830046\" data-slug=\"or-hatorah-hb\" data-id=\"8158830046\">במדבר ע' מו</a>. מג\"א ע' ב'שמא (בהוצאת תש\"נ — ע' קמט). נ\"ך ע' ריז. ועוד."],["81","25","תנחומא תשא לו."],["82","26","תשא לד, כח."]]],[1301410076,"דכתיב כו' או מנה\"מ דאמר קרא כו'\"<sup data-n=\"83\">27</sup>, כמו הלבנה המקבלת אור מהשמש [וגם ה\"דברים שגזרו חכמים ונביאים שבכל דור ודור\"<sup data-n=\"84\">28</sup> וכיו\"ב, הרי גם הם יסודם בכתוב<sup data-n=\"85\">29</sup> \"ושמרתם את משמרתי — עשו משמרת למשמרתי\" — \"לעשות סייג לתורה כמו ששמעו ממשה בפירוש\"<sup data-n=\"86\">30</sup>, היינו קיום הוראת משה בתושב\"כ לעשות סייג לתורה<sup data-n=\"87\">31</sup>].\nולפי זה יש לבאר הא שבתחילה נבראו \"שני המאורות הגדולים\" ואח\"כ נתמעטה הלבנה: זה שתושבע\"פ היא \"מקבל\" מתושב\"כ, הוא רק מצד בני ישראל, מקבלי התורה, שההלכות והציוויים שבתושבע\"פ ניתנו להם ללמוד מתושב\"כ ע\"י י\"ג מדות שהתורה נדרשת בהן וכיו\"ב [ומה גם \"הגזירות והתקנות והמנהגות\"<sup data-n=\"88\">32</sup> שעשאום חכמים סייג לתורה כו', שבודאי תלויים בבנ\"י, מקבלי התורה<sup data-n=\"89\">33</sup>];\nמשא\"כ מצד הקב\"ה, נותן התורה, אין תושבע\"פ בגדר \"מקבל\" מתושב\"כ, ושתיהן הן בגדר \"מאורות הגדולים\", ד\"כולם ניתנו מרועה אחד\"<sup data-n=\"90\">34</sup>, ובלשון הרמב\"ם<sup data-n=\"91\">35</sup> \"כל המצות כו' בפירושן ניתנו\" (מלמעלה), \"הי'<sup data-n=\"92\">36</sup> אומר לו המצוה [תושב\"כ<sup data-n=\"93\">37</sup>] ואח\"כ אומר לו השם פירושה וענינה\"<sup data-n=\"94\">38</sup>.\nה. בעומק יותר:\nזה שתושב\"כ ותושבע\"פ נקראות בשם \"שמש\" ו\"לבנה\" הוא לא רק מצד יחסם זל\"ז (שתושבע\"פ מקבלת מתושב\"כ), אלא (גם) מפני שבתושב\"כ מודגש גדר נותן התורה (שמש, משפיע), ובתושבע\"פ מודגש גדר מקבלי התורה (לבנה, מקבל).\nוכהחילוק בפשטות בין תושב\"כ ותושבע\"פ, שתושב\"כ ה\"ה כפי שנמסרה מסיני, בדיוק באותיותי' לא חסר ולא יתיר — שבזה מודגש שהיא תורת ה' (ואין בה תפיסת ידי אדם); משא\"כ תושבע\"פ גדרה הוא — הבנת האדם (דכשאינו מבין מה שלומד אינו נחשב לימוד כלל<sup data-n=\"95\">39</sup>),",[["83","27","לקו\"ת שה\"ש שם. וראה בהנסמן בהערה 24."],["84","28","ל' הרמב\"ם בהקדמתו לספר היד ד\"ה גם יתבאר. וראה רמב\"ם הל' ממרים פ\"א ה\"ב."],["85","29","אחרי יח, ל. מו\"ק ה, סע\"א. רמב\"ם בהקדמתו שם."],["86","30","ל' הרמב\"ם שם."],["87","31","ובכלל זה גם \"המנהגות והתקנות שהתקינו (ב\"ד הגדול) או שנהגו בכל דור ודור כמו שראו ב\"ד של אותו הדור\" (שהם בכלל תושבע\"פ) כל' הרמב\"ם בהקדמתו שם — ראה רמב\"ם הל' ממרים שם: ואחד הדברים שעשאום סייג לתורה ולפי מה שהשעה צריכה והן הגזירות והתקנות והמנהגות.\nוכן החיוב לשמוע להם הוא מצד המ\"ע בתורה על פי התורה אשר יורוך ואסור לסור מהם שנאמר לא תסור מן הדבר אשר יגידו לך ימין ושמאל (פ' שופטים יז, יא) — רמב\"ם בהקדמתו שם. הל' ממרים שם. וראה סהמ\"צ להרמב\"ם שורש א."],["88","32","רמב\"ם הל' ממרים שם."],["89","33","כי נוסף ע\"ז שהחכמים מקבלי התורה הם שגזרו והנהיגו והתקינו כו', הרי זה שנכללו בכלל תורה שבע\"פ ותוקף חיובן במ\"ע ובמל\"ת (כנ\"ל הערה 31) הוא מצד זה שפשט הדבר בכל ישראל (מקבלי התורה), כמבואר ברמב\"ם בהקדמתו שם ובהל' ממרים פ\"ב."],["90","34","לשון הש\"ס חגיגה ג, ב."],["91","35","בריש הקדמתו שם."],["92","36","רמב\"ם בהקדמתו לפירוש המשניות בתחלתה."],["93","37","בפרט ע\"פ תרגום קאפח שם \"אומר לו המקרא\"."],["94","38","ובתרגום קאפח: וכל מה שכלל אותו המקרא המחוכם (ולפנינו: וכל מה שהוא כולל ספר התורה). וראה בארוכה פיהמ\"ש שם, שמבאר בפרטיות מהו פירוש וביאור המקרא."],["95","39","הל' ת\"ת לאדה\"ז ספ\"ב (וש\"נ) — משא\"כ בתושב\"כ \"אע\"פ שאינו מבין אפילו פירוש המלות כו' ה\"ה מקיים מצות ולמדתם\" (הל' ת\"ת שם)."]]],[1301410077,"ועד שבנ\"י מחדשים בתורה, היינו שעניני תושבע\"פ באים ומתגלים על ידי בנ\"י.\nובזה יש לבאר דיוק לשון הרמב\"ם<sup data-n=\"96\">40</sup> (בנוגע לסדר המסורה דתורה): \"כל התורה כתבה משה רבינו כו' ונתן ספר לכל שבט ושבט כו' והמצוה שהיא פירוש התורה לא כתבה אלא צוה בה לזקנים וליהושע ולשאר כל ישראל כו' ומפני זה נק' תורה שבעל פה. אף על פי שלא נכתבה תורה שבעל פה למדה משה רבינו כולה בבית דינו לשבעים זקנים. ואלעזר ופינחס ויהושע שלשתן קבלו ממשה כו' וזקנים רבים קבלו מיהושע וקבל עלי מן הזקנים ומפינחס\", והולך ומונה פרטי מסורת התורה מדור דור, כל חכם ממי קבל, עד רבינו הקדוש שחיבר המשנה, ועד רב אשי שחיבר תלמוד בבלי כו'.\nולכאורה יש לדייק אמאי נקט הרמב\"ם בשלשלת המסורה דתושבע\"פ לא כמ\"ש גבי יהושע ד\"ליהושע שהוא תלמידו של משה רבינו מסר תורה שבע\"פ וצוהו עלי'\"<sup data-n=\"97\">41</sup>, אלא ע\"ד קבלת פלוני מפלוני, שלא כתב שפלוני מסר לפלוני אלא שפלוני קבל מפלוני. ומשמע מזה, שהחילוק בין תושב\"כ ותושבע\"פ הוא לא רק בזה שתושב\"כ \"כתבה משה רבינו\" ו\"המצוה שהיא פירוש התורה לא כתבה אלא צוה בה לזקנים כו'\", אלא גם בענין זה, שהמסורה דתושב\"כ היא באופן שמשה רבינו נתנה לכל שבט ושבט, ובתושבע\"פ ה\"ז בדרך קבלה, שכל החכמים שבכל דור מקבלים מהחכמים שבדור שלפנ\"ז.\nויש לומר, שזהו בהתאם לחילוק הנ\"ל בין תושב\"כ ותושבע\"פ — שבתושב\"כ מודגש גדר הנותן, ובתושבע\"פ מודגש גדר המקבל.\nו. אמנם, חילוק זה בין תושב\"כ ותושבע\"פ הוא רק מצד בני ישראל, מקבלי התורה, אבל מצד הקב\"ה, נותן התורה, הרי גם תושבע\"פ היא תורת ה' ממש כמו תושב\"כ, בלי כל חילוק ביניהן באופן נתינתן.\nוזהו שהרמב\"ם מקדים שם<sup data-n=\"96\">40</sup> \"כל המצות שניתנו לו למשה בסיני בפירושן ניתנו שנאמר<sup data-n=\"99\">42</sup> ואתנה לך את לוחות האבן והתורה והמצוה תורה זו תורה שבכתב והמצוה זו פירושה וצונו לעשות התורה על פי המצוה ומצוה זו היא הנקראת תורה שבעל פה\", והיינו, שהחילוק הנ\"ל בין תושב\"כ ותושבע\"פ, נתינה או קבלה, הוא רק מצד בנ\"י, אבל מצד הקב\"ה ניתנו שתיהן בשווה. ובלשון אאמו\"ר ז\"ל<sup data-n=\"100\">43</sup> \"שכל מה שנאמר בתושב\"כ ובתושבע\"פ הן בהלכה והן באגדה ובכל הספרים שחיברום חכמים צדיקים שלמדו תורה לשמה. . כולם ממש אמר ה' ובאותו הלשון ממש<sup data-n=\"101\">44</sup> שנאמרו כמו שהוא ממש\"<sup data-n=\"102\">45</sup>.",[["96","40","בריש הקדמתו לספר היד שם."],["97","41","ל' הרמב\"ם שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231201\" data-slug=\"likkutei-sichot\" data-id=\"1300231201\">לקו\"ש חכ\"ג ע' 201</a> ואילך, החידוש שבזה בנוגע ליהושע. אבל חידוש זה הוא רק בשייכות ליהושע ולא במסורת התורה, דהרי בנוגע לעלי כ' הרמב\"ם \"וקבל עלי מן הזקנים (ומוסיף) ומפינחס\", אף שגם פינחס רק קבל ממשה ולא מסר לו משה תושבע\"פ."],["96","40","בריש הקדמתו לספר היד שם."],["99","42","משפטים כד, יב (וראה שמו\"ר רפמ\"ז. פרש\"י עה\"פ)."],["100","43","לקוטי לוי\"צ — אגרות קודש ע' רסו."],["101","44","ובמחז\"ל שתוכנם שווה ממש והלשון בסגנון דתנא פ' או תנא פ' — ב' הלשונות נתנו בקבלה. ולכאורה כן הוא בכו\"כ נבואות (ראה סנהדרין פט, א ובפרש\"י שם. וראה עיקרים מ\"ג פ\"ט. ועוד)."],["102","45","ואפילו הלכה שעלי' אמרו אח\"כ שבדותא היא. ע\"ש בארוכה."]]],[1301410078,"אלא שכיון שענינה של תושבע\"פ הוא \"פירושה\" של תושב\"כ, לכן, כפי שהתורה מתקבלת בנתינה למטה לבנ\"י — שבהשגתם ותפיסתם הרי \"פירושו\" של דבר הוא למטה מעצם הדבר, וענינו רק להסביר תוכנו [וכמו רב הלומד עם תלמידו וצריך לפרש את תוכן דבריו, שה\"פירוש\" אינו עצם השכל הטמון בדבריו (כמו שהוא אצל הרב), אלא זהו מה שהרב מצמצם את שכלו לדרגת התלמיד כדי שהתלמיד יוכל לקבלו ולהבינו בשכלו] — הנה אז התושבע\"פ היא בגדר \"מקבל\" מתושב\"כ, וענינה הוא — \"קבלת\" בנ\"י, ועד שגילוי תושבע\"פ הוא על ידי בנ\"י<sup data-n=\"103\">*45</sup> כנ\"ל בארוכה<sup data-n=\"104\">46</sup>.\nז. והנה ככל הדברים האלה ב\"שמש\" ו\"ירח\" שבתורה — כן הוא גם בשמש וירח המאירים לארץ בפשטות, דזה שיש חילוק בין שני המאורות, \"המאור הגדול\" (משפיע האור) ו\"מאור הקטן\" (מקבל האור), זהו רק כפי שהם בעולם (\"מצד המקבל\"), אבל מצד מעשה של הקב\"ה, \"ויעש אלקים\", שניהם הם בגדר \"מאורות הגדולים\", \"שווים נבראו\"<sup data-n=\"105\">47</sup>, ואין אחד מהם גדול מחברו.\nובפשטות: זה שאור הלבנה מתהווה ונוצר מאור השמש, הוא רק כפי שהוא מצד גדרי העולם, אבל מצד הקב\"ה, הרי (אור) הלבנה הוא בריאתו של הקב\"ה בשווה ממש ל(אור) השמש — \"ויעש אלקים את שני המאורות הגדולים\"<sup data-n=\"106\">48</sup>; אלא שכיון שגדרו של אור הלבנה הוא — אור של מקבל, לכן, אור זה בא בפועל ובגלוי באמצעות השמש<sup data-n=\"107\">49</sup>.\n[וע\"ד המבואר בענין עשיר ועני<sup data-n=\"108\">50</sup> (שהם בדוגמת שמש וירח, משפיע ומקבל) — דזה שהעני מקבל מזונו מן העשיר, אינו מפני שבעצם הוא למטה ממנו וצריך אליו, אלא שהקב\"ה מזמין לו פרנסתו באמצעות העשיר; והיינו דהיות שהקב\"ה רוצה שתהי' מצות צדקה<sup data-n=\"109\">51</sup>, לכן ברא את העולם באופן כזה שיהי' משפיע ומקבל, עשיר ועני —",[["103","*45","ע\"פ המבואר בפנים יש לבאר ל' חז\"ל (ראה הנסמן בלקו\"ש חי\"ט ע' 252 הערה 20, 21) \"כל מה שתלמיד ותיק עתיד לחדש ניתן למשה מסיני\" — דלכאורה, כיון שגם חידוש זה כבר ניתן למשה בסיני, מדוע נקרא (באמת) בשם \"חידוש\"? וע\"פ הנ\"ל י\"ל, כי זוהי הנפק\"מ בין גדר \"נותן\" וגדר \"מקבל\" שבתורה: מצד גדרי המקבל (כפי שהתורה ניתנה למטה ונלמדת על ידי בנ\"י), ה\"ז \"חידוש\" של התלמיד ותיק, אבל מצד הקב\"ה, נותן התורה, ניתן גם חידוש זה ממש כמו שניתנה תושב\"כ."],["104","46","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191399\" data-slug=\"likkutei-sichot\" data-id=\"1300191399\">לקו\"ש חי\"ט ע' 386</a> ואילך. \"הדרן\" על מס' ברכות ומו\"ק בסה\"ש תשנ\"ב ח\"ב ע' 508 ואילך."],["105","47","ל' רש\"י (וראה פדר\"א) שבהערה 4."],["106","48","כלומר: זה גופא שצריך להיות אור של \"מקבל\" יש בו \"גדלות\" ומעלה שווה למעלת וגדלות אור המשפיע. וכ\"ה גם בתורה, שלא רק שגם דברי התושבע\"פ הם מלמעלה כמו תושב\"כ, אלא שגם ענין הקבלה שבהם הוא מלמעלה כמו ענין הנתינה בתושב\"כ."],["107","49","המבואר בפנים הוא להפירוש (וראה הנסמן בהערה 19) שגם לפני מיעוט הירח קיבלה הלבנה אורה מהשמש, אלא שאז הי' האור שלה אור גדול כמו אור השמש — ראה ספר הערכיםחב\"ד ח\"ג ע' שיב ואילך. וש\"נ (וראה לעיל הערה 13, *20 — במה הובדל אז הלילה).\nוראה שם, שיש דיעות שאז היתה הלבנה \"מאור\" כמו השמש ולא קיבלה כלל מהשמש, ומה שאמרו (ראה זח\"א רמט, ב. ח\"ב רטו, א. ועוד) סיהרא לית לה מגרמה כלום — נעשה רק לאחרי מיעוט הירח [ובכ\"מ מבואר (ראה שם ע' רצז. וש\"נ) שהכוונה ב\"לית לה מגרמה כלום\" היא, שהאור שלה אינו מאיר, ובכדי שהלבנה תאיר צריכה היא לקבל מהשמש. ע\"ש]."],["108","50","סה\"מ תרכ\"ז ע' שצט ואילך. סה\"מ קונטרסים ח\"א קיט, א ואילך."],["109","51","ראה תנחומא משפטים ט. שמו\"ר פל\"א, ה. ולהעיר מאוה\"ת פרשתנו שם לו, ב (אות ד)."]]],[1301410079,"והעשיר נותן צדקה להעני, ונמצא שלאמיתו של דבר אין העני מקבל מן העשיר אלא מהקב\"ה (כי \"מה שנותן העשיר לעני אין זה שלו כלל אלא הוא ג\"כ של ה'\"<sup data-n=\"110\">52</sup>), ורק מצד גדרי העולם עובר מזונו על ידי העשיר].\nוזהו הפירוש בטענת הלבנה \"אפשר לשני מלכים שישתמשו בכתר אחד\": מצד כוונת הקב\"ה בהבריאה, הנה מציאות \"המקבל\" (לבנה) היא היא הדורשת שאור המקבל יבוא באמצעות המשפיע [וכנ\"ל, שמצד גדרי העולם, הרי המקבל למטה מן המשפיע ומקבל ממנו], ומשום הכי צריך להיות מיעוט הירח, באופן שנעשה \"מאור הקטן\", המקבל אורו מן השמש.\nח. אמנם זה שנעשה מאור הקטן אין זו התכלית והמטרה, אלא שעי\"ז יגיע לשלימותו, שתתגלה בו עשייתו של הקב\"ה, שיהיו \"שני המאורות הגדולים\", וזה יתקיים בפועל לעת\"ל, שאז יהי' \"אור הלבנה כאור החמה\"<sup data-n=\"67\">12</sup>.\nוזהו ביאור המשך השקו\"ט בדברי הגמ' — \"אמרה לפניו רבש\"ע הואיל ואמרתי לפניך דבר הגון אמעיט את עצמי אמר לה לכי ומשול ביום ובלילה א\"ל מאי רבותי' דשרגא בטיהרא מאי אהני א\"ל זיל לימנו בך ישראל ימים ושנים וכו'\"; לאחרי מיעוט (אור) הירח — צריכים להדגיש את תכלית הכוונה באור המקבל, שאין הכוונה שישאר במיעוט אורו<sup data-n=\"112\">*52</sup>, אלא שיבוא ויגיע עי\"ז להיות \"מאור הגדול\", \"אור הלבנה כאור החמה\".\nוזהו תוכן ענין הפיוס של הקב\"ה — \"לכי ומשול ביום ובלילה כו' זיל לימנו בך ישראל ימים ושנים כו' זיל ליקרו צדיקי בשמיך\" — שכדי שיודגש באופן גלוי שכל המטרה של מיעוט הירח הוא רק כדי שעי\"ז תבוא סו\"ס להיות \"כאור החמה\", ששוב יהיו \"שני המאורות הגדולים\", יש בה גם עתה ענינים של \"גדלות\"<sup data-n=\"113\">53</sup> (\"לכי ומשול כו' לימנו בך<sup data-n=\"114\">54</sup> כו' ליקרו צדיקי כו'\"): ובכ\"ז \"לא קא מיתבא דעתה, אמר הקב\"ה הביאו כפרה",[["110","52","מאמרים שבהערה 50 — ע\"פ מחז\"ל (ב\"ב י, א) עה\"פ מלוה ה' חונן דל. וראה גם טיו\"ד סרמ\"ז \"יש לו לדעת שאין הממון שלו אלא פקדון לעשות בו רצון המפקיד. . שיחלק לעניים\"."],["67","12","ישעי' ל, כו."],["112","*52","וזהו פירוש \"טענת\" הלבנה \"הואיל ואמרתי לפניך דבר הגון אמעיט את עצמי\", שהמקבל צריך להרגיש שאין הכוונה שישאר בדרגא של מיעוט כו'."],["113","53","היינו לא \"גדלות\" במובן של \"השפעה\" (הגדול ב\"המאור\"), אלא גדול ועילוי של מקבל, כמודגש במ\"ש \"זיל לימנו בך ישראל ימים ושנים\", שזהו מה שבנ\"י (מקבל) פועלים ומחדשים בזמן — קידוש חדשים ועיבור שנים (אף שמנין הימים ושנים הוא לכאורה דבר הנעשה מעצמו, ע\"י הזמן שנברא מלמעלה);\nועד\"ז ב\"זיל ליקרו צדיקי בשמיך יעקב הקטן כו'\", שהכוונה בזה, שאמיתית המעלה ד\"צדיק\" שייכת ל\"קטנות\" (צמצום) דוקא, ולא העילוי בענין האור והגילוי.\nוגם הענין הא' — \"לכי ומשול ביום ובלילה\", אין הכוונה שהירח יאיר כמו מאור הגדול (ראה תורת העולה שם), אלא להדגיש שמעלת המקבל אין ענינה בענין האור שמאיר (שזה נראה רק בלילה), אלא במעלה עצמית שיש בו גם ביום כאשר אין אורו מאיר. וראה בדרושים הנ\"ל הערה 21. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301550119\" data-slug=\"likkutei-sichot\" data-id=\"1301550119\">לקו\"ש חל\"ד ע' 48</a> ואילך. סה\"ש תשנ\"ב ח\"א ע' 157 ואילך."],["114","54","ולהוסיף, שהצורך בעיבור שנים — שבא להשוות שני לבנה לשני חמה (ע\"ד \"שני המאורות הגדולים\"*) — תלוי ב\"לימנו כו' ושנים\" (מנין השנים ללבנה). ולהעיר משל\"ה חלק תושב\"כ ר\"פ שמות (שו, ב) \"אם לא הי' ענין מיעוט הירח לא הי' עולמים שום עיבור כי. . הי' סיבובם ומהלכם שוה\". וראה גם עתים לבינה (מאמר ז)."]]],[1301410080,"עלי שמיעטתי את הירח\", והיינו להדגיש שכל זמן שהיא בגדר \"מאור הקטן\", שהלבנה היא בגדר מיעוט, צריכים עדיין ל\"כפרה\" על מיעוטה, עד שתושלם הכוונה בגלוי לעתיד לבוא, \"והי' אור הלבנה כאור החמה\"<sup data-n=\"67\">12</sup>, שיהיו \"שני המאורות הגדולים\" בגלוי ובפועל<sup data-n=\"116\">55</sup>.\n<span data-k=\"q\">(משיחת יום ב' דחג השבועות תשמ\"ז) </span>",[["67","12","ישעי' ל, כו."],["116","55","ראה בארוכה ספר הערכיםחב\"ד ח\"ג ע' שיד ואילך (וש\"נ) — שני האופנים (א) שיהיו שווים בגודל האור, (ב) שגם הלבנה יהי' לה אור של עצמה (ע\"ד שני האופנים דלעיל הערה 49). ע\"ש."]]],[1301410081,"<h3>שיחה א</h3>\nא. איתא במדרש<sup data-n=\"117\">1</sup>: \"מתחילת ברייתו של עולם לא הי' קלוסו של הקב\"ה עולה אלא מן המים\", ולאחרי ש\"עמד דור המבול ומרד בו. . אמר הקב\"ה יפנו אלו ויעמדו ויבואו אותן שישבו בהן מקודם הדא הוא דכתיב<sup data-n=\"118\">2</sup> ויהי הגשם על הארץ ארבעים יום וארבעים לילה\".\nלפי זה מובן, שמצבו של העולם בהיותו מוצף במי המבול דומה למצבו ב\"תחילת ברייתו\"<sup data-n=\"119\">3</sup>, שאז הי' \"כל העולם כולו מים במים\"<sup data-n=\"120\">4</sup>, שזהו עילוי גדול ביותר — עולם המקלס את הקב\"ה (ש\"קלוסו של הקב\"ה\" עולה מן המים דוקא).\nולכאורה דורש ביאור: איך מתאים ענין זה שבמי המבול עם תוכן ענינם בפשטות, שבאו \"לשחת כל בשר\"<sup data-n=\"121\">5</sup>?\nבפירוש רש\"י<sup data-n=\"122\">6</sup> מצינו, ד\"כשהורידן הורידן ברחמים אם יחזרו יהיו גשמי ברכה וכשלא חזרו היו למבול\" — הרי שהורדת המים היתה \"ברחמים\", שיהיו \"גשמי ברכה\"<sup data-n=\"123\">7</sup>. אמנם, זה הי' רק בתחילה ובאופן של תנאי — באם \"יחזרו\" אנשי דור המבול ויעשו תשובה (אז לא ישחיתו המים את הארץ, אלא יהיו \"גשמי ברכה\")<sup data-n=\"124\">8</sup>, וכיון שלא חזרו בתשובה, לא היו המים \"גשמי ברכה\" אלא מי מבול; משא\"כ לפי דברי המדרש יוצא, שגם בפועל, כשמי המבול הציפו וכסו את העולם, הי' בזה ענין למעליותא.\nידוע גם ביאורו של אדמו\"ר הזקן<sup data-n=\"125\">9</sup>, שמי המבול באו לא רק להעניש את דור המבול, אלא גם כדי \"לטהר את הארץ\", כמו טהרה על ידי מקוה [שלכן ירד הגשם ארבעים יום, כמו מקוה ששיעורה ארבעים סאה].\nאמנם גם לפי ביאור זה, הרי פעולת מי המבול — טהרת העולם — קשורה עם החטאים של דור המבול, שהביאו טומאה בעולם<sup data-n=\"126\">10</sup>, ועל ידי המבול נטהר העולם מטומאה זו;\nאבל לפי המדרש, שמצבו של העולם בהיותו מכוסה במי המבול הוא בדומה למצב העולם בתחילת הבריאה, כאשר הי' \"כל העולם כולו מים במים\" — הרי המבול פועל לא רק שלילת והסרת הטומאה, אלא גם ענין חיובי שהוא טוב",[["117","1","ב\"ר פ\"ה, א. ועד\"ז באיכ\"ר פ\"א, נב."],["118","2","פרשתנו ז, יב."],["119","3","וכהלשון באיכ\"ר שם: יחזור העולם לכמו שהי'. וראה רש\"י לב\"ר שם: הגשם כלומר אותו הגשם שהי' משי\"ב."],["120","4","ב\"ר שם, ב. וש\"נ. ירושלמי חגיגה פ\"ב ה\"א (בתחלתה)."],["121","5","פרשתנו ו, יז."],["122","6","פרשתנו ז, יב (מזהר חדש (מהנ\"ע) פרשתנו (כב, סע\"א). וראה ב\"ר פל\"א, יב)."],["123","7","ועפ\"ז יומתק שגם במדרש הנ\"ל (בתחלת הסעיף) הובא הכתוב \"ויהי הגשם גו'\" (וראה מפרשי המדרש שם) — לרמז שהו\"ע של \"גשמי ברכה\"."],["124","8","וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251023\" data-slug=\"likkutei-sichot\" data-id=\"1300251023\">לקו\"ש חכ\"ה ע' 23</a> ואילך."],["125","9","תו\"א ריש פרשתנו (ח, סע\"ג ואילך). וראה שם י, רע\"א. מאמרי אדה\"ז — הנחות הר\"פ (ע' סט). תו\"ח שם (נט, ב ואילך). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560286\" data-slug=\"or-hatorah-hb\" data-id=\"8316560286\">אוה\"ת שם (כרך ג) תרט, ב</a> ואילך. תרכד, א ואילך. ועוד.\nובאוה\"ת בראשית (כרך ז) תתשנה, ב ואילך (סה\"מ תרכ\"ז ע' ז), מקשר ביאור אדה\"ז בענין המבול עם דברי המדרש שבפנים. ע\"ש."],["126","10","בל' התו\"א ריש פרשתנו (ועוד), שהארץ \"נתקלקלה מאד\"."]]],[1301410082,"וקדושה בעצם<sup data-n=\"127\">11</sup> — וכמו שהי' מצבו של העולם (ד\"כל העולם כולו מים במים\") בתחילת ברייתו, שלא הי' בקשר לאיזה ענין של חטא (גם לא טהרה מחטא), שהרי עדיין לא היתה שום מציאות של חטא בעולם, וכל ענינו הי' רק \"קלוסו של הקב\"ה\".\nב. ויש לומר, שבדברי המדרש האלה נרמז ענין יסודי וכללי בשייכות לתורה — ובהקדמה:\nידוע מאמר חז\"ל<sup data-n=\"128\">12</sup> שהתורה היא מהדברים ש\"קדמו לעולם\", וכאמרם<sup data-n=\"129\">13</sup> \"אלפיים שנה קדמה תורה לעולם\". כלומר, למרות שאין מקרא יוצא מידי פשוטו<sup data-n=\"130\">14</sup>, ו\"פשוטן\" של דברי תורה הוא כפי שהתורה נלמדת בעולם הזה הגשמי דוקא — מ\"מ \"קדמה תורה לעולם\", כי בכל תיבה ותיבה שבתורה יש (גם) פירוש פנימי ורוחני, כפי שהתורה נלמדת בעולמות עליונים רוחניים (שלמעלה מעלה מענינים גשמיים).\nומובן, שכלל זה חל לא רק על ציוויי התורה, אלא גם על סיפורי התורה. דעם היות שכל סיפור שבתורה אירע בפשטות בכל פרטיו כפי המסופר בתורה, מ\"מ, מכיון שהתורה קדמה לעולם, עכצ\"ל שגם סיפורי התורה מכילים תוכן רוחני<sup data-n=\"131\">15</sup> בהתאם למציאות התורה בעולמות עליונים<sup data-n=\"132\">16</sup>.\n[ואדרבה — כמאמר הידוע<sup data-n=\"133\">17</sup>, שהתורה \"מדברת בעצם בעליונים ורומזות בשניות בתחתונים\": לא רק שדברי תורה יכולים להתפרש גם לפי תוכנם הרוחני (כפי שהתורה היא \"בעליונים\"), כ\"א להיפך: מקור והתחלת התורה הוא \"בעליונים\" (כמש\"נ<sup data-n=\"134\">18</sup> \"ואהי' אצלו גו' שעשועים גו'\", וכמחז\"ל<sup data-n=\"135\">19</sup> \"חמדה גנוזה שגנוזה לך\", ועוד), ומשם \"ירדה\" ונשתלשלה התורה עד למטה ובגשמיות (בל' הכתוב<sup data-n=\"136\">20</sup> מן השמים דברתי עמכם; מן השמים השמיעך את קולו גו'), ולכן, \"בעצם\" מדברת התורה בעליונים וברוחניות, אלא כש\"יורדת\" למטה בעוה\"ז, ניתנה להתפרש בפירושה הפשוט כפי שהוא \"בתחתונים\"].\nונמצינו למדים ענין נוסף: מכיון שאצל הקב\"ה \"לא יגורך רע\"<sup data-n=\"137\">21</sup> — עכצ\"ל, שגם ענינים אלו שבתורה שלפי פירושם הפשוט (\"בתחתונים\") הם ענינים בלתי רצויים (מעשים לא טובים, עונשים וכיו\"ב), הרי בתורה כפי שהיא בעליונים (שלא יתכן בהם מציאות של רע) מתפרשים המה באופן שכולם קודש וטוב<sup data-n=\"138\">22</sup>.",[["127","11","ורק סיבת המבול היא מצד החטאים דדור המבול (שלכן אמר הקב\"ה \"יפנו אלו\"), אבל המצב של מבול (מה ש\"יבואו אותן שישבו בהן מקודם\") הו\"ע טוב בתכלית."],["128","12","שבת פח, ב. פסחים נד, א. ב\"ר פ\"א, ד (וראה שם, א). ועוד."],["129","13","ראה מדרש תהלים צ, ג. תנחומא וישב ד. ועוד."],["130","14","שבת סג, א. וש\"נ."],["131","15","ולהעיר ג\"כ ממ\"ש הצפע\"נ (מכתבי תורה מכתב צט) ד\"כל מה דכתוב בתורה הוא דין לא ח\"ו סיפור\". וראה זח\"ג קנב, א. ע\"ש. וראה ג\"כ פיהמ\"ש להרמב\"ם שצויין בהערה 23."],["132","16","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380173\" data-slug=\"likkutei-torah\" data-id=\"4001380173\">לקו\"ת תזריע כג, ב</a> ואילך."],["133","17","עשרה מאמרות מאמר חקור דין ח\"ג פכ\"ב. וראה של\"ה יג, ב ואילך."],["134","18","משלי ח, ל."],["135","19","שבת פח, ב."],["136","20","יתרו כ, יט. ואתחנן ד, לו."],["137","21","תהלים ה, ה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו\"ת במדבר ג, ג</a>. אוה\"ת (יהל אור) עה\"פ."],["138","22","ראה ג\"כ בארוכה סה\"מ עטר\"ת (ע' תקטו ואילך). ועוד. — ולהעיר גם מהמבואר, שלעת\"ל בגמר הבירורים — כל ענין עסק התומ\"צ יהי' רק בקדושה גופא, ליחד יחודים כו' (תניא אגה\"ק סוסכ\"ו. קו\"א סד\"ה ולהבין פרטי ההלכות ועוד)."]]],[1301410083,"ולהעיר מדברי הרמב\"ם<sup data-n=\"139\">23</sup> ד\"אין הפרש בין. . ותמנע היתה פילגש<sup data-n=\"140\">24</sup>, ובין אנכי ה' אלקיך ושמע ישראל<sup data-n=\"141\">25</sup>, כי הכל מפי הגבורה, והכל תורת ה' תמימה טהורה וקדושה אמת\": אף שפשטות המכוון בתיבות אלו (\"תמנע היתה פלגש\") הוא לאשה שהיתה בתכלית הירידה כו' (עד שלידתה היתה באופן דהיפך קיום שבע מצות ב\"נ<sup data-n=\"142\">26</sup>) — קצה ההפכי בתכלית מקדושת \"אנכי ה\"א\" — מ\"מ אין זה נוגע לקדושת תיבות אלו כמו שנכתבו בתורה, עד שאין הפרש כלל בין קדושת תיבות אלו לקדושת התיבות \"אנכי ה\"א\", ד\"הכל תורת ה' תמימה טהורה וקדושה אמת\". כי אין הנידון מציאותה של \"תמנע\", כ\"א הדיון בתורה אודותה, ודיון זה שבתורה הוא תמים טהור וקדוש באמת.\nוכ\"ש וק\"ו כפי שהתורה היא \"בעליונים\", ששם הענין ד\"תמנע היתה פלגש\" מעיקרא אינו אלא ענין רוחני הנמצא בעולם שכולו קדושה (מכיון דשם \"לא יגורך רע\").\nג. יסוד זה מבאר ג\"כ סיפור, לכאורה תמוה, אודות קריאת ה\"תוכחה\" (שבפ' תבוא) ע\"י אדמו\"ר הזקן:\nמסופר<sup data-n=\"143\">27</sup>:\nרבינו הזקן הי' בעצמו הקורא בתורה. פעם אחת לא הי' בליאזנא ש\"פ תבוא, ושמע אדמו\"ר האמצעי — והוא עודנו נער קודם הבר מצוה — הקריאה מאחר. העגמת נפש מהקללות שבתוכחה הביאתו לכאב לב, עד שביוהכ\"פ נסתפק רבינו הזקן אם יוכל להתענות. כששאלו את אדמו\"ר האמצעי, הרי בכל שנה קוראים פרשה זו, ענה: כשאבא קורא \"הערט זיך ניט קיין קללות\".\nולכאורה דורש ביאור: כאשר רבינו הזקן קרא בתורה — בתכלית הדיוק בכל התיבות והאותיות עם הנקודות וטעמים כו' — בודאי נשמע תוכנה של הקריאה כפשוטו (בהתאם להכלל<sup data-n=\"130\">14</sup> \"אין מקרא יוצא מידי פשוטו\") — ומהו, איפוא, הפירוש בדברי אדהאמ\"צ \"כשאבא קורא הערט זיך ניט קיין קללות\"?\nוהביאור — ע\"פ הנ\"ל: ענין הקללות במובנן הפשוט הוא רק כפי שהענין נלמד למטה בעולם הפשט. אמנם כפי ש\"התורה מדברת בעליונים\", בעולם שכולו קדושה שאין לה שייכות למציאות של רע (ובמילא גם לא להעונש על רע) — הנה גם ענינים אלו (הקללות) תוכנם אך ורק קדושה וברכה.\n[וכפי שמפרש אדה\"ז<sup data-n=\"145\">28</sup> לענין הקללות דפ' בחוקותי, ש\"לפי האמת אינם רק ברכות\", ומביא הצ\"צ<sup data-n=\"146\">29</sup> דוגמא לזה מהסיפור המובא בש\"ס<sup data-n=\"147\">30</sup>, דרשב\"י שלח בנו לתנאים שנזדמנו במקומו שיברכוהו, אמנם הם ברכוהו \"בלשון קללה\"<sup data-n=\"148\">31</sup> והי' מצטער מזה. וכשחזר דברי התנאים לפני אביו אמר לו \"הנך כולהו ברכתא נינהו\"<sup data-n=\"149\">32</sup>].",[["139","23","פיהמ\"ש סנה' פ' חלק היסוד הח' (מסנהדרין צט, ב)."],["140","24","וישלח לו, יב."],["141","25","יתרו כ, ב (ואתחנן ה, ו). ואתחנן ו, ד."],["142","26","פרש\"י וישלח שם."],["143","27","\"היום יום\" יז אלול."],["130","14","שבת סג, א. וש\"נ."],["145","28","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380282\" data-slug=\"likkutei-torah\" data-id=\"4001380282\">לקו\"ת בחוקותי מח, סע\"א</a> ואילך. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450622\" data-slug=\"or-hatorah-hb\" data-id=\"8316450622\">אוה\"ת תבא ע' תתרצב</a> ואילך."],["146","29","בהגהות ללקו\"ת שם (מח, ב). ע\"ש. — ולהעיר ג\"כ מרשימות הצ\"צ לאיכה (באוה\"ת לנ\"ך ח\"ב), שמפרש הפסוקים דאיכה למעליותא (ע\"ש באורך). ועוד."],["147","30","מו\"ק ט, סע\"א ואילך."],["148","31","ל' המהרש\"א בחדא\"ג מו\"ק (שם, ב ד\"ה א\"ל יהא)."],["149","32","ואי\"ז כענין היסורים, ד\"גם זו לטובה רק שאינה נראית ונגלית לעיני בשר כי היא מעלמא דאתכסי'\" (<a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>) — כי שם, מה שהאדם מרגיש הוא יסורים, משא\"כ בהמדובר בפנים, שמלכתחילה \"כולהו ברכתא נינהו\" בגלוי ממש."]]],[1301410084,"ולכן, כאשר אדמו\"ר הזקן הי' קורא בתורה, הי' נשמע בקריאתו (אצל אדמו\"ר האמצעי) תוכן פירוש הדברים כפי ש\"התורה מדברת בעליונים\", ששם (גם) פ' התוכחה היא מעיקרא ענין שכולו טוב וברכה.\n[ויומתק ע\"פ מה דמפרש אדמו\"ר הזקן<sup data-n=\"150\">33</sup> את הלשון \"קורא בתורה\" — \"שע\"י עסק התורה (האדם) קורא להקב\"ה לבוא אליו כביכול כאדם הקורא לחבירו שיבא אליו וכבן קטן הקורא לאביו לבא אליו להיות עמו בצוותא חדא\"<sup data-n=\"151\">34</sup> — וכן בעניננו, שע\"י קריאת התורה של אדמו\"ר הזקן, קרא והמשיך התורה כפי שהיא בעליונים, אצל הקב\"ה<sup data-n=\"152\">35</sup> (דשם \"לא יגורך רע\", כנ\"ל)].\nד. ועד\"ז הוא הביאור בדברי המדרש אודות מי המבול:\nזה שהמבול בא להעניש את אנשי דור המבול, וגם לטהר את הארץ מטומאת חטאי דור המבול, ה\"ז רק כפי שהענין הוא למטה וכפשוטו; אמנם מכיון שענין המבול מסופר בתורה — בהכרח לומר שענין המבול לכל פרטיו ישנו ג\"כ בתורה כפי שהיא \"בעליונים\", ב\"עולם\" שלא שייך בו שום ענין של רע וחטא.\nוזהו מה שמשמיענו המדרש, שהמציאות של מי המבול על פני כל הארץ<sup data-n=\"153\">36</sup> הוא (גם) ענין שכולו קדושה<sup data-n=\"154\">37</sup> — דוגמא ל\"תחילת ברייתו של עולם\", כאשר \"כל העולם כולו מים במים\", כי \"לא הי' קלוסו של הקב\"ה עולה אלא מן המים\".\nויש לומר, שזהו התוכן הפנימי בביאור אדה\"ז הנ\"ל שמי המבול היו בדוגמא למי מקוה<sup data-n=\"155\">38</sup> — שכן מצינו טבילה במקוה שהיא אך לתוספת קדושה (ולא כדי לטהר מטומאה) [כמו טבילות של הכהן גדול ביוהכ\"פ, שאחרי הטבילה הראשונה כבר נטהר מכל חשש טומאה<sup data-n=\"156\">*38</sup>, וכולו הן רק לתוספת קדושה, שעולה מדרגא לדרגא בקדושה גופא],",[["150","33","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא ספל\"ז</a>."],["151","34","ביאור ב' הדוגמאות ראה לקוטי לוי\"צ לתניא ע' יז."],["152","35","וי\"ל שבאמרו \"כשאבא קורא\" רמז ג\"כ שבקריאת אדה\"ז היתה נשמעת קריאתו של \"אבינו\" שבשמים (שאצלו ית' לא יגורך רע). — ולהעיר, שגם בעל המאמר במדרש (שהובא לעיל ריש סעיף א) הוא \"רבי אבא\")."],["153","36","היינו, שתוכן זה שבענין המבול (כפי שהוא \"בעליונים\") נמשך במי המבול הגשמיים למטה בארץ:\nמכיון ש\"תורה לא בשמים היא\" אלא ניתנה למטה בארץ [שהכוונה בזה היא לכל חלקי התורה, וכמובן מפסק דין אדמו\"ר הזקן בהלכות ת\"ת שלו (פ\"א ס\"ד), שכל אחד ואחד מישראל מחוייב בלימוד כל ד' חלקי התורה] — הרי מובן, דזה שלכל ענין שבתורה יש פירוש כפי שהתורה היא \"בעליונים\" — אין הכוונה ש\"מקומו\" של פירוש זה הוא רק ב\"עליונים\", אלא ש(תוכנו של ענין) זה נמשך גם ב\"תחתונים\".\nוכן בעניננו, שתוכן האמור במי המבול אינו רק ענין שהי' רק בעולמות עליונים, אלא שבמי המבול הגשמיים (שהציפו את העולם בפשטות ואשר בהם נאבד דור המבול, וטהרו את העולם מטומאת החטאים) היתה גם התכונה של \"תוספת\" טהרה, כענין המבול בעליונים."],["154","37","ולהעיר מהביאור בהכתוב (שה\"ש ח, ז) \"מים רבים לא יוכלו לכבות את האהבה\" — \"מים רבים\" למעליותא, \"ההתבוננות. . בגדולת ה' ביחו\"ע. . שמזה נמשך ואהבת. . בכל מאדך בלי גבול\" (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370086\" data-slug=\"torah-or\" data-id=\"3901370086\">תו\"א תולדות יח, ב</a>)."],["155","38","ראה אוה\"ת (וסה\"מ תרכ\"ז) שצוין בסוף הערה 9."],["156","*38","ראה רמב\"ם הל' עבודת יוהכ\"פ פ\"ב ה\"ג."]]],[1301410085,"וכן י\"ל בנוגע למי המבול<sup data-n=\"157\">39</sup>, שהם בדוגמא למקוה: זה שהמבול בא לטהר את הארץ מטומאת חטאי דור המבול הוא רק כפי שענין המבול נשתלשל מלמעלה וירד ונמצא \"בתחתונים\", אבל ענינו ב\"עליונים\" (בעולם שכולו קדושה) הוא — הטבילה הנדרשת בעלי' מדרגא בקדושה לדרגא עליונה יותר.\nדוגמא פשוטה בחיי האדם, גם שאינם מבנ\"י, בעוה\"ז הגשמי והחומרי: אהבת אב לבנו — שהיא באמתתה ותקפה בלב האב וכולה אך אהבה וטוב. כשחוטא הבן — נשתלשל מאהבה זו שמעניש את הבן בשבט וככל שתגדל האהבה בלב האב — יגדל עונש הבן. ועד אשר חושך<sup data-n=\"158\">40</sup> שבטו שונא בנו.\nה. הסברת העילוי שבמי המבול — בפרטיות יותר:\nכתב הרמב\"ם בסוף הל' מקוואות<sup data-n=\"159\">41</sup> שמי המקוה מרמזים ל\"מי הדעת הטהור\"<sup data-n=\"160\">42</sup>; וכמו שעל ידי הטבילה במים מתכסה האדם כולו במי המקוה עד שאינם נראים אלא מי המקוה, כך הוא בה\"רמז\" שבמקוה, הבאת הנפש במי הדעת, שצ\"ל השיקוע ב\"מי הדעת\" באופן שלא תיראה מציאותו של האדם, כ\"א רק של \"מי הדעת\" שבהם הוא שקוע.\nוזהו התוכן הרוחני של ענין המבול (כאשר כל העולם כולו מכוסה במים) — שכל הארץ כולה \"שקועה\" במי הדעת עד שאין נראית מציאותה של הארץ<sup data-n=\"154\">37</sup> כ\"א של \"מי הדעת\".\nוכמו\"כ הוא התוכן הרוחני של מי המבול בימי נח — שבאו \"לשחת כל בשר\"<sup data-n=\"121\">5</sup>, \"לשחת הארץ\"<sup data-n=\"163\">43</sup> — היינו לבטל (\"לשחת\") בביטול כליל (של \"בשריות\" ו\"ארציות\") ב\"מי הדעת\", עד שלא נראה שום מציאות מלבדו יתברך.\nוע\"ד מצב העולם לעתיד לבא<sup data-n=\"164\">44</sup>, וכדברי הרמב\"ם בסיום וחותם ספרו, ש\"באותו הזמן. . לא יהי' עסק<sup data-n=\"165\">45</sup> כל העולם אלא לדעת את ה' בלבד. . שנאמר<sup data-n=\"166\">46</sup> כי מלאה הארץ דעה את ה' כמים לים מכסים\" — שמצב העולם לעת\"ל דומה ל\"מבול\"<sup data-n=\"167\">47</sup> (\"כמים לים מכסים\"), שהעסק ב\"דעה את ה'\" (\"מי הדעת\") יהי' באופן ד\"מלאה הארץ דעה\" (ועד ש\"לא יהי' עסק כל העולם אלא לדעת את ה' בלבד\"<sup data-n=\"168\">48</sup>).\nובדרגא זו הי' מצב העולם בתחילת הבריאה, כשהי' \"כל העולם כולו מים במים\", ו\"לא הי' קלוסו של הקב\"ה עולה",[["157","39","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560320\" data-slug=\"or-hatorah-hb\" data-id=\"8316560320\">אוה\"ת</a> פרשתנו (כרך ג) תרכו, ב. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101036\" data-slug=\"likkutei-sichot\" data-id=\"1300101036\">לקו\"ש ח\"י (ע' 36</a>) שי\"ל שזהו ענין ירידת המבול בא\"י (למ\"ד שירד גם שם). ע\"ש."],["158","40","משלי יג, כד."],["159","41","משיעורי הרמב\"ם דשבוע זה (דשנת תשמ\"ז)."],["160","42","כמשנ\"ת כמ\"פ שלכאורה הגירסא הנכונה ברמב\"ם שם היא — \"במי הדעת הטהור — טהור\". אבל ראה שיחת ליל ד' דסוכות תשמ\"ח."],["154","37","ולהעיר מהביאור בהכתוב (שה\"ש ח, ז) \"מים רבים לא יוכלו לכבות את האהבה\" — \"מים רבים\" למעליותא, \"ההתבוננות. . בגדולת ה' ביחו\"ע. . שמזה נמשך ואהבת. . בכל מאדך בלי גבול\" (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370086\" data-slug=\"torah-or\" data-id=\"3901370086\">תו\"א תולדות יח, ב</a>)."],["121","5","פרשתנו ו, יז."],["163","43","פרשתנו ט, יא."],["164","44","ראה גם שער היחוד (לאדמו\"ר האמצעי) בתחלתו (ב, א)."],["165","45","ע\"ד הפי' בלעסוק בד\"ת (ב\"ח לטואו\"ח סמ\"ז ד\"ה ונוסחא)."],["166","46","ישעי' יא, ט."],["167","47","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670243\" data-slug=\"torat-chaim\" data-id=\"2300670243\">ולהעיר ג</a>\"כ ממחז\"ל (סנהדרין צב, ריש ע\"ב) \"אותן שנים. . הקב\"ה עושה להם כנפים כו' ושטין על פני המים\" (נת' בתו\"ח בראשית ד, ג ואילך. אוה\"ת בראשית כח, ב ואילך. סה\"מ תרכ\"ז ע' רלט ואילך (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640009\" data-slug=\"or-hatorah-hb\" data-id=\"8316640009\">אוה\"ת שה\"ש ח\"א ע' ט</a> ואילך). ועוד) — אלא ששם קאי באלף השביעי, כש\"יהי' עולם זה חרב\" (רש\"י שם). וראה לקמן סעיף וז (ובהערה 63)."],["168","48","ראה בארוכה \"הדרן\" על הרמב\"ם (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271252\" data-slug=\"likkutei-sichot\" data-id=\"1300271252\">לקו\"ש חכ\"ז ע' 238</a> ואילך) — דיוק תיבת \"בלבד\"."]]],[1301410086,"אלא מן המים\" — דהיינו שאין העולם נראה כלל כמציאות בפ\"ע (בדוגמת דבר שנטבל (אותיות בטל<sup data-n=\"169\">49</sup>) במים)<sup data-n=\"170\">50</sup>, אלא כל מציאותו היא רק הכח האלקי המהווה אותו ומקיימו.\nו. אמנם, לפי הביאור האמור בתוכנו של ענין המבול (כפי שהוא \"בעליונים\") — צלה\"ב לאידך גיסא: מכיון שענין המבול מורה על עילוי גדול כזה (שכל הארץ בטילה ב\"מי הדעת\") — מהו התוכן הפנימי (\"בעליונים\") של שבועת הקב\"ה ש\"לא אוסיף\"<sup data-n=\"171\">51</sup>, \"לא יהי' עוד מבול לשחת הארץ\"<sup data-n=\"163\">43</sup> (ומכיון ששבועה זו נכתבה בתורה, מובן, שהיא שוללת (גם, ואדרבא — באמת) ענין המבול לפי תוכנו הרוחני הנ\"ל)?\nוי\"ל נקודת הביאור בזה:\nזה שבתחילת הבריאה הי' \"כל העולם כולו מים במים\" — הוא מפני שעדיין לא נבראה מציאות היבשה<sup data-n=\"173\">52</sup>; ואילו ענין המבול הוא, לאחר שכבר נבראה מציאות הארץ, וכמו שהיא במציאותה — מכסים אותה המים.\nוההבדל ביניהם (ברוחניות):\nהעילוי ד\"כל העולם כולו מים במים\" בתחילת ברייתו של עולם — מה שהעולם לא הי' נראה כמציאות בפני עצמו אלא בטל כליל בכח האלקי המקיימו (כנ\"ל) — לא הי' נרגש במציאות העולם עצמו (כי לא הי' עדיין ראוי לכך), והעילוי ד\"דכל העולם כולו מים במים\" הי' רק מחמת זה שעדיין לא נבראה היבשה (הארץ);\nאמנם תכלית הכוונה היא, שביטול זה יומשך ויופעל במציאות הארץ עצמה. וזהו דיוק לשון הכתוב (בנוגע ללעתיד לבא) \"מלאה הארץ דעה את ה' כמים לים מכסים\", כלומר, לא שהארץ תהפך ל\"מים\", כ\"א כמו שהיא במציאות של ארץ תתמלא ב\"דעה את ה' כמים (בכ\"ף הדמיון) לים מכסים\", היינו שהעילוי ד\"כמים לים מכסים\" הוא בהארץ עצמה.\nאלא שכדי לפעול עילוי זה בהארץ עצמה צ\"ל ההכנה של \"טבילת\" הארץ ב\"מי המבול\" — \"לשחת הארץ\", לבטל לפי שעה מציאותה של הארץ עד שמכוסה כליל במים; וביטול זה הוא הוא הנותן כח, שגם כאשר אח\"כ \"יבשה הארץ\"<sup data-n=\"174\">53</sup> (\"נעשה גריד כהלכתה\"<sup data-n=\"175\">54</sup>), יומשך ביטול זה ביבשת הארץ עצמה.\nוזהו ג\"כ ענינם של מי המבול (לפי תוכנם הרוחני) — שבאו להכשיר את מציאות העולם שתהי' \"כלי\" לביטול זה<sup data-n=\"176\">55</sup> שיבוא לידי גילוי לעתיד לבא, כשתתמלא \"הארץ דעה את ה' כמים לים מכסים\".\n[עפ\"ז יובן גם מש\"כ במדרש<sup data-n=\"177\">56</sup> על הכתוב<sup data-n=\"178\">57</sup> \"וערבה לה' מנחת יהודה וירושלים",[["169","49","ראה סדור עם דא\"ח כוונת המקוה (קנט, סע\"ד)."],["170","50","ויש לקשר זה עם ההלכה \"כל מה שבים טהור\" (רמב\"ם הל' טומאת מת רפ\"ו). — וראה \"הדרן\" הנ\"ל (לקו\"ש חכ\"ז ע' 2412). וראה ע\"ד הענין ד\"מים במים\" (ע\"ד החסידות) במאמרים שנסמנו בהערה 47. ועוד."],["171","51","פרשתנו ח, כא ובפרש\"י."],["163","43","פרשתנו ט, יא."],["173","52","ראה קרבן העדה לירושלמי חגיגה שם (פ\"ב ה\"א) \"כל הברואים (ו)לא היו בהם רק יסוד המים\"."],["174","53","פרשתנו ח, יד."],["175","54","פרש\"י שם."],["176","55","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151051\" data-slug=\"likkutei-sichot\" data-id=\"1300151051\">לקו\"ש חט\"ו (ס\"ע 51</a> ואילך), דקיום העולם לפני המבול הי' רק מצד \"למעלה\", והמבול פעל זיכוך בהעולם, שיהי' מוכשר שקיומו יהי' מצד מציאות העולם גופא. ע\"ש."],["177","56","ויק\"ר פ\"ז, ד. איכ\"ר בסופו. ועוד."],["178","57","מלאכי ג, ד."]]],[1301410087,"כימי עולם וכשנים קדמוניות\" — \"כימי עולם כימי נח\". דלכאורה תמוה: הפסוק \"וערבה לה' גו'\" קאי על הזמן דגאולה האמיתית והשלימה, כאשר העולם יהי' בתכלית השלימות, וא\"כ איך אפשר לומר שהוא \"כימי עולם — כימי נח\"<sup data-n=\"179\">58</sup>?!\nאמנם ע\"פ הנ\"ל מובן — כי תחילת הכשרת העולם והכנתו לשלימותו בזמן הגאולה (\"מלאה גו' כמים לים מכסים\") היתה בימי נח<sup data-n=\"180\">59</sup>, ע\"י מי המבול שכיסו את העולם].\nז. ע\"פ הנ\"ל יבואר ג\"כ זה שנשבע הקב\"ה ש\"לא יהי' עוד מבול לשחת הארץ\":\nתכלית הכוונה היא שתהי' מציאות העולם דוקא, \"לשבת יצרה\"<sup data-n=\"181\">60</sup>, ובאופן ד\"לא ישבותו\"<sup data-n=\"182\">61</sup>, וכמו שהעולם הוא במציאותו יהי' כלי לכל הענינים הכי נעלים, כנ\"ל.\n[שלכן לא רצה הקב\"ה שהעולם ישאר בהמצב ד\"כולו מים במים\" — אף שאז \"הי' קלוסו של הקב\"ה עולה\" — אלא צמצם הקב\"ה התגלות זו עד ש\"תראה היבשה\"<sup data-n=\"183\">62</sup>, העולם כפי שנראה לעינינו]<sup data-n=\"184\">63</sup>.\nוהיות שהכשרה זו וכח זה כבר ניתן בעולם ע\"י הטבילה במי המבול, הרי שוב אין צורך \"לשחת\", לבטל מציאותו, ולכן נשבע הקב\"ה ש\"לא יהי' עוד מבול\" (כי, אדרבה, תכלית הכוונה היא שתהי' מציאותה של הארץ<sup data-n=\"185\">64</sup>).\nח. ידועים דברי השל\"ה<sup data-n=\"186\">65</sup>, שבפירוש רש\"י על התורה נרמזו \"ענינים מופלאים\". ובעניננו: העילוי הרוחני שב\"יבשה הארץ\" (כשישנה מציאות הארץ) לגבי העילוי הרוחני שב\"מי המבול\" (שהוא ע\"ד העילוי ד\"מים במים\" שבהתחלת הבריאה) — מרומז בלשון רש\"י על הפסוק \"יבשה הארץ\" — \"נעשה גריד כהלכתה\"<sup data-n=\"187\">66</sup>:\nמי המבול מרמזים על מדריגת התורה (\"מי הדעת\") כפי שהיא למעלה עדיין ממציאות העולם; ואילו \"יבשה הארץ\" היא התורה כפי שירדה למטה ונתלבשה בעניני ארץ — עוה\"ז.\nודוקא על ידי \"ירידה\" זו (של התורה) לעוה\"ז מתגלה חלק ההלכה שבתורה. כידוע דתורה לא בשמים היא<sup data-n=\"188\">67</sup>, ופסק",[["179","58","ובפרט ע\"פ מ\"ש באיכ\"ר שם: שנאמר (ישעי' נט, ד) כי מי נח זאת לי — והרי המדובר שם בנוגע למי המבול. וראה (בביאור מדרש זה ע\"ד החסידות) אוה\"ת פרשתנו סח, א ואילך. (כרך ג) תרכג, א ואילך."],["180","59","וי\"ל שזהו הפירוש הפנימי במחז\"ל (ב\"ר פ\"ל, ח. וש\"נ) דנח \"ראה עולם חדש\" — מעין ודוגמא ל\"שמים החדשים והארץ החדשה אשר אני עושה\" (ישעי' סו, כב) לעת\"ל."],["181","60","ישעי' מה, יח."],["182","61","פרשתנו ח, כב."],["183","62","בראשית א, ט."],["184","63","ולהעיר מאוה\"ת בראשית (ל, סע\"ב. וכן בסה\"מ תרכ\"ז ריש ע' רמו (אוה\"ת שה\"ש ע' יד) — הובאו לעיל הערה 47), דלאחרי ה\"חד חרוב\" (שאז יהי' \"מים במים כמו שהי' לפני הבריאה ואז. . שטים על פני המים\") — \"יתחדש העולם כאשר הוא עתה אלא כו' (השמים החדשים והארץ החדשה). . כולו טוב\". ע\"ש (ובלקו\"ת שמע\"צ פט, ג)."],["185","64","יתרה מזה — ע\"פ משמעות ל' הרמב\"ם (הל' אבות הטומאה פ\"ו הט\"ז ובכס\"מ שם) דהטובל נטהר לאחרי שיצא מן המקוה. ו\"יש ראי' לזה מדברי התוספתא פרה\" (שו\"ת צפע\"נ ווארשא סרע\"ו) ועוד. ונפק\"מ לנוגע בהטובל קודם שיצא. וראה השקו\"ט באנציקלופדי' תלמודית (חי\"ח) ערך טבילה (ע' תטתי). וש\"נ."],["186","65","במס' שבועות שלו (קפא, א)."],["187","66","ובפרט שהוא ביטוי בלתי רגיל בכגון דא, והול\"ל \"כראוי\" וכיו\"ב."],["188","67","ב\"מ נט, ב."]]],[1301410088,"הלכה אפשר להיות רק על ידי נשמה בגוף דוקא<sup data-n=\"189\">68</sup>. כי ענין ההלכה הוא — הידיעה כיצד להתנהג במעשה בפועל, הלכה למעשה. וכן — ענינם של הלכות הוא לפעול בעולם, בלשון הכתוב<sup data-n=\"190\">69</sup> \"הליכות עולם לו\", \"אל תקרי הליכות אלא הלכות\"<sup data-n=\"191\">70</sup>, כלומר, שפעולת התורה בעולם — \"הליכות עולם\", היא ע\"י ההלכות שבתורה. ועד שהעולם נעשה מהלך.\nוי\"ל שזהו הרמז בלשון רש\"י \"נעשה גריד כהלכתה\" — מלשון הלכה, שזהו העילוי שב\"יבשה הארץ\" לגבי מי המבול שקדמום, שעל ידי \"יבשה הארץ\" מגיעים לתכלית הכוונה בענין התורה, שהיא הפעולה בעניני העולם ע\"י חלק ההלכה שבתורה (\"כהלכתה\")<sup data-n=\"192\">71</sup>.\nט. ההסבר האמור בענין המבול שייך ג\"כ להזמן בשנה שבו קורין פ' נח — תחילת חודש מרחשון:\nחודש תשרי, שהוא \"מרובה במועדות\"<sup data-n=\"193\">72</sup>, הוא מעין ולמעליותא של ענין המבול \"בעליונים\", בו האדם שקוע וטובל (ובטל) בעניני טוב וקדושה, עד \"ששוכח\" עניניו הגשמיים, וכיון שמחשבתו אך ברוחניות — גם מציאות האדם (החושב) היא בענינים רוחניים<sup data-n=\"194\">73</sup>,\nוכאשר יוצאים מחודש תשרי לחודש מרחשון קורין בתורה סיפור המבול וסיומו, ללמדנו, שתכלית ענין ה\"מבול\" של חודש תשרי ושלימותו, הוא המצב ד\"יבשה הארץ\" שלאח\"ז, היינו, שימשיך ביטול זה של \"מי המבול\" תוך יבשת הארץ.\nובפשטות, שתכלית המועדים דחודש תשרי היא — להמשיך הקדושה וכו' ששאבו בחודש זה תוך חיי יום יום במשך כל השנה כולה \"בארץ\"<sup data-n=\"195\">74</sup>, עד שעבודת השם תהי' (גם) בכל עניניו הגשמיים — \"כל מעשיך יהיו לשם שמים\"<sup data-n=\"196\">75</sup>, ו\"בכל דרכיך דעהו\"<sup data-n=\"197\">76</sup>.\nוע\"י עבודה זו נזכה להקדמת קיום היעוד \"כי מלאה הארץ דעה את ה' כמים לים מכסים\", ובקרוב ממש.\n<span data-k=\"q\">(משיחת א' דר\"ח מרחשון תשמ\"ו) </span>",[["189","68","וראה אגה\"ק סכ\"ו (קמד, ב ואילך)."],["190","69","חבקוק ג, ו."],["191","70","מגילה כח, סע\"ב. נדה בסופה."],["192","71","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370086\" data-slug=\"torah-or\" data-id=\"3901370086\">תו\"א תולדות (יח, ב</a>) שם בפירוש \"מים רבים לא יוכלו לכבות את האהבה\" — \"שלא יוכל להשקיט ולכבות צמאון האהבה. . כי אם. . דוקא ע\"י עסק התורה ומצות מעשיות\"."],["193","72","שו\"ע אדה\"ז או\"ח סתצ\"ב ס\"ב. ועוד."],["194","73","דבמקום רצונו ומחשבתו של אדם שם הוא נמצא (כתר שם טוב — הוצאת קה\"ת — הוספות סל\"ח. וש\"נ), וכידועה הראי' מעירובי תחומין דבמקום שדעתו שם שם הוא מקומו (ראה שו\"ע אדה\"ז או\"ח סת\"ח)."],["195","74","ראה תניא אגה\"ק רס\"ט."],["196","75","אבות פ\"ב מי\"ב."],["197","76","משלי ג, ו."]]],[1301410089,"<h3>שיחה ב</h3>\nא. כתב הרמב\"ם<sup data-n=\"198\">1</sup>: \"אף על פי שקיים אדם מצות פרי' ורבי'<sup data-n=\"199\">2</sup> הרי הוא מצווה מדברי סופרים שלא יבטל מלפרות ולרבות כל זמן שיש בו כח, שכל המוסיף נפש אחת בישראל<sup data-n=\"200\">3</sup> כאילו בנה עולם\".\nוהקשו ע\"ז<sup data-n=\"201\">4</sup>, דהרי בגמ'<sup data-n=\"202\">5</sup> מפורש שמקורו וטעמו של דין זה הוא מהכתוב<sup data-n=\"203\">6</sup> \"בבוקר זרע את זרעך ולערב אל תנח ידך וגו'\", וז\"ל הגמרא: \"ר' יהושע אומר נשא אדם אשה בילדותו ישא אשה בזקנותו היו לו בנים בילדותו יהיו לו בנים בזקנותו שנאמר בבוקר זרע את זרעך ולערב אל תנח ידך כי אינך יודע אי זה יכשר הזה או זה ואם שניהם כאחד טובים\". וכן העתיק ופסק הרי\"ף<sup data-n=\"204\">7</sup>, והביא כתוב זה. ואמאי השמיט הרמב\"ם טעם הגמ' וכתב טעם חדש מדילי' (\"שכל המוסיף כו'\")<sup data-n=\"205\">8</sup>?\nב. והנה יש מפרשים<sup data-n=\"206\">9</sup>, שמהכתוב יש לדייק שני טעמים: (א) לפי רישא דקרא \"כי אינך יודע אי זה יכשר גו'\", ה\"ז מטעם ספיקא (כפי' רש\"י על הכתוב<sup data-n=\"207\">10</sup>) \"אם. . בנים שבילדותך יתקיימו לך או שמא לא יתקיימו אלא שבזקנותך\": (ב) לפי סיפא דקרא \"ואם שניהם כאחד טובים\" אין זה מטעם ספיקא וחשש, אלא כל אימת שיכול להוסיף בהולדת בנים הרי הוא מצווה ע\"ז.\nוהיינו, דלטעם הא' עיקר החיוב הוא",[["198","1","הל' אישות פט\"ו הט\"ז."],["199","2","ראה לקמן סעיף ו ובהערות שם, שעיקר ציווי פו\"ר נאמר בפרשתנו."],["200","3","י\"ג \"מישראל\" (וע\"ד ל' הרמב\"ם שבהערה 22. ועוד) — ראה ילקוט שינויי נוסחאות ברמב\"ם הוצאת פרענקל."],["201","4","ראה הגהות הרמ\"ך לרמב\"ם שם. מעשה רוקח שם."],["202","5","יבמות סב, ב."],["203","6","קהלת<sup data-n=\"e1\">*</sup> יא, ו."],["204","7","יבמות שם."],["205","8","ומובן שאין לבאר שהוא ע\"ד שמצינו בכללי הרמב\"ם (ראה יד מלאכי כללי הרמב\"ם אות ד) שדרכו לכתוב דבר היותר מתקבל, ובפרט בעניננו שגם בגמ' נלמד מכתוב שהודגש בו טעם, ולכן כ' הרמב\"ם מדילי' טעם פשוט יותר — כי טעם הרמב\"ם \"שכל המוסיף נפש אחת בישראל כאילו בנה עולם\" לכאורה אינו טעם (מספיק) כלל בהלכה לחייבו במצוה (מד\"ס), משא\"כ בגמ' שלמדין מכתוב שנאמר בסגנון של הוראה וציווי."],["206","9","העמק שאלה לשאילתות שאילתא קסה אות ג. וראה בארוכה שדי חמד כללים מערכת וא\"ו כלל יד."],["207","10","קהלת שם. ועד\"ז ברש\"י יבמות שם ד\"ה אי זה יכשר: איזה זרע יהא הגון וירא שמים ומתקיים. וברשב\"ם ב\"ב צא, א ד\"ה כדרבה: לפי שהי' ירא שמא ימותו בניו כו'. ע\"ש. ובקה\"ר עה\"פ בדברי ר\"נ: אינך יודע איזה בנים מתקיימין לך אם של נערותך אם של זקנותך אם שניהם כאחד טובים. ובאבות דר\"נ פ\"ג, ו \"אם שניהם יתקיימו בידך\"."],["e1","*","שקיהל חכמות רבות. . וי\"א שהי' אומר כל דבריו בהקהל (רש\"י ריש קהלת — ולכאורה זהו יותר מ\"בקהל\". וראה ר\"פ ויקהל. ומנ\"ל לרש\"י זה?).\n[מקורו דרש\"י הוא בקה\"ר בתחלתה \"שהיו דבריו נאמרין בהקהל\". וראה יל\"ש ריש קהלת. ובאבודרהם (בשם אבן הירחי) \"כי שלמה בחג אמרו בהקהל כמ\"ש במועד שנת השמיטה בחג הסוכות גו' וכתיב ויקהלו אל המלך שלמה בירח האתנים בחג וגו' ואז אמרו בהקהל להוכיח את ישראל\".\nאבל צ\"ע מנ\"ל בפשש\"מ שהיו דבריו סתם ב\"הקהל\" לאו דוקא בחה\"ס דשנת הקהל. וראה מדרש לקח טוב ר\"פ דברים: לפי שהי' קהלת מקהיל קהילות בישראל כו']."]]],[1301410090,"משום חשש ביטול מצות פו\"ר, וא\"כ י\"ל דנחשב כספיקא דאורייתא דשמא יבטל ממצות פו\"ר<sup data-n=\"208\">11</sup>; אבל לפי הטעם השני שבכתוב \"ואם שניהם כאחד טובים\", אין כאן משום חשש ביטול מצות פו\"ר וספיקא דאורייתא, אלא הנהגה טובה ומצוה מדברי סופרים, שיהיו לו עוד בנים.\nוזהו שכתב הרמב\"ם \"שכל המוסיף נפש אחת בישראל כאילו בנה עולם\", שכוונתו להטעם \"ואם שניהם כאחד טובים\", כי לדעת הרמב\"ם עיקר הטעם הוא מסיפא דקרא, וחיובו אינו מטעם חשש ביטול מצות פו\"ר דאורייתא, אלא הוי מצוה מדברי סופרים, וכנ\"ל.\nאמנם לכאורה ביאור זה דחוק הוא מכמה טעמים:\nא) דוחק לחלק הפסוק לשני טעמים, כי מפשטות הכתוב משמע דהוי כולא טעמא חדא, וסיפא דקרא הוא המשך הספק דרישא: \"אינך יודע אי זה מהם יכשר הזה או זה ואם (או) שניהם כאחד טובים\"<sup data-n=\"209\">12</sup>.\nב) את\"ל שהטעם הא' שבכתוב (\"אינך יודע אי זה מהם יכשר\") הוי חששא דביטול מ\"ע דאורייתא (שמא ימותו בניו הראשונים), אינו מובן:\n(א) לפי זה יוצא, שכל אימת שאשתו של אדם (גם אם ילדה לו בן ובת) אינה עוד בת בנים יש עליו חיוב לישא אשה (בת בנים) על אשתו<sup data-n=\"210\">13</sup> (או לגרשה ולישא אחרת)<sup data-n=\"211\">14</sup> מחשש שמא ימותו — והרי לא מצינו שבנ\"י יחמירו בזה<sup data-n=\"212\">15</sup> כדי לצאת דעת ר\"י (ובפרט שמפורש בגמ'<sup data-n=\"213\">16</sup> \"הלכה כרבי יהושע\"<sup data-n=\"214\">17</sup>).\n(ב) ומאידך גיסא, אם הוי ספיקא בלבד — חל חיוב זה ד\"לערב אל תנח ידך\" דוקא כאשר יש לו רק בן ובת (או שני זכרים לדעת ב\"ש), כי אז י\"ל דאע\"פ שקיים מצות פו\"ר, מ\"מ חיישינן למיתת אחד מהם ושוב אין בידו מצות פו\"ר; אבל כאשר יש לו כמה בנים ובנות אז אין טעם שיחול עליו חיוב זה<sup data-n=\"215\">18</sup>, שהרי למיתה דבי תרי לא חיישינן<sup data-n=\"216\">19</sup> — ומסתימת לשון ר\"י \"היו לו בנים בילדותו\" משמע בפשטות שהמדובר הוא לאו דוקא בשני בנים (בן ובת), כ\"א גם כאשר היו לו כו\"כ בנים.",[["208","11","בהגהות הרמ\"ך שם בהמשך לדברי הגמ' כי לא תדע הזה יכשר: דחייש למיתת הראשונים ונמצא שלא קיים המצוה."],["209","12","להעיר שבקה\"ר שם במאמר ר\"י אינו מביא סיום הכתוב \"אם שניהם כאחד טובים\". ולאידך באבות דר\"נ הובא זה בלשון ר\"י \"כי אינך יודע אם שניהם יתקיימו בידך אם שניהם כאחד טובים שנאמר בבוקר זרע את זרעך\" (וראה ב' הנוסחאות באבות דר\"נ). ובב\"ר פס\"א, ג במאמר ר\"י לענין נתינה לעני נקט הטעם שבכתוב לא בתור ראי' מהכתוב אלא כחלק מלשונו, ולא הביא בכלל רישא דקרא. וראה זח\"א קפח, א. זהר חדש רות (פט, רע\"ג)."],["210","13","ובזה אין מקום לכאורה לחשש דהכנסת צרה לביתו — \"לעשות את זו צרה לזו\" (ל' רש\"י אחרי יח, יח), כיון שהוי ספק בקיום מ\"ע דאורייתא, משא\"כ להטעם השני הנ\"ל שאין מקום לזה. כפשוט."],["211","14","ראה בעל המאור יבמות שם. רא\"ש שם פ\"ח ס\"ט. דרישה לטור אה\"ע ס\"א סק\"ט."],["212","15","ראה מקור חסד לספר חסידים סי' שעו שמביא ראיות מכ\"מ שגם לפני חדר\"ג לא הי' מנהג בנ\"י (ובפרט גדולי ישראל) לישא שתי נשים."],["213","16","יבמות שם."],["214","17","וכ\"ה ברי\"ף שם. וראה בעל המאור ורא\"ש שם (ומעשה רוקח שבהערה 31). וראה שו\"ע אה\"ע שם ס\"ח ובנ\"כ."],["215","18","והא דבועז שהי' ירא שמא ימותו בניו (שהיו יותר משנים) — רשב\"ם ב\"ב שם — וכולם מתו בחייו — אין מזה הכרח שהוא חיוב (ראה בהנסמן בהערה שלאח\"ז)."],["216","19","יבמות כו, ב ותוס' שם. תוד\"ה וחכ\"א — ריש יומא. וראה שדי חמד שם. ולהעיר מערוך לנר ליבמות סא, ב ד\"ה דלאו בת בנים."]]],[1301410091,"ומלבד זאת — אין פירוש זה מספיק ליישב דברי הרמב\"ם, שהרי עכ\"פ הו\"ל להרמב\"ם להביא רישא דקרא — שנאמר \"בבוקר זרע את זרעך ולערב אל תנח ידך\" (בלי המשך הטעם ד\"אינך יודע גו'\") — שבו נאמר עצם החיוב (וכמו שמצינו ברי\"ף<sup data-n=\"217\">20</sup> שהביא רק רישא דקרא הנ\"ל, והרי גם הוא ס\"ל \"והא מילתא דרבנן היא\" כדעת הרמב\"ם ש\"הוא מצווה מדברי סופרים\").\nג. והנה בטעם שכתב הרמב\"ם \"שכל המוסיף נפש אחת בישראל כאילו בנה עולם\" צ\"ב לכאורה, לשונו \"שכל המוסיף\" ולא בלשון הרגיל — \"כל המוליד\"; ולאידך, אם תפס ל' \"מוסיף\", הו\"ל לסיים \"כאילו הוסיף עולם\" בהתאם לתחלת הלשון \"כל המוסיף נפש אחת\" (וע\"ד מרז\"ל במס' סנהדרין<sup data-n=\"218\">21</sup> \"כל המקיים נפש אחת מישראל מעלה עליו הכתוב כאילו קיים עולם מלא\"<sup data-n=\"219\">22</sup>), ולמה ממשיך \"כאילו בנה כו'\"?\nגם צריך להבין: ברמב\"ם הל' דעות<sup data-n=\"220\">23</sup> כ' בנוגע להכוונה בהולדת בנים \"וישים על לבו שיהי' לו בן אולי יהי' חכם וגדול בישראל\". ולכאורה הרי זו הסברה פשוטה ב\"כאילו בנה עולם\", ומדוע לא הביאה הרמב\"ם כאן כטעם ע\"ז שלא יבטל מלפרות ולרבות, כי אולי יהי' הבן הנולד חכם וגדול בישראל, ואז הרי זה לא רק \"כאילו בנה עולם\" אלא שזהו בנין עולם ממש?\nד. ויובן זה בהקדם הצ\"ע, ובפרט אם נאמר (כדמוכחא מילתא)<sup data-n=\"221\">24</sup> שדין זה ברמב\"ם מקורו בדברי ר\"י — ד\"היו לו בנים בילדותו יהיו לו בנים בזקנותו\"; מדוע שינה הרמב\"ם מלשון ר\"י (\"היו לו בנים כו'\") וכותב לשון אחר<sup data-n=\"222\">25</sup>?\nוי\"ל הביאור בזה בפשטות: בדין נשא אשה בילדותו ישא אשה בזקנותו היו לו בנים בילדותו יהיו לו בנים בזקנותו — אפ\"ל שני אופנים:\nא) הוא (המשך מ)עצם חיוב העיקרי דמצות פו\"ר, שגם לאחר שקיים מצוה זו בילדותו, יש עליו חיוב מד\"ס להמשיך (\"לא ליבטל\") במצות פו\"ר גם בזקנותו. ולפי זה — הכתוב בקהלת הוי<sup data-n=\"223\">26</sup> גילוי מילתא וביאור במצות פו\"ר שמן התורה. או\nב) הוא חיוב ודין בפ\"ע, שאף שקיים מצות פו\"ר ע\"י הבנים שהיו לו בילדותו, ה\"ה מצווה בדברי קבלה<sup data-n=\"223\">26</sup> \"בבוקר זרע את זרעך גו'\" להוליד בנים גם בזקנותו [וכן משמע לכאורה מהמשך דברי ר\"י, שאינו מסתפק בציווי הולדת בנים (\"היו לו בנים בילדותו כו'\"), אלא<sup data-n=\"225\">27</sup> מתחיל כענין חדש — \"נשא אשה. . היו לו בנים. . \"].",[["217","20","וכן בסמ\"ג מ\"ע מט."],["218","21","לז, א — במשנה. והביאו הרמב\"ם בהל' סנהדרין פי\"ב ה\"ג. וראה גם רמב\"ם שבהערה הבאה."],["219","22","וברמב\"ם הל' רוצח כו' ספ\"א \"וכל המקיים נפש אחת מישראל כאילו קיים כל העולם כולו\"."],["220","23","ספ\"ג."],["221","24","כמ\"ש במגיד משנה כאן ושם ה\"ז."],["222","25","ראה יד מלאכי כללי הרמב\"ם אות ה — שהרמב\"ם מעתיק לשון הגמ'."],["223","26","להעיר מהשינויים במדרשים הנ\"ל הערות 10, 12: בקה\"ר מביא רק ל' הכתוב (ע\"ד ל' הגמרא); באבות דר\"נ \"אלא שא אשה והוליד בנים ובנות והרבה פרי' ורבי' בעולם\"; בב\"ר שם בסופו \"ר' דוסתאי בשם רבי שמואל בר נחמן אם היו לך בנים בנערותך קח לך אשה בזקנותך והעמד בנים וממי אתה למד מאברהם כו'\", ומשמע שהוא לימוד בפ\"ע, ואינו מטעם המשך קיום מצות פו\"ר. וראה בארוכה יפ\"ת (השלם) ונזר הקדש (השלם) לב\"ר שם."],["223","26","להעיר מהשינויים במדרשים הנ\"ל הערות 10, 12: בקה\"ר מביא רק ל' הכתוב (ע\"ד ל' הגמרא); באבות דר\"נ \"אלא שא אשה והוליד בנים ובנות והרבה פרי' ורבי' בעולם\"; בב\"ר שם בסופו \"ר' דוסתאי בשם רבי שמואל בר נחמן אם היו לך בנים בנערותך קח לך אשה בזקנותך והעמד בנים וממי אתה למד מאברהם כו'\", ומשמע שהוא לימוד בפ\"ע, ואינו מטעם המשך קיום מצות פו\"ר. וראה בארוכה יפ\"ת (השלם) ונזר הקדש (השלם) לב\"ר שם."],["225","27","ראה עיון יעקב (לע\"י) וערוך לנר יבמות שם. ועוד."]]],[1301410092,"ויש לומר שזהו יסוד החילוק בין שתי הגירסאות שישנן בגמ' שם, בקשר לדברי המשנה<sup data-n=\"226\">28</sup> \"לא יבטל אדם מפרי' ורבי' אלא א\"כ יש לו בנים\": לרוב הספרים גרסינן בגמ' \"מתניתין דלאו כר' יהושע\", אמנם הרי\"ף (ועוד) לא הביא תיבות אלו<sup data-n=\"227\">29</sup>.\nוהנה להגירסא \"מתניתין [דקתני אא\"כ כו' הא אם יש לו יבטל<sup data-n=\"228\">30</sup>] דלאו כר\"י\", נקטינן כאופן הא' הנ\"ל, שדברי ר\"י הם מטעם (המשך) קיום מצות פו\"ר ובע\"כ פליג אמתניתין שדייקינן מינה דאם יש לו בנים נתקיימה מצות פו\"ר במילואה ויכול ליבטל כו'.\nאבל להגירסא דליתא תיבות אלו בגמ' י\"ל, שמאמר ר\"י אינו בסתירה להמשנה (דמשמע הא אם יש לו בנים יכול ליבטל מפו\"ר), כי הדין דר\"י הוא דין וחיוב בפ\"ע מדברי קבלה<sup data-n=\"229\">31</sup> — ובזה לא איירי במתניתין.\nועפ\"ז י\"ל שלכן משנה הרמב\"ם מלשון ר\"י \"היו לו בנים בילדותו יהיו לו בנים בזקנותו\" וכותב \"אף על פי שקיים אדם מצות פרי' ורבי' הרי הוא מצווה מדברי סופרים שלא יבטל מלפרות ולרבות כל זמן שיש בו כח\" — להשמיענו דבר זה גופא<sup data-n=\"230\">32</sup> — שציווי הכתוב (בדברי קבלה) דגם בעת זקנותו יהיו לו בנים (\"לערב אל תנח ידך\"), אינו ענין וחיוב בפ\"ע, אלא הוא מצד לתא דמצות פו\"ר<sup data-n=\"231\">33</sup>, שיש חיוב תמידי (מד\"ס) שלא יבטל מפו\"ר (מקיום מצות פו\"ר שמדאורייתא<sup data-n=\"232\">34</sup>) כ\"ז שיש בו כח.\nויש לומר שהנפק\"מ להלכה בין ב' אופנים אלו, היא בהדין דמוכרים ס\"ת בשביל בנים (לישא אשה בת בנים)<sup data-n=\"233\">35</sup> — אם ישנו גם כשכבר קיים מצות פו\"ר (כשתי הדיעות בשו\"ע בזה<sup data-n=\"234\">36</sup>): לפי השיטה שהוא דין בפ\"ע, הרי כיון שכבר קיים מצות פו\"ר בשלימותה, שוב אינו מוכר ס\"ת בשביל לישא אשה בת בנים; אבל אם הוא חיוב תמידי מצד לתא דמצות פו\"ר, מסתבר שיש לו למכור ס\"ת כדי לישא אשה בת בנים גם אם כבר קיים<sup data-n=\"235\">37</sup> מצות פו\"ר מה\"ת<sup data-n=\"236\">38</sup>.\nה. עפ\"ז מובן בפשטות לשון הרמב\"ם \"שכל המוסיף נפש אחת בישראל כאילו בנה עולם\":\nבלשון וטעם זה מתבאר התוכן הנ\"ל — כי גדר של מצות פרי' ורבי' הוא — בנין העולם (לשבת יצרה), וכפשטות הכתובים<sup data-n=\"237\">39</sup> \"פרו ורבו ומלאו את הארץ (וכבשוה גו')\".\nומדייק הרמב\"ם \"שכל המוסיף נפש אחת בישראל כאילו בנה עולם\", להדגיש שמצות פו\"ר אינה מוגבלת רק לקיום חיובה, הולדת בן ובת, אלא שכל שהוא מוסיף בזה, ה\"ז בכלל תוכנה (וגדרה) של מצוה זו — בנין העולם<sup data-n=\"238\">40</sup>, \"כאילו בנה עולם\".\nמשא\"כ הא דהל' דעות \"יהי' לו בן אולי יהי' חכם וגדול בישראל\" שייך רק לכוונתו בהולדת בנים, אבל אי\"ז גדר קיום מצות פו\"ר, שענינה \"בנין עולם\" בהולדת בנים ובנות (וגם אם הבן אינו \"חכם וגדול בישראל\").\nו. ויש לומר, שענין זה ד\"כל המוסיף נפש. . כאילו בנה עולם\" מודגש בפרשתנו — פ' נח.\nדהנה \"פרו ורבו\" נאמר בתורה בפ' בראשית ובפ' נח<sup data-n=\"239\">41</sup>, ואחד החילוקים ביניהם הוא\n[נוסף ע\"ז שהציווי על פרו ורבו (בפשש\"מ<sup data-n=\"240\">42</sup>) נאמר בפרשתנו<sup data-n=\"241\">43</sup> \"ואתם פרו ורבו\", משא\"כ בפ' בראשית<sup data-n=\"242\">44</sup> שהוא לברכה<sup data-n=\"243\">45</sup>]:\nבפ' בראשית נאמר זה לאדם הראשון, ומכיון שלפני אמירת (ברכה) ציווי זה לא היו לאדם בנים, מובן, שבזה מדובר בעיקר קיום פו\"ר (הולדת בן ובת).\nמשא\"כ בפרשתנו נאמר \"פרו ורבו\" לנח ובניו — כלומר, לא רק לבני נח שעדיין לא היו להם בנים, אלא גם לנח",[["226","28","שם סא, ב."],["227","29","ראה בעל המאור, מלחמות יבמות שם. רא\"ש שם ס\"ט (ועוד)."],["228","30","פרש\"י יבמות שם (סב, ב)."],["229","31","וראה לחם משנה לרמב\"ם שם ה\"ז. מעשה רוקח שם. ועוד."],["230","32","ראה ב\"ש אה\"ע ריש ס\"א שהקשה בדברי הרמב\"ם (הל' אישות רפט\"ו) דמהני מחילה אם כבר קיים מצות פו\"ר, מנ\"ל להרמב\"ם חילוק זה דמהני מחילה שלה אחר קיום פו\"ר דמ\"מ חייב לקיים לערב אל תנח ידך (אף שהוא מדרבנן). וע\"פ הנ\"ל בדעת הרמב\"ם לכאורה יוקשה ביותר, דעדיין מצווה הוא מד\"ס שלא לבטל מלפרות ולרבות — אבל ראה נימוקי הגרי\"ב לרמב\"ם הל' אישות שם, דדברי הרמב\"ם הם רק בנוגע לחיוב מדאורייתא, אבל מדרבנן ודאי לא מהני מחילה, מפני הציווי ד\"לערב אל תנח ידך\", וכהא דתירץ המגיד משנה לרמב\"ם שם ה\"ז. וראה אוצר הפוסקים לשו\"ע אה\"ע שם סק\"ג. וש\"נ."],["231","33","להעיר מפרש\"י ביצה לז, רע\"א (נסמן בצפע\"נ לרמב\"ם כאן) דכאשר כבר קיים מצות פו\"ר (לב\"ה או לב\"ש) \"תו לא מיפקד כולי האי כו' ומיהא קצת מצוה איכא כדאמר בבוקר כו'\" (וראה פרש\"י שם לו, סע\"ב: ולא. . הא מצוה קא עביד — שנושא אשה לפרות ולרבות). ואולי זוהי כוונת הצפע\"נ בציונו, דמגמ' ופרש\"י זה משמע דהיינו (קצת) מצות פו\"ר. וראה שו\"ת פרי יצחק (להר\"י בלאזער דפעטערבורג) סמ\"א."],["232","34","ואולי י\"ל דלהרמב\"ם, אף שהחיוב הוא מדברי סופרים, יש בזה קיום מצות פו\"ר מה\"ת (ע\"ד כשנוסף על התפלות שמתפלל, יהיב פרוטה לעני (ב\"ב י, א) אף שכבר נתן חומש, ועוד כו\"כ. וראה אנציקלופדי' תלמודית כרך יב ע' תרנז, תערב). ולהעיר משיטת הרמב\"ם דקרי גם לדאורייתא בשם \"דברי סופרים\" כשאינו מפורש בתורה (ראה סהמ\"צ שורש ב' ובמפרשים שם. נ\"כ הרמב\"ם הל' אישות פ\"א ה\"ב. ועוד). וראה שדי חמד אסיפת דינים מערכת אישות ס\"ב אות ז."],["233","35","ראה יבמות סא, סע\"ב ובתוס' שם. וראה הערה הבאה."],["234","36","אה\"ע ס\"א ס\"ח. וראה נ\"כ טור ושו\"ע שם."],["235","37","וברמב\"ם הל' ס\"ת פ\"י ה\"ב סתם ולא פירט, ולאידך בהל' אישות כאן לא כתב דין זה כלל. וראה לח\"מ ומעשה רוקח כאן ה\"ז. ואכ\"מ."],["236","38","ראה שאילתות פרשתנו שאילתא ה' בסופה (וראה העמק שאלה שם). בעל המאור ומלחמות לרי\"ף יבמות שם. נ\"כ השו\"ע שם. וראה בארוכה שו\"ת פרי יצחק שם."],["237","39","בראשית א, כח. פרשתנו ט, א (וראה שם, ז). וראה לקמן בפנים סעיף ו."],["238","40","להעיר מסהמ\"צ להרמב\"ם מ\"ע ריב \"לכוין לקיום המין\" (וראה גם בהל' דעות פ\"ג ה\"ב). וראה חמדת ישראל ח\"א קונטרס נר מצוה חלק העשין סעיף מד. ואכ\"מ."],["239","41","ראה סמ\"ג ריש מ\"ע מט: בד' מקומות הזהירה תורה בפ' בראשית ובפ' נח. וראה בארוכה במפרשי הסמ\"ג."],["240","42","ראה רש\"י פרשתנו שם, ז. רמב\"ן ורא\"ם ועוד שם."],["241","43","וכ\"ה בסנהדרין נט, ריש ע\"ב (וראה ע\"ז ה, א (ור\"ח שם)). שאילתות פרשתנו שם (בתחלתו). שם פ' ברכה שאילתא קסה. וכ\"ה בסהמ\"צ להרמב\"ם שם לפנינו<sup data-n=\"e2\">*</sup>. וראה הערה 45."],["242","44","וכן פרשתנו ט, א."],["243","45","ראה כתובות ה, ב. תוד\"ה ולא קאמר — יבמות סה, ב. ובמהרש\"א סנהדרין שם (נסמן עה\"ג שם) דלכו\"ע הציווי דפו\"ר הוא בפרשתנו ט, ז."],["e2","*","בהוצאת הר\"ח העליר, שבערבית (ובתרגום אבן איוב) שם ליתא \"ואתם\". ע\"ש. אבל להעיר שבראש ספר היד במנין המצות לכמה גי' (ראה ספר המדע — ירושלים, תשכ\"ד) הובא \"ואתם\" (היינו הכתוב דפרשתנו שם, ז) או המשך הכתוב \"שרצו בארץ\" (אבל ראה שם עוד גי' — שהובא סיום הכתוב דפרשתנו ט, א או דבראשית שם)."]]],[1301410093,"עצמו שכבר היו לו שלשה בנים<sup data-n=\"244\">46</sup>, גם לו נאמר \"פרו ורבו ומלאו את הארץ\", \"פרו ורבו שרצו בארץ ורבו בה\", שי\"ל שבזה נרמז אשר גם הוספת נפש הוי בכלל קיום פו\"ר, וכאילו בנה עולם.\nז. וי\"ל — כשם שהוא בענין מצות פו\"ר כפשוטה, כך הוא גם בנוגע ל(תוכן) מצות פו\"ר ברוחניות, שהוא לימוד התורה עם תלמידים<sup data-n=\"245\">47</sup> (ובכללות — קירוב בני ישראל ליהדות, תורה ומצוותי') — כמחז\"ל<sup data-n=\"246\">48</sup> \"כל המלמד בן חבירו תורה מעלה עליו הכתוב כאילו ילדו\" — שאין בזה חילוק בין זמן ה\"ילדות\" לעת ה\"זקנה\", וכהמשך דברי הגמ'<sup data-n=\"247\">49</sup>, שלאחרי מאמר ר' יהושע בא מאמר ר' עקיבא \"למד תורה בילדותו ילמוד תורה בזקנותו היו לו תלמידים בילדותו יהיו לו תלמידים בזקנותו שנאמר בבקר זרע גו'\".\nכלומר, מלבד זאת שבחיוב ת\"ת (לעצמו) אין חילוק בין בחור לזקן (כמ\"ש הרמב\"ם בהל' ת\"ת<sup data-n=\"248\">50</sup>), הנה גם בלימוד עם תלמידים (שהוא מ\"ע מן התורה<sup data-n=\"249\">51</sup>) ישנו הציווי (מדברי קבלה?) ד\"לערב אל תנח ידך\":\nלאחר שהאדם עסק והתייגע בהשפעה על הזולת במשך שנות הבחרות וגיל העמידה, הנה בהגיעו לעת זקנתו הרי אפשר שיאמר שעתה ינוח מעבודתו ויגיעתו אלו — בלשון הכתוב<sup data-n=\"250\">52</sup> \"יצא אדם לפעלו ולעבודתו עדי ערב\" [כולל ה\"ערב\" דכללות ימי חייו<sup data-n=\"251\">53</sup>] — בא הכתוב ואומר: \"ולערב אל תנח ידך\", שגם אז עליו להמשיך ולעסוק ב\"פרו ורבו\", לקרב עוד בנ\"י ועוד בנ\"י ליהדות, תורה ומצוותי'.\nובזה מוסיף הרמב\"ם, שטעם הדבר הוא, מפני \"שכל המוסיף נפש אחת בישראל כאילו בנה עולם\": ההכרח להוסיף בעבודתו זאת, אינו רק מפני החשש שעבודתו הקודמת לא היתה בשלימות (ועד שישנו חשש \"אי זה יכשר גו'\", ע\"ד סיפור הגמ' שם אודות תלמידי ר' עקיבא), אלא שגם אם עבודתו הקודמת היתה בתכלית השלימות — אין לו להסתפק בכך, ועליו להוסיף בעבודתו גם ב\"ערב\", כי ע\"י כל פעולה שלו ה\"ז \"כאילו בנה עולם\".\nוע\"פ משנת\"ל בדברי הרמב\"ם נמצא, שחיוב זה, שגם \"לערב\" יש להוסיף ב\"מלמד את בן חבירו תורה\" — אינו חיוב נוסף, לעשות דבר טוב ונעלה, אלא זהו המשך והשלמה לקיום מצות פו\"ר (ברוחניות).\nויש לבאר תוכן חידוש זה (שגם ההשפעה \"בזקנותו\" הוי בכלל מצות פו\"ר ברוחניות) בפנימיות הענין:\nתכלית כל הבריאה היא כדי לעשות",[["244","46","אף שלענין קיום מצות פו\"ר להלכה לאחר מ\"ת לא קיים כי לדעת ב\"ה צ\"ל בן ובת (יבמות סא, ב. רמב\"ם הל' אישות שם ה\"ד)."],["245","47","להעיר שרש\"י, שמפרש פשוטו של מקרא (גם בנ\"ך<sup data-n=\"e3\">*</sup>), פי' בקהלת שם הן בנוגע להולדת בנים והן בנוגע ללימוד התורה."],["246","48","סנהדרין יט, ב. פרש\"י עה\"ת במדבר ג, א."],["247","49","יבמות סב, ב."],["248","50","פ\"א ה\"ח. טושו\"ע יו\"ד ר\"ס רמו. שו\"ע אדה\"ז או\"ח ר\"ס קנה. וראה הל' ת\"ת שלו פ\"ג סוס\"ד."],["249","51","ראה רמב\"ם ריש הל' ת\"ת. הל' ת\"ת לאדה\"ז פ\"א ס\"ח."],["250","52","תהלים קד, כג."],["251","53","ראה סה\"מ אידיש ס\"ע 200 ואילך."],["e3","*","אף שאינו פשוטו של מקרא ממש כמו בפירושו על התורה (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141099\" data-slug=\"likkutei-sichot\" data-id=\"1300141099\">לקו\"ש חי\"ד ע' 87</a> הערה 10 ובשוה\"ג. ועוד)."]]],[1301410094,"לו ית' דירה בתחתונים<sup data-n=\"252\">54</sup>, וזהו תוכן הפנימי של \"בנה עולם\", לבנות לו ית' דירה. כלומר, שהעולם שמצ\"ע הוא במצב של \"העלם\" והסתר, שלא ניכר בו שהתהוותו היא מ\"אמתת המצאו\"<sup data-n=\"253\">55</sup>, צריכים לבנותו ולעשות דבר חדש, לגלות בו את \"אמתת המצאו\".\nושינוי וחידוש זה שבעולם נעשה ע\"י שינוי וחידוש במצבם של בני ישראל:\nכל זמן שלא ניכר בכאו\"א מישראל שהוא בן אברהם יצחק ויעקב והיא בת שרה רבקה רחל ולאה, נשאר העולם במצב שלא ניכר בו מקורו ושרשו; ועל ידי העבודה לגלות בכל או\"א מישראל את שייכותו והתקשרותו להקב\"ה ולתורתו ומצותיו, הוא פועל שכל העולם כולו נעשה דירה לו ית', \"כאילו בנה עולם\".\nח. ע\"פ הנ\"ל יש לבאר גם הטעם שחז\"ל תלו הגאולה דלעתיד בקיום מצות פו\"ר, כמאמר<sup data-n=\"254\">56</sup> \"אין בן דוד בא עד שיכלו כל נשמות שב(אוצר ששמו) גוף\", ואמרו<sup data-n=\"255\">57</sup> \"כמו שנגאלו ישראל ממצרים בזכות שהיו פרים ורבים כמו כן יגאלו לעתיד בזכות שהן פרים ורבים. . אין ישראל נגאלין אלא א\"כ הם פרים ורבים ויהיו מלא כל העולם\",\nכי ע\"י סיום קיום מצות פו\"ר — הן בגשמיות, עי\"ז שכאו\"א \"לא יבטל\" מקיום מצוה זו \"כל זמן שיש בו כח\" (כפסק דין ברור של הרמב\"ם)<sup data-n=\"256\">58</sup>, והן ברוחניות — שמקרבים כאו\"א מישראל לה' ולתורתו ולמצוותיו,\nבאים לשלימות בנין העולם כולו, דהיינו שתתגלה בו מלכותו של הקב\"ה<sup data-n=\"257\">59</sup>,\nוזה יהי' בתכלית השלימות לעתיד לבא, כאשר יקויים היעוד<sup data-n=\"258\">60</sup> ונגלה כבוד ה' וראו כל בשר יחדיו כי פי ה' דבר.\nואף שכל הגילויים דלעתיד תלויים בכל מעשינו ועבודתנו במשך זמן הגלות<sup data-n=\"259\">61</sup>, הרי מובן שבפרטיות בנין העולם מחדש נעשה ע\"י הוספה בקיום מצות פו\"ר בגשמיות וברוחניות, בנין העולם שבזמן הגלות, שע\"י הוספת נפש אחת בישראל כאילו בנה עולם, וכ\"ש וק\"ו ע\"י הוספת כו\"כ נפשות מישראל,\nוזה ממהר ומזרז בנין \"עולם חדש\"<sup data-n=\"260\">62</sup>, השמים החדשים והארץ החדשה דלעת\"ל<sup data-n=\"261\">63</sup>, והי' ה' למלך על כל הארץ ביום ההוא יהי' ה' אחד ושמו אחד<sup data-n=\"262\">64</sup>.\n<span data-k=\"q\">(משיחת ש\"פ שלח תשמ\"ה) </span>",[["252","54","תנחומא נשא טז. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>."],["253","55","רמב\"ם ריש (ספר היד ו)הל' יסודי התורה."],["254","56","יבמות סב, סע\"א (ובפרש\"י שם). וש\"נ."],["255","57","תנא דבא\"ז ספי\"ד."],["256","58","כאן המקום לעורר עוה\"פ ע\"ד גודל הזכות והאחריות של כאו\"א, ובפרט בדורנו זה, לעסוק ולהוסיף בפו\"ר ולא להתחשב עם חשבונות ואמתלאות (אמת לא) ליבטל ממנה — ראה בפרטיות <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251033\" data-slug=\"likkutei-sichot\" data-id=\"1300251033\">לקו\"ש חכ\"ה ע' 33</a> ואילך. וש\"נ."],["257","59","להעיר מחסד לאברהם (מעין שני נהר סד) בנוגע למצות פו\"ר ד\"שכינה בתחתונים תלוי' במצוה זו\"."],["258","60","ישעי' מ, ה."],["259","61","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["260","62","להעיר דנח עולם חדש ראה (ב\"ר פ\"ל, ח)."],["261","63","מהפטורת שבת זו [תשמ\"ח] — שבת ר\"ח (ישעי' סו, כב)."],["262","64","זכרי' יד, טו."]]],[1301410095,"<h3>שיחה ג</h3>\nא. \"והיתה הקשת בענן וראיתי' לזכור ברית עולם בין אלקים ובין כל נפש חי' בכל בשר אשר על הארץ\"<sup data-n=\"263\">1</sup>. בפירושו מעתיק רש\"י את התיבות \"בין אלקים ובין כל נפש חי'\" ומפרש: \"בין מדת הדין של מעלה וביניכם, שהי' לו לכתוב ביני ובין כל נפש חי', אלא זהו מדרשו, כשתבוא מדת הדין לקטרג עליכם לחייב אתכם אני רואה את האות ונזכר\".\nלפום ריהטא נראה שכוונת רש\"י לתרץ השאלה (שמביא בפירושו) \"שהי' לו לכתוב ביני כו'\" (כיון שכ\"ז הוא חלק מאמירת הקב\"ה, \"ויאמר אלקים\"<sup data-n=\"264\">2</sup>), וע\"ז מפרש שהכוונה ב\"אלקים\" כאן היא ל\"מדת הדין של מעלה\".\nאבל צ\"ע, שהרי מצינו ש\"דרך המקראות לדבר כן\", כמו שפירש רש\"י עצמו בפ' וירא עה\"פ<sup data-n=\"265\">3</sup> \"וה' המטיר על סדום גו' מאת ה' מן השמים\", ש\"אמר מאת ה' ולא אמר מאתו\" — כי \"דרך המקראות לדבר כן\", ומביא ע\"ז כמה דוגמאות, כולל דוגמא מפ' בראשית<sup data-n=\"266\">4</sup> \"כמו נשי למך ולא אמר נשיי\", הרי שכבר בפ' בראשית אתי שפיר לשון הכתוב מטעם ש\"דרך המקראות לדבר כן\".\n[במקומו בפ' בראשית שם לא פרש\"י מאומה. ויש לומר הטעם, כי משם אין הכרח ש\"דרך המקראות לדבר כן\", כיון שהתם ה\"ה דברי למך המובאים במקרא ולא לשון הכתוב עצמו, ולכן אין מזה הוכחה שזוהי גם \"דרך המקראות\". משא\"כ בפ' וירא, שזוהי לשון המקרא — \"וה' המטיר גו' מאת ה'\" — הוכחה ברורה ש\"דרך המקראות לדבר כן\"].\nוכיון ש\"דרך המקראות לדבר כן\" (וכדמצינו בכמה מקומות), מהו הכרחו של רש\"י לפרש את הכתוב כאן ע\"פ \"מדרשו\" (ד\"בין אלקים\" היינו \"בין מדת הדין\"), ולא כפשוטו, דמה שלא נאמר \"ביני\" הוא כי \"דרך המקראות לדבר כן\"<sup data-n=\"267\">5</sup>.\nב. גם צריך להבין האריכות בלשון רש\"י:\nא) ידוע שאין דרכו של רש\"י לכתוב פירושו בדרך קושיא ותירוץ, אלא הוא כותב פירוש הכתוב בסגנון שהקושיא מסתלקת מאלי' — וא\"כ, גם בנדו\"ד הי' מספיק לכאורה שיכתוב \"בין מדת הדין של מעלה כו'\", ומדוע הוזקק רש\"י להאריך ולפרש את השאלה \"שהי' לו לכתוב ביני ובין כל נפש חי'\"?\nב) לכאורה חידושו של רש\"י הוא רק בנוגע לתיבת (\"בין) אלקים\", שפירושה \"מדת הדין של מעלה\" — וא\"כ מדוע (א) הוא מעתיק מהכתוב גם תיבות \"ובין כל נפש חי'\"; (ב) וכן בגוף פירושו חוזר ומפרט \"וביניכם. . ובין כל נפש חי'\" —",[["263","1","פרשתנו ט, טז."],["264","2","ט, יב."],["265","3","יט, כד."],["266","4","ד, כג."],["267","5","ראה גם רד\"ק כאן (ומביא דוגמא מ\"ואל משה אמר עלה אל ה'\" — משפטים כד, א).\nולהעיר, שברד\"ק שם ממשיך \"ואמר אלקים שפירושו דיין כו' כשיהי' הדור רע וראוי לדונם כו' אזכור הברית כו'\" (ע\"ד סיום ל' רש\"י כאן), אף שמפרש ד\"בין אלקים\" הוא \"כאילו אמר ביני\"."]]],[1301410096,"והול\"ל בקיצור: \"בין אלקים — בין מדת הדין של מעלה. . כשתבוא מדת הדין לקטרג כו'\" (וכיו\"ב)?\nג) כל האריכות בסיום פירוש רש\"י — \"כשתבוא מדת הדין לקטרג עליכם לחייב אתכם אני רואה את האות ונזכר\" — היא לכאורה שפת יתר, שאין בה שום חידוש: הן בנוגע לענין הקטרוג — שזה פשוט שמדת הדין ענינה \"לקטרג עליכם\", וכן בהתועלת של אות הברית — שענינה כבר ידוע מהפסוקים שלפנ\"ז<sup data-n=\"268\">6</sup>, \"והי' בענני ענן על הארץ (כשתעלה במחשבה לפני להביא חשך ואבדון לעולם — רש\"י) ונראתה הקשת גו' וזכרתי את בריתי גו' ולא יהי' עוד המים למבול לשחת כל בשר\".\nג. נוסף על האריכות — יש להבין גם כמה דיוקי לשונות של רש\"י, ומהם:\nא) הסדר בפרש\"י תמוה, שבתחילה כותב פירוש הכתוב בקיצור (\"בין מדת הדין של מעלה וביניכם\"), ולאח\"ז מפרש את הקושי בהכתוב (\"שהי' לו לכתוב כו'\"), ואח\"כ חוזר שוב לבאר את פירוש הכתוב — \"אלא זהו מדרשו כשתבוא מדת הדין כו'\"! והי' מתאים יותר להתחיל בהקושיא<sup data-n=\"269\">7</sup> \"הי' לו לכתוב כו'\", ואח\"כ ליישבה<sup data-n=\"269\">7</sup> בפירושו \"אלא זהו מדרשו, בין מדת הדין כו' כשתבוא מדת הדין לקטרג כו'\".\nב) \"אלא זהו מדרשו\" — הרי זה ש\"אלקים\" הוא מדת הדין כבר הובא לעיל בפירושי רש\"י כפשוטו של מקרא [החל מתחילת פ' בראשית, \"בראשית ברא אלקים\", ופרש\"י<sup data-n=\"271\">8</sup> \"ולא אמר ברא ה', שבתחלה עלה במחשבה לבראותו במדת הדין כו'\", וכן בפרשתנו עה\"פ<sup data-n=\"272\">9</sup> \"ויזכור אלקים את נח\" פרש\"י \"זה השם מדת הדין הוא כו'\"] — ומה נשתנה כאן שרש\"י מדגיש ש\"זהו מדרשו\"?\nג) \"מדת הדין של מעלה\" — ולא כתב רש\"י (כבשאר המקומות) \"מדת הדין\" סתם (דמובן מאליו שהכוונה למדת הדין של הקב\"ה)?\n[מקורו של לשון זה הוא במדרש רבה על כתוב זה<sup data-n=\"273\">10</sup>, אבל שם מובן טעם ההוספה, כי זה הלשון במדרש שם: \"בין אלקים ובין כל נפש חי', בין אלקים זו מדת הדין שלמעלה, ובין כל נפש חי' זו מדת הדין של מטה, מדת הדין של מעלה קשה ומדת הדין של מטה רפה\"<sup data-n=\"274\">11</sup>. משא\"כ לפי פרש\"י הרי אאפ\"ל ש\"ובין כל נפש חי'\" היינו \"מדת הדין של מטה\"<sup data-n=\"275\">12</sup> (שהרי זהו היפך הפשט לגמרי<sup data-n=\"276\">13</sup>), אלא ענינו כפשוטו, כלשון רש\"י \"בין מדת הדין כו' וביניכם\". וא\"כ אינו מובן פי' התיבות \"(מדת הדין) של מעלה\"? ובפרט שחסר הביאור בזה שהיא \"קשה\" ודוקא במדרש ישנו אף שהתלמיד גדול יותר].",[["268","6","ט, יד-טו."],["269","7","או להיפך — להתחיל עם הפירוש, ואח\"כ לסיים \"שאל\"כ הי' לו לכתוב ביני כו'\" (וכיו\"ב)."],["269","7","או להיפך — להתחיל עם הפירוש, ואח\"כ לסיים \"שאל\"כ הי' לו לכתוב ביני כו'\" (וכיו\"ב)."],["271","8","ד\"ה ברא אלקים."],["272","9","ח, א."],["273","10","פל\"ה, ג (קרוב לסופו). וראה הערה הבאה."],["274","11","בב\"ר שם בתחילת הפיסקא \"בין אלקים זו מדת הדין שלמעלה ובין כל נפש חי' וגו'\" (ותו לא). אבל ראה מת\"כ שם ד\"סיומא דמילתא למטה בעמוד זה (היינו מה שנעתק בפנים מסיום הפיסקא) ובפי' הרמב\"ן (ט, יב בסופו) גרס כאן סיומא דמילתא\". ויש שאין גורסים זה בתחילת הפיסקא (ראה עץ יוסף ופי' מהרז\"ו שם. ב\"ר הוצאת תיאודור)."],["275","12","וכהערת הרמב\"ן פרשתנו כאן, דמ\"ש רש\"י — \"רבותינו לא לכך נתכוונו\"."],["276","13","ראה גם יפה תואר (השלם) לב\"ר שם. — ובנזר הקודש (השלם) שם מציין לזהר ד\"נפש חי'\" הוא רמז על מדת דין שלמטה שהוא דין רפה. ע\"ש. וראה באר בשדה על פרש\"י כאן ע\"ד הסוד."]]],[1301410097,"ד) \"ביניכם\" — מדוע שינה רש\"י מלשון הכתוב \"ובין כל נפש חי'\"? ואין לומר דהיינו הך אלא שנקט לשון קצר — שהרי אין זה שינוי בלשון בלבד, אלא גם בתוכן, כי \"ביניכם\" ו\"בין כל נפש חי'\" מכוונים לשני סוגים שונים, כמפורש בכתוב שלפנ\"ז \"וזכרתי את בריתי גו' ביני וביניכם ובין כל נפש חי' בכל בשר\" (וכפשטות הענין, ד\"ביניכם\" קאי על בני אדם, ו\"כל נפש חי'\" קאי על כל בעל חי).\nוביותר תמוה: תיכף לאח\"ז ממשיך רש\"י \"שהי' לו לכתוב ביני ובין כל נפש חי'\" (ולא כתב \"וביניכם\")!\nד. ויש לומר הביאור בכל זה:\nעיקר הקושי בכתוב (שאותו בא רש\"י לתרץ בפירושו) אינו \"שהי' לו לכתוב ביני\" (ולא \"בין אלקים\") — כי ע\"ד הפשט הרי \"דרך המקראות לדבר כן\" — אלא רש\"י בא (בעיקר) לתרץ שאלה כללית בכתוב זה — והיא:\nכל פסוק זה, \"והיתה הקשת בענן וראיתי' לזכור ברית עולם בין אלקים ובין כל נפש חי' גו'\", לכאורה מיותר הוא<sup data-n=\"277\">14</sup> — כי כל הפרטים שבו, כבר נאמרו בפסוקים שלפנ\"ז<sup data-n=\"278\">15</sup>: \"את קשתי נתתי בענן והיתה לאות ברית גו' והי' בענני ענן גו' וזכרתי את בריתי אשר ביני וביניכם ובין כל נפש חי' גו' ולא יהי' עוד המים גו'\".\nועכצ\"ל שכתוב זה בא ללמדנו ענין חדש שלא נאמר עדיין<sup data-n=\"279\">16</sup>. וזוהי כוונת רש\"י בהעתיקו מן הכתוב את התיבות \"בין אלקים ובין כל נפש חי'\" — כי בתיבות אלו מרומז החידוש שלא נודע עד כה, ומפרש רש\"י מהו החידוש — \"בין מדת הדין של מעלה וביניכם\".\nכלומר: ה\"ברית\" שבפסוקים הקודמים היא בין הקב\"ה והעולם (\"ביני ובין הארץ\"<sup data-n=\"280\">17</sup>), וענינה, ש\"כשתעלה במחשבה לפני להביא חשך ואבדון לעולם\"<sup data-n=\"281\">18</sup>, אזי \"ונראתה הקשת בענן, וזכרתי את בריתי גו' ולא יהי' עוד המים למבול גו'\". אבל כאן נתוסף עוד ענין של ברית — \"בין מדת הדין. . וביניכם\", היינו שלא זו בלבד שהקב\"ה ירחם אז על העולם ולא יביא מבול, אלא שמדת הדין גופא תחדל מלקטרג ועד שתיהפך לרחמים [וכפשטות לשון (הכתוב ו)רש\"י, שה\"ברית\" היא בין מדת הדין וביניכם].\nוי\"ל שענין זה הוא המשך להנאמר לפנ\"ז<sup data-n=\"272\">9</sup> \"ויזכור אלקים את נח\", ופרש\"י שם ש\"זה השם מדת הדין הוא ונהפכה למדת רחמים על ידי תפלת הצדיקים\", שבהמשך לתפלתו של נח שהפכה את מדת הדין למדת הרחמים, ישנה ברית מיוחדת עם מדת הדין של מעלה, שעל ידי הקשת תתהפך מדת הדין לרחמים.\nועפ\"ז מדוייק לשון רש\"י \"בין מדת הדין של מעלה וביניכם\": (א) מאחר שהמדובר בברית נוספת על הברית שבין הקב\"ה והארץ, יש מקום לטעות שהכוונה בהברית \"בין מדת הדין וביניכם\" היא לברית עם בית דין (\"מדת הדין\") של מטה (שנקרא ג\"כ \"אלקים\"",[["277","14","ראה גם יפה תואר לב\"ר שם."],["278","15","ט, יג-טו."],["279","16","ובפשטות, זוהי כוונת רש\"י בפסוק שלאח\"ז (ט, יז) \"הראהו הקשת וא\"ל הרי האות שאמרתי\" — לתרץ יתור הכתוב."],["280","17","ט, יג."],["281","18","ל' רש\"י שם, יד."],["272","9","ח, א."]]],[1301410098,"בכתוב<sup data-n=\"283\">19</sup>) — שהרי כבר ישנה ברית עם הקב\"ה — ולכן מדגיש רש\"י שגם ברית זו השני' היא עם \"מדת הדין של מעלה\"<sup data-n=\"284\">20</sup>. (ב) רש\"י כ' \"וביניכם\" (ולא \"ובין כל נפש חי'\"), דקאי בפשטות על בני אדם — כי עיקר הצורך ב\"ברית\" עם מדת הדין הוא בנוגע לבני אדם, שעליהם הוא עיקר קטרוגה של מדת הדין (כדיוק לשון רש\"י בהמשך פירושו \"לקטרג עליכם לחייב אתכם\"<sup data-n=\"285\">21</sup>), משא\"כ \"כל נפש חי'\" שלא שייך עליהם (כ\"כ) קטרוג של מדת הדין כיון שאינם בעלי בחירה<sup data-n=\"286\">22</sup>.\nה. אלא שעדיין קשה: איך אפ\"ל שהחידוש בכתוב זה הוא שכאן מדובר בברית ש\"בין אלקים גו'\" (מדת הדין של מעלה) — והרי גם הפסוקים שלפנ\"ז הם דברים שנאמרו על ידי \"אלקים\", כהתחלת הפסוקים \"ויאמר אלקים\", וא\"כ גם הברית ש\"ביני ובין הארץ\" היא \"בין אלקים גו'\"<sup data-n=\"287\">23</sup> (שאמר ע\"ד ברית זו), דהיינו מדת הדין, והדרא קושיא לדוכתא, מה נתחדש בפסוק זה?\nולכן ממשיך רש\"י לבאר ולהוכיח, שאכן הדיוק \"בין אלקים\" הוא הוא החידוש שבפסוק זה — \"שהי' לו לכתוב ביני ובין כל נפש חי'\". כלומר, אין כוונת רש\"י כאן להקשות איך מתאים לכתוב \"בין אלקים\" (מאחר שהוא דיבור המתחיל ב\"ויאמר אלקים\"), אלא לדייק השינוי בין פסוק זה להקודם לו — ששם נאמר \"וזכרתי את בריתי אשר ביני וביניכם גו'\", ומאי טעמא משנה כאן הכתוב ואומר \"בין אלקים\"? ומזה מוכח, שזהו החידוש בהברית שבפסוק זה לגבי הברית שבפסוק הקודם: אע\"פ שגם בהפסוקים שלפנ\"ז נאמר שם אלקים, אעפ\"כ אין בזה הוכחה דמ\"ש \"ביני\" היינו מדת הדין; משא\"כ בפסוק זה, מכיון שבמקום \"ביני\" כתוב \"בין אלקים\", יש ללמוד שהכוונה כאן היא למדת הדין.\nוההסברה בזה:\n\"אלקים\" פירושו (כפרש\"י לעיל<sup data-n=\"288\">24</sup>) \"שליט ושופט\" (ובמק\"א<sup data-n=\"289\">25</sup> כ' \"כל אלקים שבמקרא לשון מרות\"), שמזה מובן, ששם אלקים אינו מורה בכל מקום על מדת הדין (בניגוד למדת הרחמים), אלא הכוונה להקב\"ה כשליט על הארץ. וכן בעניננו, דמ\"ש לעיל \"ויאמר אלקים זאת אות הברית גו'\", המכוון הוא שהקב\"ה הוא השולט על הארץ, וקבע בעולמו אות ברית — \"את קשתי נתתי בענן גו'\". משא\"כ בפסוק דידן, כנ\"ל.\nועפ\"ז מובן המשך לשון רש\"י \"אלא זהו מדרשו כשתבוא כו'\" — כי ע\"פ פשט הכתוב, מש\"נ \"בין אלקים\" הוא כאילו הי' כתוב כאן \"ביני\" (וכנ\"ל שכן הוא",[["283","19","משפטים כא, ו (וברש\"י). שם כב, זח (וברש\"י). שם, כז (וברש\"י). ובכ\"מ. — וכן ברש\"י לעיל בראשית ו, ב."],["284","20","בסגנון אחר קצת: כיון שגם הברית הא' היא בין אלקים והארץ (שהרי \"ביני\" קאי על \"ויאמר אלקים\" שבפסוק יב. וראה לקמן סעיף ה) — מוכרח להדגיש, שגם \"אלקים\" שבברית הב' היינו הקב\"ה (\"של מעלה\"), אלא שהברית היא עם מדת הדין שלו."],["285","21","בדפוס ראשון ושני דפרש\"י, ובכת\"י רש\"י שתח\"י ליתא \"עליכם לחייב אתכם\". אבל בדפוסי רש\"י הנפוצים הוא כבפנים."],["286","22","אע\"פ שבדור המבול \"אף הם (הבהמות כו') השחיתו דרכם\" (רש\"י ס\"פ בראשית. וראה גם רש\"י נח, ו, יב) — מ\"מ מובן שעיקר העונש הי' מצד השחתת האדם (ראה נח ו, יג ובפרש\"י שם). ובפרט לפי' הב' שבפרש\"י ס\"פ בראשית שם. וראה גם רש\"י קדושים כ, טו. בלק כב, לג. ואכ\"מ."],["287","23","וראה רד\"ק כאן \"בין אלקים כאילו אמר ביני כמו שאמר למעלה\"."],["288","24","בראשית ב, ה ד\"ה ה' אלקים."],["289","25","רש\"י בראשית ו, ב. — וראה טושו\"ע (ודאדה\"ז) או\"ח סוס\"ה."]]],[1301410099,"דרך המקראות לדבר), אלא שע\"פ מדרש אפשר לפרש, דמש\"נ שתי פעמים \"אלקים\" בכתובים אלו (\"ויאמר אלקים גו' והיתה הקשת גו' לזכור ברית עולם בין אלקים ובין כל נפש חי' גו'\"), הנה השם הראשון קאי על הקב\"ה (ה\"שליט ושופט\"), והשני על מדת הדין של מעלה.\n[נוסף לזה, שעצם הפירוש, שהקב\"ה עשה ברית בין \"מדת הדין\" שלו ובין הארץ, אינו ענין של פשט אלא מדרש ואגדה].\nו. אמנם, אא\"פ לרש\"י להסתפק בכך, כי אינו מובן — סו\"ס מהו החידוש של הברית הב' לגבי הברית הא'? כיון שכל פעם \"שתעלה במחשבה לפני להביא חשך ואבדון לעולם\" יזכור הקב\"ה את בריתו שלא \"לשחת כל בשר\" — למאי נפק\"מ ומה מוסיפה הברית עם מדת הדין (\"בין אלקים\"), שמדת הדין עצמה מתהפכת לרחמים?\nולכן מסיים רש\"י \"כשתבוא מדת הדין לקטרג עליכם לחייב אתכם אני רואה את האות ונזכר\": \"קטרוג\" פירושו לא רק טענה הבאה לחייב את האדם ולהענישו כפי מעשיו, אלא זוהי טענה והשתדלות יתירה<sup data-n=\"290\">26</sup> לחייבו יותר ממה שהוא מחוייב מצד שורת הדין.\nע\"ד שמצינו (גם בפרש\"י<sup data-n=\"291\">27</sup>) שהשטן מקטרג בשעת הסכנה — דלכאורה, ממנ\"פ: אם האדם חייב עונש, מדוע אין השטן מקטרג גם שלא בשעת הסכנה? ואם אינו חייב כלום, מה יועיל לו להשטן קטרוגו? אלא הפירוש בזה, שיש ענינים שבזמנים רגילים אין מענישים עליהם, אלא שכשיש סכנה וצריכים שמירה יתירה, אזי מועיל קטרוגו של שטן לחייב את האדם גם על ענינים אלו.\nוכן בעניננו: יש מצבים שהנהגת העולם היא באופן שגורמת מחשבה לפני הקב\"ה \"להביא חשך ואבדון לעולם\", וע\"ז באה הברית הא' \"ביני ובין הארץ\", שהקב\"ה יזכור את הברית ולא ישחת עוד את הארץ.\nאבל לפעמים יש מצב ששייך קטרוג<sup data-n=\"292\">28</sup> מצד \"מדת הדין\", \"לחייב אתכם\" עוד יותר מכפי שורת הדין, וכדי לבטל מעיקרא דבר כזה, עשה הקב\"ה עוד ברית \"בין אלקים ובין כל נפש חי'\", דהיינו \"בין מדת הדין של מעלה וביניכם\", שעל ידי זה נשללת מעיקרא האפשריות של קטרוג, וכדיוק לשון רש\"י \"כשתבוא מדת הדין לקטרג כו'\" אזי תיכף \"אני רואה את האות ונזכר\", באופן שמלכתחילה אינו בא לידי קטרוג בפועל,\nכי מדת הדין עצמה נהפכת לרחמים, והיא פוסקת אך טוב לישראל, בטוב הנראה והנגלה, למטה מעשרה טפחים.\n<span data-k=\"q\">(משיחת ש\"פ נח תשד\"מ) </span>",[["290","26","ראה רע\"ב לאבות (פ\"ד מי\"א) \"ולשון קטיגור קורא תיגר\". ובערוך (מע' קטיגור) \"מלשון רכיל\". וראה רש\"י סוף כתובות \"מסטינים ומלמדים חובה\"."],["291","27","מקץ מב, ד. ויגש מד, כט."],["292","28","ולהעיר ממדרש לקח טוב (וכן בטור הארוך ופענח רזא) עה\"פ (לעיל ט, יד) \"והי' בענני ענן גו'\" — \"מלמד שאין השטן מקטרג אלא בשעת הסכנה\". וע\"פ המבואר בפנים מובן, שתוכן ענין זה שייך (לפרש\"י) לברית הב' (שבפסוק טז), משא\"כ לעיל שם פרש\"י (כנ\"ל בפנים) \"כשתעלה במחשבה לפני כו'\". ולהעיר שבכמה כת\"י רש\"י שתח\"י, בא פרש\"י על פסוק יד לאחרי פירושו כאן בפסוק טז."]]],[1301410100,"<h3>שיחה א</h3>\nא. בפרשתנו מסופר ע\"ד שלש מזבחות שבנה אברהם אבינו: (א) ויבן שם מזבח לה' הנראה אליו<sup data-n=\"293\">1</sup>, (ב) ויבן שם מזבח לה' ויקרא בשם ה'<sup data-n=\"294\">2</sup>, (ג) ויבן שם מזבח לה'<sup data-n=\"295\">3</sup>. וביארו חז\"ל<sup data-n=\"296\">4</sup>: ג' מזבחות בנה אחד לבשורת א\"י וא' לקנינה וא' שלא יפלו בניו. כלומר, שכל אחד מג' מזבחות אלו בנה אברהם לשם ענין בפ\"ע<sup data-n=\"297\">5</sup>: הראשון, שנבנה לאחר דיבור השם אל אברם \"לזרעך אתן את הארץ הזאת\"<sup data-n=\"293\">1</sup>, הי' \"לבשורת א\"י\"; המזבח שבנה סמוך לעי הי' לשם תפלה<sup data-n=\"299\">6</sup> \"שלא יפלו בניו בעי\"<sup data-n=\"300\">7</sup>; והמזבח השלישי, שבנה לאחר קיום ציווי ה' \"קום התהלך בארץ לארכה ולרחבה כי לך אתננה\"<sup data-n=\"301\">8</sup>, שעי\"ז \"זכה בה\"<sup data-n=\"302\">9</sup>, הי' \"לקנינה\" (של א\"י)<sup data-n=\"303\">10</sup>.\nרש\"י בפירושו על התורה מביא תוכן דברי המדרש בנוגע לשני המזבחות הראשונים — על הפסוק \"ויבן שם מזבח\" (שנאמר בפעם הראשונה) מפרש \"על בשורת הזרע ועל בשורת א\"י\", ועל \"ויבן שם מזבח\" השני כותב \"נתנבא שעתידין בניו להכשל שם על עון עכן והתפלל שם עליהם\" — אבל בנוגע למזבח השלישי (לאחר ציווי ה' \"קום התהלך בארץ גו'\") סתם רש\"י ולא פירש כלום.\nהטעם שלא פירש רש\"י כהמדרש<sup data-n=\"304\">11</sup> שהמזבח השלישי הי' \"לקנינה\" — יש לומר: דברי המדרש הם להשיטה<sup data-n=\"305\">12</sup> שע\"י הליכת אברהם לארכה ולרחבה \"זכה בה\" (שעל ידי הילוך קנה)<sup data-n=\"306\">13</sup>, ולכן מתאים לומר שמזבח זה הי' \"לקנינה\"<sup data-n=\"307\">14</sup>; ואולם, לפי פרש\"י על התורה, בפשוטו של מקרא — לא הי' בהילוכו של אברהם",[["293","1","יב, ז."],["294","2","יב, ח."],["295","3","יג, יח."],["296","4","ב\"ר (פרשתנו) ספל\"ט."],["297","5","כמ\"ש במפרשי המדרש (פירוש המיוחס לרש\"י. מת\"כ. פי' מהרז\"ו. ועוד)."],["293","1","יב, ז."],["299","6","כמ\"ש בת\"א יב, ח \"(ויקרא) וצלי\". וכ\"ה לכמה גי' בהמשך דברי המדרש (ראה ב\"ר הוצאת תיאודור). וביל\"ש עה\"פ (הובא במהרז\"ו. ע\"ש)."],["300","7","המשך הלשון בב\"ר שם."],["301","8","יג, יז."],["302","9","לשון המת\"כ לב\"ר שם (ע\"פ ב\"ר עה\"פ — ראה לקמן הערות 12, 13)."],["303","10","ובב\"ר לא נקט כסדרם של הפסוקים, כי \"איידי דבעי לפרש מעשה דיהושע (שבעי) קודם נקט ועשאו אחרון\" (פי' המיוחס לרש\"י לב\"ר שם. וראה גם יפ\"ת השלם, פי' מהרז\"ו ועוד)."],["304","11","ומה ששינה רש\"י במזבח הא' והוסיף (והקדים<sup data-n=\"e4\">*</sup>) \"על בשורת הזרע\" — ראה מפרשי רש\"י (גו\"א. הואיל משה (באר היטב). שפ\"ח. משכיל לדוד. ועוד)."],["305","12","בב\"ר ספמ\"א (וכן בב\"ב ק, א) דעת ר' אליעזר. ולהעיר שבעל המאמר בב\"ר פל\"ט הוא ג\"כ ר\"א [ואת\"ל דר\"א בן שמוע (בב\"ר שם) הוא המשך ללפני זה — לכאורה בעל המאמר הוא ר\"א התנא]."],["306","13","כ\"ה לפי' המת\"כ לב\"ר. ועד\"ז בפי' מהרז\"ו. וראה יפ\"ת (השלם) לב\"ר שם (ועוד), דאתי גם לדעת חכמים שם. וראה תו\"ח ב\"ב שם ד\"ה משום חביבותא. כוס ישועות ויפה עינים שם. ואכ\"מ."],["307","14","וראה גם תיב\"ע עה\"פ (וב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151101\" data-slug=\"likkutei-sichot\" data-id=\"1300151101\">לקו\"ש חט\"ו ע' 101</a> והערה 16 שם). רמב\"ן יג, טו (ע\"ד הדרש כו', וכהמשכו: וע\"ד הפשט כו'). ובש\"ך עה\"ת מפרש, דויבן שם מזבח הי' \"כדי להחזיק בה\". ע\"ש."],["e4","*","כ\"ה בדפוסי רש\"י שלפנינו, דפוס שני דרש\"י וכמה כת\"י רש\"י (שתח\"י). ובדפוס ראשון וכמה כת\"י רש\"י (שתח\"י) נאמר \"על בשורת א\"י\" לפני \"על בשורת הזרע\"."]]],[1301410101,"לארכה ולרחבה משום קנין הארץ, וכסיום הכתוב עצמו \"קום התהלך גו' כי לך אתננה\" — לשון עתיד, היינו שההליכה היא רק לסמן את אורך ורוחב הארץ שהקב\"ה עתיד ליתנה לו<sup data-n=\"308\">15</sup>. וא\"כ אין לפרש שמזבח זה בנה \"לקנינה\".\nאבל טעמא בעי: מאחר שנחית רש\"י לבאר הטעם של כל אחד משני המזבחות הראשונים שבנה אברהם — מדוע לא ביאר טעם על בנין מזבח השלישי?\nב. לפי פשוטו יש לומר:\nלאחרי שפירש רש\"י כי אברהם בנה מזבח עבור הבשורות טובות — \"בשורת הזרע\" \"בשורת א\"י\" — שוב אין צורך לחפש טעם אחר על בנין המזבח השלישי, כי כמפורש בקרא בנה אותו אברהם לאחרי שנתבשר בשו\"ט<sup data-n=\"309\">16</sup> \"כי את כל הארץ אשר אתה רואה לך אתננה ולזרעך עד עולם, ושמתי את זרעך כעפר הארץ גו'\" — היינו כו\"כ ברכות וענינים טובים, הן בבשורת א\"י והן בבשורת הזרע<sup data-n=\"310\">17</sup>, ששמע אברהם בבשורה זו דוקא, שלא נאמרו בבשורה הראשונה<sup data-n=\"311\">*17</sup> — ומובן מאליו שבגלל בשורות נוספות אלו בנה אברהם מזבח מיוחד לה'.\nאמנם ביאור זה דחוק הוא מפני לשון הכתובים: \"ויבן שם מזבח\" משמע, שבנין המזבח הי' שייך להמקום שנבנה בו. וע\"ד שמצינו בשני מזבחות הראשונים — ש(גם) בהם נאמר \"ויבן שם מזבח\" — שהיו \"שייכים\" וקשורים עם מקום בנייתם<sup data-n=\"312\">18</sup>: המזבח הראשון, שהי' \"לה' הנראה אליו\", בנאו אברהם \"שם\" דוקא, כי במקום זה נראה ה' אליו<sup data-n=\"313\">19</sup>; ומזבח השני",[["308","15","וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151204\" data-slug=\"likkutei-sichot\" data-id=\"1300151204\">לקו\"ש חט\"ו ע' 204</a> ואילך, שמוכח בכ\"מ בפרש\"י שלדעת רש\"י בפירושו עה\"ת לא נקנתה א\"י לאברהם (ולא — בכלל — להאבות), משא\"כ לדעת המדרש וע\"ד ההלכה. וראה גם לקו\"ש ח\"כ ע' 131 ואילך."],["309","16","יג, טו-טז."],["310","17","ולכן אף את\"ל שאין מקום לבנות מזבח על חזרת בשורה עוה\"פ (ראה יפ\"ת השלם לב\"ר שם, כב) — בנדו\"ד שנתוספו כאן פרטים, ופרטים עיקריים, ה\"ז כמו בשורה חדשה. ובדפוס ראשון וכת\"י רש\"י (שתח\"י), ישנה אריכות בפרש\"י עה\"פ (יג, טז) ע\"ד בני ישראל, שאינה בפרש\"י לפנינו, וז\"ל: ושמתי את זרעך כעפר הארץ שיהו מפוזרין בכל העולם<sup data-n=\"e5\">*</sup> כעפר המפוזר ועוד שאם אין עפר אין בעולם אילנות ותבואה כך אם אין ישראל אין העולם מתקיים שנאמר והתברכו בזרעך אבל לימות המשיח משולין כחול שמקהה שיני הכל כך יפלו ויקהו כל העולם שנאמר ולו יקהת עמים. וראה גם פרש\"י שבהערה 25."],["311","*17","ולכמה מפרשים (ריב\"א וחי' ופי' מהרי\"ק על פרש\"י — יג, יד), מש\"כ רש\"י (שם) ש\"הי' הדבור פורש ממנו\" (מאברהם) ורק כאן נאמר \"וה' אמר אל אברם\" — כי לפנ\"ז (בפסוק יב, ז) \"לא הי' מאריך עמו כ\"כ בדברים\"."],["312","18","ועד\"ז הוא בשאר המקומות בתורה שנאמר \"ויבן שם מזבח\" וכיו\"ב (ראה וירא כב, ט. תולדות כו, כה. וישלח לג, כ. לה, ז), שבכולם בא הכתוב להדגיש שהי' ענין מיוחד במקום ההוא, שלכן בנה המזבח שם דוקא."],["313","19","אלא שרש\"י מפרש \"על בשורת הזרע ועל בשורת א\"י\", לשלול הפירוש שבניית המזבח היתה ע\"ז שנראה אליו ה'<sup data-n=\"e6\">*</sup> (רמב\"ן, צידה לדרך ואוה\"ח יב, ז). אבל גם לפרש\"י ה\"ז שייך לבשורת הזרע ובשורת א\"י שנתבשר כאן (\"לזרעך אתן את הארץ הזאת\"), ולא למש\"נ בתחילת הסדרה \"ואעשך לגוי גדול\". וראה מפרשי רש\"י שבהערה 11. באר מים חיים (לאחי המהר\"ל) שם, ח. מלאכת הקודש על פרש\"י. יפ\"ת שבהערה 17. ואכ\"מ."],["e5","*","ובכת\"י הנ\"ל: מפוזרין מסוף העולם ועד סופו. . כך יקהו ויפלו כל כו'."],["e6","*","והטעם י\"ל, כי לא מצינו שבכל פעם שנגלה ה' לאברהם בנה מזבח — ראה לדוגמא ריש (וסוף) פרשתנו. וראה מפרשי רש\"י שבפנים ההערה (בסופה)."]]],[1301410102,"נבנה \"שם\", בסמיכות לעי, כי נבנה (כפרש\"י) מטעם ש\"נתנבא שעתידין בניו להכשל שם כו' ו(לכן) התפלל שם עליהם\"<sup data-n=\"314\">20</sup>;\nואת\"ל שבנין מזבח זה (השלישי) הי' בגלל הבשורות טובות שנתבשר קודם בואו לחברון [ומה שבנה המזבח בחברון דוקא, הוא רק משום שזהו המקום שאליו בא לאחרי קיום ציווי הקב\"ה<sup data-n=\"315\">21</sup> (בבשורת הארץ) \"קום התהלך בארץ גו'\"<sup data-n=\"316\">*21</sup>] — אין שום שייכות, לכאורה, בין טעם בניית המזבח למקום זה דוקא; והכתוב הרי מדייק \"ויבן שם מזבח\"?\nע\"ד הפשט יש לבאר הקשר דמזבח זה למקומו, כי זה הי' המקום הראשון בארץ ישראל שבו נתיישב אברהם אבינו בקביעות. שהרי עד אז הי' אברהם במצב של \"הלוך ונסוע\"<sup data-n=\"317\">22</sup>, \"וילך למסעיו\"<sup data-n=\"318\">23</sup>, ורק בבואו לחברון התיישב בארץ, כמ\"ש<sup data-n=\"295\">3</sup> \"וישב באלוני ממרא אשר בחברון\" (וכמסופר לאח\"ז, שאברהם ישב שם כ\"ה שנה<sup data-n=\"320\">24</sup>). ובמילא מובן, שזהו המקום המתאים להודות להקב\"ה על \"בשורת (התיישבותו — קבע ב)א\"י\".\nאמנם עדיין אין הענין מתיישב כל צרכו (בדרך הדרש). כי את\"ל שמזבח זה (השלישי) בא (רק) על הבשורות \"כי גו' לך אתננה גו' ושמתי גו'\", הו\"ל להדגיש (עכ\"פ — לרמז) בהכתובים שבנינו הי' בסמיכות ובהמשך לשמיעת הבשורות; אבל בלשון הפסוק מודגש ההיפך, ההפסק והשהיי' שבין בשורות אלו לבנין המזבח — \"ויאהל אברם ויבא וישב גו' (ורק אח\"כ) ויבן שם מזבח לה'\"<sup data-n=\"321\">25</sup>.\nולכן מסתבר, שבנין המזבח הי' (גם) ענין בפ\"ע, בשייכות להתיישבותו בעיר חברון<sup data-n=\"322\">26</sup>.\nג. ויש לומר הביאור בזה:\nאמרו חז\"ל<sup data-n=\"323\">27</sup> \"סימן נתן לו הקב\"ה לאברהם שכל מה שאירע לו אירע לבניו\", מעשה אבות סימן לבנים, וכמ\"ש הרמב\"ן<sup data-n=\"324\">28</sup> ד\"כולם (כל מעשי האבות) באים ללמד על העתיד כי כאשר יבוא המקרה לנביא משלשת האבות יתבונן ממנו הדבר הנגזר לבוא לזרעו\", ואולי י\"ל, שמעשה האבות הוא סימן, גרם<sup data-n=\"325\">29</sup>",[["314","20","ובזה מתורץ ג\"כ — מנ\"ל לרש\"י (בפשש\"מ) שמזבח זה הי' שייך וקשור עם נבואה זו (שלכאורה פירוש זה רחוק מדרך הפשט) — כי דוקא עפ\"ז מובן דיוק הלשון \"ויבן שם מזבח\", שבניית המזבח היא בשייכות למאורע שאירע שם דוקא (ראה גו\"א (וראה גם רע\"ב) על פרש\"י כאן)."],["315","21","אבל ראה אברבנאל כאן: שעם היות שאמר ית' לאברם קום התהלך בארץ לארכה ולרחבה הנה הוא בענותנותו לא עשה כן כו'. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071093\" data-slug=\"likkutei-sichot\" data-id=\"1300071093\">לקו\"ש ח\"ז (ע' 81</a>, 86) שכ\"ה לפרש\"י (יב, ד) ש\"וישב\" כאן הוא ל' עכבה."],["316","*21","להעיר מש\"ך עה\"ת הנ\"ל הערה 14."],["317","22","יב, ט."],["318","23","יג, ג."],["295","3","יג, יח."],["320","24","פרש\"י וירא כא, לד."],["321","25","דאם בא להדגיש שזה הי' אחר קיום ציווי ה' \"קום התהלך בארץ גו'\", הו\"ל להכתוב להדגיש העיקר \"וילך אברם גו'\", ולא (רק) \"ויאהל אברם\" (וראה ש\"ך עה\"ת שם).\nולהעיר שבדפוס ראשון דפרש\"י שם יג, יח איתא \"ויאהל אברם, שחזר לאשתו כשראה שאינו מוליד פירש ממנה כיון שאמר לו הב\"ה ושמתי את זרעך חזר לה\". — אבל ליתא בשאר הדפוסים וכת\"י (שתח\"י)."],["322","26","להעיר ממדרש הגדול פרשתנו יג, יח — הובא לקמן בפנים סעיף ח."],["323","27","תנחומא פרשתנו ט. ועד\"ז בב\"ר פ\"מ, ו."],["324","28","פרשתנו יב, ו. וראה שם יב, יו\"ד. יד, א. תולדות כו, א. וישלח לב, ד. וראה גם בהנסמן בהערה 63."],["325","29","וע\"ד שמצינו בנוגע לסימני טהרה וטומאה דבהמה, ד\"הסימנים הם הגורמים הטהרה והטומאה (אבל בסימני עופות וסימני חי' לגבי חלבה זה רק הוה סימן (המברר) איזהו הטהור ואיזה היא החי')\" — צפע\"נ על הרמב\"ם הל' מאכלות אסורות פ\"א ה\"א. וראה לקמן ע' 117 הערה 17."]]],[1301410103,"למאורעות הבנים. ועפ\"ז בעניננו, מזבחות אלו שבנה אברהם הם הם ההכנה ונתינת כח לעבודת הקרבנות<sup data-n=\"326\">30</sup> (של בני ישראל) ע\"ג המזבח במשכן ומקדש.\nוזוהי נקודת הטעם שבנה אברהם שלשה מזבחות — כי ב\"מזבח\" של ה\"בנים\" מצינו ג' פעולות וענינים, ש(ה\"סימן\" ו)נתינת הכח להם הם שלשה מזבחות אלו שבנה אברהם.\nוההסברה:\nבנוגע לענינו של מזבח אמרו חז\"ל<sup data-n=\"327\">31</sup> — \"מזבח, מזיח ומזין מחבב מכפר\", כלומר: מזיח גזירות<sup data-n=\"328\">32</sup> (רעות מעל ישראל<sup data-n=\"329\">33</sup>); מזין, בזכות הקרבנות העולם נזון שהקרבנות באין מן המזון וגורמין לו ברכה<sup data-n=\"329\">33</sup>; מחבב את ישראל אל אביהם<sup data-n=\"329\">33</sup>; ומכפר עונות<sup data-n=\"328\">32</sup>.\nארבעה דברים אלו מתחלקים, בכללות, לשלשה סוגים: א) \"מזין\" — השפעת מזון לעולם, ב) \"מזיח ומכפר\" — ביטול ענינים בלתי רצויים מעל ישראל (גזירות ועונות). ג) \"מחבב את ישראל אל אביהם\".\nוהנה, חלוקה כזו של \"ארבעה שהן שלשה\" אנו מוצאים גם בחלוקת הקרבנות (על המזבח) למיניהם — שהרמב\"ם<sup data-n=\"333\">34</sup> מחלק את הקרבנות ל\"ארבעה מינין, עולה וחטאת ואשם ושלמים\", ואילו במדרש<sup data-n=\"334\">35</sup> מצינו שמחלקם לשלשה — \"עולה שלמים וחטאת\". ומובן שאין כאן סתירה, כי חטאת ואשם תוכנם אחד<sup data-n=\"335\">*35</sup>, שניהם באים לכפרה.\nועפ\"ז יש לומר, ששלש פעולות הנ\"ל שבקרבנות מכוונות כנגד שלשה סוגים אלו שבקרבנות<sup data-n=\"336\">36</sup>:\nשלמים, שיש בהם אכילת בעלים, הם כנגד זה שהמזבח (קרבנות) \"מזין\" את העולם, דכשם שהבעלים זוכים באכילתם זו (שהיא אכילה גשמית, מזון הגוף) על ידי הקרבת קרבן לה', כך \"בזכות הקרבנות העולם נזון\";\nחטאת (ואשם) שבאו לכפרה — היינו \"מזיח. . מכפר\";\nוהעולה, שהיא כליל לה', ענינה ל\"חבב ישראל אל אביהם\"<sup data-n=\"337\">37</sup>, ובלשון המדרש<sup data-n=\"338\">38</sup>, ש\"העולה נקרבת לכבוד הקב\"ה בלבד אבל השלמים והחטאת בעד (כנגד) עצמנו\", כלומר, השלמים והחטאת באים (בעיקר?, גם?) לתועלת המקריב (או בשביל קבלת מזון, או כדי לבטל ענינים בלתי רצויים), משא\"כ העולה",[["326","30","ואף שגם יצחק ויעקב בנו מזבחות, כנסמן לעיל הערה 18 (וראה פרש\"י בלק כג, ד \"אבותיהם של אלו בנו לפניך שבעה מזבחות כו'\"), יש בהם \"סימן לבנים\" משלהם. ולהעיר שבמדרשים הנ\"ל (הערה 27) מפורש הענין דמעשה אבות סימן לבנים רק בנוגע לאברהם — \"סימן נתן לו הקב\"ה לאברהם שכל מה שאירע לו אירע לבניו\", ומפרט כו\"כ דברים שאירעו לאברהם ואירעו עד\"ז לבניו."],["327","31","כתובות י, ב."],["328","32","ל' הגמ' שם."],["329","33","פרש\"י שם."],["329","33","פרש\"י שם."],["329","33","פרש\"י שם."],["328","32","ל' הגמ' שם."],["333","34","הל' מעשה הקרבנות פ\"א ה\"ב."],["334","35","מדרש תדשא (הנק' ג\"כ ברייתא דר\"פ בן יאיר) פי\"ב<sup data-n=\"e7\">*</sup>. ס' רזיאל המלאך (בשינויים קלים)."],["335","*35","ראה גם רמב\"ן פרשתנו טו, ט."],["336","36","ראה באופן אחר קצת — חדא\"ג מהרש\"א כתובות שם. והמבואר בפנים הוא ע\"פ המדרש תדשא."],["337","37","להעיר שעולה דורון הוא — זבחים ז, ב."],["338","38","מדרש תדשא וס' רזיאל המלאך שם. ע\"ש."],["e7","*","הובאו קטעים מפרק זה בס' הרוקח בתחלתו. הגהמ\"י הל' יסוה\"ת פ\"ב."]]],[1301410104,"באה רק \"לכבוד הקב\"ה בלבד\", ועל ידה מתחבבים ישראל אל אביהם שבשמים<sup data-n=\"339\">39</sup>.\nד. ויש לומר, ששלש פעולות הנ\"ל ישנן, בכללות, בכל קרבן, כי בכולם יש שלשה ענינים: א) זריקת הדם ע\"ג המזבח; ב) אכילת כהנים ובעלים (וגם בקרבן עולה — עורה לכהנים<sup data-n=\"340\">40</sup>); ג) גילוי שכינה — האש שירדה מן השמים ו\"אכלה\" את הקרבנות<sup data-n=\"341\">41</sup> (ובכללות יותר — מה שמקום המזבח הוא בביהמ\"ק, בלשון הרמב\"ם<sup data-n=\"342\">42</sup> \"בית לה' מוכן להיות מקריבים בו הקרבנות\"):\nחלק הקרבן הנאכל (ושייך) לכהנים ולבעלים — מרמז על פעולת \"הזנת העולם\", כנ\"ל;\nזריקת הדם ע\"ג המזבח היא היא הפועלת כפרת<sup data-n=\"343\">43</sup> העונות וריצויין (ש\nזה כולל ריצוי על כל ענינים בלתי רצויים);\nוגילוי השכינה שבקרבנות (האש שיורדת מן השמים, ובכללות, זה שהמזבח הוא בבית המקדש, \"בית לה'\") מורה על חביבותם של ישראל<sup data-n=\"344\">44</sup>, ועד \"כדרך שבא לראות כך בא ליראות\"<sup data-n=\"345\">45</sup>, שכל התגלות זו היא בשביל ישראל עם קרובו.\nה. ידוע שעבודת הקרבנות נקראת בשם \"עבודה\" סתם<sup data-n=\"346\">46</sup>, משום שבה מתבטא כללות הענין דעבודת השם.\nומזה מובן, דכשם שבקרבנות ישנם ג' הענינים הנ\"ל — כמו\"כ הוא בנוגע לכללות הענין דעבודת השם, שג' חלוקות בה:\nראשיתה היא העבודה דתורה ומצות, מזון הנפש (\"מזין\"), כי התורה היא \"חיינו\", ונאמר (גבי מצות) \"אשר יעשה אותם האדם וחי בהם\"<sup data-n=\"347\">47</sup>, וכידוע שרמ\"ח מ\"ע הם כנגד רמ\"ח אברים<sup data-n=\"348\">48</sup>, ועל ידי קיום התומ\"צ ממשיכים חיות (הנשמה) תוך אברי האדם<sup data-n=\"349\">49</sup>.\nלמעלה מזה היא עבודת התשובה, דגם כאשר חטא ופגם ועבר את הדרך ר\"ל, מתקן זה ע\"י התשובה (\"מכפר\" ו\"מזיח\").\nאמנם שלימות ענין הדביקות בו יתברך היא העבודה דמסירת נפש, זה שהאדם מוסר את עצמו מכל וכל להקב\"ה (כמו עולה שהיא כליל לה'). שזוהי אמיתית ענין המסירת נפש, שמוסר נפשו לא בשביל שכר או בשביל איזוהי תועלת (גשמית, או) רוחנית (שתגיע לנשמתו)<sup data-n=\"350\">50</sup>, כ\"א רק לכבודו ית', בלי שום חשבון כלל וכלל<sup data-n=\"351\">51</sup>. ובזה שהאדם מקריב (ומבטל) את עצמו כליל להקב\"ה, ואינו",[["339","39","וראה גם אדר\"נ רפ\"ד."],["340","40","צו ז, ח."],["341","41","יומא כא, ב."],["342","42","ריש הל' ביהב\"ח."],["343","43","תו\"כ ויקרא א, ד. זבחים ו, א. וש\"נ."],["344","44","ראה יומא שם דרק בבית ראשון הי' אש יורד מן השמים (רבוצה כארי) ואוכל הקרבנות (משא\"כ בבית שני ד\"סיועי לא מסייעא\", אבל ירדה מלמעלה). ולהעיר מגמ' שם לפנ\"ז בנוגע להנס בלחם הפנים \"אומרים להם ראו חיבתכם לפני המקום שסילוקו כסידורו\"."],["345","45","חגיגה ב, א (וש\"נ). וראה אוה\"ת בראשית וירא קג, ב ואילך."],["346","46","ראה מפרשים לאבות פ\"א מ\"ב."],["347","47","אחרי יח, ה."],["348","48","מכות כג, סע\"ב. הובא בהקדמת הרמב\"ם לספר היד בסופה. ובכ\"מ."],["349","49","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו\"ת נצבים מה, ג</a>."],["350","50","וכלשון הרמב\"ם הל' תשובה פ\"י ה\"ב: לא מפני דבר בעולם כו' לא כדי לירש הטובה (חיי עוה\"ב — שביאר בריש הפרק ובפ\"חט שם) אלא עושה האמת מפני שהוא אמת."],["351","51","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a> ופי\"ט. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201075\" data-slug=\"likkutei-sichot\" data-id=\"1300201075\">לקו\"ש ח\"כ ע' 75</a> ואילך."]]],[1301410105,"מחפש לעצמו כלום, הרי הוא \"מחבב את ישראל אל אביהם\".\nו. עפ\"ז יובן תוכנם של שלשת המזבחות שבנה אברהם — בבחינת \"מעשה אבות סימן לבנים\" — שבהם הניח אברהם את היסודות (\"סימן\") לשלשה ענינים כלליים בעבודת עם ישראל במשך כל הדורות:\nהמזבח הראשון הי' \"על בשורת הזרע ועל בשורת א\"י\", שזהו ענין של צרכי האדם, הן הגשמיים והן הרוחניים (בדוגמת \"מזין\"<sup data-n=\"352\">*51</sup>);\nהמזבח השני — שהתפלל שם עליהם (לכפר על מעשה עכן)<sup data-n=\"353\">52</sup> — היינו הענין ד\"מזיח<sup data-n=\"352\">*51</sup>. . מכפר\";\nואילו המזבח השלישי לא פרש\"י מהו ענינו — כי תכליתו של מזבח זה אינה בשביל איזו תועלת צדדית, כ\"א רק כדי לבנות מזבח לה' (כמו קרבן עולה שהיא כליל לה', ובאה רק לכבודו יתברך כנ\"ל). וה\"סימן לבנים\" שב\"מעשה אבות\" זה<sup data-n=\"355\">53</sup> הוא לענין ד\"מחבב\" שבקרבנות<sup data-n=\"356\">54</sup>, כי הקרבה באופן כזה פועלת חביבותם של ישראל אצל הקב\"ה, כנ\"ל.\nונמצא, ששלשת המזבחות שבנה אברהם הם בסדר דמן הקל אל הכבד: הראשון — \"על בשורת הזרע ועל בשורת א\"י\" (דוגמת \"מזין\"); השני — תפלתו על מעשה עכן (\"מזיח. . מכפר\"); והשלישי — \"ויבן שם מזבח לה'\" (סתם), מבלי שום כוונה נוספת, רק לכבודו יתברך.\n[ובזה יומתק זה שבהמזבח הראשון לא העתיק רש\"י את התיבות \"לה' הנראה אליו\" — דלכאורה, פשטות משמעות הכתוב היא, דלאחרי שנראה אליו ה' — \"וירא ה' אל אברם\" — בנה מזבח \"לה' הנראה אליו\", וא\"כ הו\"ל לרש\"י להעתיק הנ\"ל ולפרש שבניית המזבח היתה להודות על התגלות זו<sup data-n=\"357\">*54</sup> (או שהתגלות זו עוררה אצלו הרצון לעבוד ה' על ידי מזבח), ורש\"י מפרש שהמזבח בא (רק) \"על בשורת הזרע ועל בשורת א\"י\"?\nוע\"פ הנ\"ל מובן, כי סדר העבודה הוא בהדרגה (מלמטה למעלה), מן הקל אל הכבד, ותוכן זה שבמזבח (לבנות מזבח \"לה' הנראה אליו\") שייך למזבח השלישי<sup data-n=\"358\">55</sup>; ולכן פרש\"י דמש\"נ \"לה' הנראה אליו\" (גבי מזבח הא') לא בא לתאר תוכנו ומטרתו של המזבח, אלא רק כסימן (הזמן) לחוד — ש(בנייתו שהיא בגלל הבשורות —) הבשורות נודעו לו כאשר \"ה' נראה אליו\"<sup data-n=\"359\">56</sup>].\nז. ועפ\"ז יש לבאר גם זה שהכתוב מדגיש גם במזבח הג' \"ויבן שם מזבח לה'\", שבנה את המזבח בחברון דוקא, כי תוכן ענינו של מזבח זה שייך לעיר חברון דוקא.",[["352","*51","להעיר מהגירסא בש\"ס כת\"י מינכן (ראה מס' כתובות עם דקדוקי סופרים השלם — אה\"ק, תשל\"ב) \"מזין (ואח\"כ) ומזיח\"."],["353","52","להעיר ממלאכת הקודש על פרש\"י פרשתנו (יב, ח) דבפעולת אברהם בעי \"דהי' בשביל עון, הוצרך לשניהם, לתפלה, ולמזבח להקריב עליו קרבן לכפרת עון\"."],["352","*51","להעיר מהגירסא בש\"ס כת\"י מינכן (ראה מס' כתובות עם דקדוקי סופרים השלם — אה\"ק, תשל\"ב) \"מזין (ואח\"כ) ומזיח\"."],["355","53","משא\"כ המזבח שבפ' וירא — עקידת יצחק — שזה הי' מצד הציווי, ואין זה בגדר מעשה אבות שהם רק סימן לבנים, אלא שהוא כעין תחילת מעשה הבנים. שלכן: א) הי' מצד הציווי, ב) הי' במקום המקדש והמזבח בהר המורי'. וראה רמב\"ם הל' ביהב\"ח רפ\"ב."],["356","54","ולהעיר מרמב\"ם שבהערה 50, שממשיך שם: והיא מעלת אברהם אבינו כו'."],["357","*54","כפי' המפרשים הנ\"ל הערה 19."],["358","55","וכנ\"ל סוס\"ד דבחי' זו הג' שייכת לגילוי שכינה (שבקרבנות). וראה אברבנאל שם בפי' \"ויבן שם מזבח\" (הא')."],["359","56","וראה באר יצחק לפרש\"י שם, ז."]]],[1301410106,"וכידוע<sup data-n=\"360\">57</sup> ש\"חברון\" הוא לשון חיבור<sup data-n=\"361\">58</sup> [וכמשנ\"ת במק\"א<sup data-n=\"362\">59</sup> שזה שייך (גם) לעיר חברון כפשוטה, ששם נקברו האבות והאמהות של כל ישראל ואין קורין אבות (ואמהות) אלא לאלה<sup data-n=\"363\">60</sup>, וכל התפלות עולות על ידי חברון<sup data-n=\"364\">61</sup>], ואמיתית הקשר והחיבור של בנ\"י עם הקב\"ה הוא כאשר עבודתנו היא לא \"בעד עצמנו\", בשביל איזו תועלת המגיעה להאדם (גם לא תועלת נעלית ביותר של כפרת האדם), כ\"א כאשר ה\"מזבח\" (ההקרבה) שלו הוא רק לכבודו ית', כולו כליל לה'.\nח. ידוע שעיקרו של ביהמ\"ק — \"בית לה' מוכן להיות מקריבים בו הקרבנות\"<sup data-n=\"365\">62</sup> — הוא המזבח, וע\"פ הנ\"ל יש לומר, שג' מזבחות אלו דאברהם, הם כנגד ג' בתימקדשות<sup data-n=\"366\">63</sup>:\nנת' במ\"א בארוכה<sup data-n=\"367\">64</sup>, שההפרש בין מקדש ראשון ומקדש שני בעבודה רוחנית הוא בזה, שענינו של מקדש הראשון הוא עבודת הצדיקים, ועבודה דמקדש שני, שבא (לאחרי חורבן בית ראשון ו)לתיקונו של החורבן — היא עבודת התשובה.\nונמצא, שמזבח הראשון דאברהם — שכנגד העבודה דתומ\"צ — הוא ה\"סימן\" למקדש הראשון, עבודת הצדיקים (שנקראים כן על שם עבודתם בקיום התומ\"צ); ומזבח השני שלו — כנגד עבודת התשובה — הוא ה\"סימן\" להעבודה דמקדש שני<sup data-n=\"368\">65</sup>.\nאמנם תכלית השלימות היא בית המקדש השלישי — תכלית השלימות בעבודת השם, שאז יקויים היעוד \"עין בעין יראו וגו'\"<sup data-n=\"369\">66</sup>, היינו התגלות אלקות בתכלית השלימות<sup data-n=\"370\">67</sup>, ובמילא גם דביקות בנ\"י בה' תהי' בתכלית השלימות ובביטול מוחלט אליו ית'. וב\"מעשה אבות\" הוא המזבח השלישי שבנה אברהם בחברון, שכל ענינו הי' רק — \"ויבן שם מזבח לה'\", כנ\"ל באורך.\nויש למצוא סמוכין לזה בדברי המדרש<sup data-n=\"371\">68</sup>, שאברהם בנה מזבח בחברון מפני שהוא \"מקום שהמליכו בו את דוד ושם כרתו ברית שנאמר<sup data-n=\"372\">69</sup> ויבואו כל זקני ישראל אל המלך חברונה ויכרות להם המלך דוד ברית בחברון לפני ה'\":\nידוע שמלכותו של דוד המלך (ובפרט כאשר נעשה מלך בפועל על כל ישראל) היא מלכות נצחית<sup data-n=\"373\">70</sup>, אשר שלימותה היא מלכותו של המלך המשיח.",[["360","57","זח\"א קכב, ב (מהנ\"ע). קכה, א."],["361","58","להעיר שבדפוס ראשון ובא' מכת\"י רש\"י (שתח\"י) איתא בפרש\"י עה\"פ (יג, יח) ד\"ה אשר בחברון, \"שחבר את עצמו להב\"ה\"."],["362","59","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251098\" data-slug=\"likkutei-sichot\" data-id=\"1300251098\">לקו\"ש חכ\"ה ע' 98</a>."],["363","60","ברכות טז, ב."],["364","61","ילקוט ראובני ח\"ש כג, ט (ממגלה עמוקות). וראה בהנסמן בלקו\"ש חכ\"ה שם."],["365","62","רמב\"ם ריש הל' בית הבחירה."],["366","63","להעיר מרמב\"ן תולדות (כו, כ. וראה גם כלי יקר שם, יט) שג' הבארות שחפר יצחק הם לנגד ג' בתי מקדשות. ע\"ש. — נת' בארוכה לקמן ע' 116 ואילך."],["367","64","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091027\" data-slug=\"likkutei-sichot\" data-id=\"1300091027\">לקו\"ש ח\"ט ע' 27</a> ואילך. 67 ואילך."],["368","65","שאף שחסרו שם ה' דברים (ראה יומא שם), הרי נאמר (חגי ב, ט) \"גדול יהי' כבוד הבית הזה האחרון מן הראשון\", שקאי על בית שני (ב\"ב ג, סע\"א ואילך). וראה בארוכה לקו\"ש ח\"ט (שם) ענינו ברוחניות."],["369","66","ישעי' נב, ח."],["370","67","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["371","68","מדרש הגדול פרשתנו יג, יח."],["372","69","ש\"ב ה, ג."],["373","70","כמ\"ש הרמב\"ם הל' מלכים פ\"א ה\"ז ואילך. וראה ר\"ה (כה, א. זח\"א קצב, ריש ע\"ב. נוסח קידוש לבנה) \"דוד מלך ישראל חי וקיים\"."]]],[1301410107,"וכפסק דין הרמב\"ם<sup data-n=\"374\">71</sup> ש\"המלך המשיח עתיד לעמוד ולהחזיר מלכות דוד ליושנה לממשלה הראשונה\"; ולא עוד אלא שמצינו במדרשי חז\"ל<sup data-n=\"375\">72</sup>, שמלך המשיח הוא הוא דוד המלך — \"דוד שמי'\", ובלשון הידוע<sup data-n=\"376\">73</sup> \"איש צמח שמו הוא דוד בעצמו\"<sup data-n=\"377\">74</sup>.\nונמצא, שמזבח זה שבנה אברהם שייך למלכותו של דוד, שהיא היא מלכותו של מלך המשיח, שאז תהי' תכלית השלימות הנ\"ל בעבודת השם.\nט. ההוראה מכל זה במעשינו ועבודתינו עתה:\nמאחר שמעשה אבות הוא סימן לבנים, מובן, שענינם של כל שלשת המזבחות שבנה אברהם צ\"ל בעבודת כאו\"א מישראל, וגם עתה.\nוע\"פ משנ\"ת שהמזבח השלישי הוא כנגד השלימות שתושג בגאולה האמיתית והשלימה על ידי משיח צדקנו, נמצינו למדים, שכל עניני העבודה (כללות ענין המזבח והקרבנות בעבודת השם), גם בזמן הגלות, צריכים להיות קשורים בתוכן הענין דמלכות דוד, דוד מלכא משיחא.\nהיינו שגם העבודה דתומ\"צ ותשובה צ\"ל חדורה בההכרה הברורה, ששלימות ענין עבודת השם תהי' רק לעת\"ל<sup data-n=\"378\">75</sup> (שאז יהי' קיום המצות \"כמצות רצונך\"<sup data-n=\"379\">76</sup>), וכדברי הרמב\"ן הידועים<sup data-n=\"380\">77</sup> שהמצות שאנו מקיימים בזמן הזה (בחו\"ל) הן רק \"ציונים\", \"כי עיקר כל המצוות ליושבים בארץ ה'\" —\nשזה גופא מעורר עוד יותר התשוקה והגעגועים לגאולה האמיתית והשלימה, ועי\"ז מקרבים וממהרים את הזמן שבו רואים במוחש, בפועל ובגלוי, את קיומה של הכריתת ברית דכל בנ\"י עם דוד המלך, דוד מלכא משיחא — \"ועבדי דוד מלך עליהם ורועה אחד יהי' לכולם. . ודוד עבדי נשיא להם לעולם\"<sup data-n=\"381\">78</sup>, ובמהרה בימינו ממש.\n<span data-k=\"q\">(משיחת ז' מרחשון תשמ\"ו) </span>",[["374","71","שם רפי\"א."],["375","72","ירושלמי ברכות פ\"ב ה\"ד (ובפני משה שם)."],["376","73","\"סדר הושענות\" להושענא רבא (פיוט אומץ ישעך)."],["377","74","ולהעיר מסנהדרין (צח, סע\"ב): עתיד הקב\"ה להעמיד להם דוד אחר כו'. וראה לקו\"ש חל\"ה ע' 206 ואילך."],["378","75","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221077\" data-slug=\"likkutei-sichot\" data-id=\"1300221077\">לקו\"ש חכ\"ב ע' 77</a> ואילך."],["379","76","ראה תו\"ח ר\"פ ויחי. מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תרפו. וש\"נ. המשך וככה תרל\"ז פי\"ז ואילך."],["380","77","אחרי יח, כה (ע\"פ ספרי עקב יא, יז — הובא בפרש\"י שם, יח)."],["381","78","יחזקאל לז, כדכה."]]],[1301410108,"<h3>שיחה ב</h3>\nא. תנן במס' נדרים<sup data-n=\"382\">1</sup>: גדולה מילה שכל המצות שעשה אברהם אבינו לא נקרא שלם עד שמל שנאמר<sup data-n=\"383\">2</sup> התהלך לפני והי' תמים<sup data-n=\"384\">3</sup> (וכתיב בתרי'<sup data-n=\"385\">4</sup> ואתנה בריתי ביני ובינך. רש\"י<sup data-n=\"386\">5</sup>). ובגמ' שם<sup data-n=\"387\">6</sup>: תניא רבי אומר גדולה מילה שאין לך מי שנתעסק במצות כאברהם אבינו ולא נקרא תמים אלא על שם מילה שנאמר התהלך לפני והי' תמים וכתיב ואתנה בריתי ביני ובינך.\nוהנה לכאורה נראה ששני המאמרים (במשנה וברייתא) היינו הך<sup data-n=\"388\">7</sup>. אבל כד דייקת — כמה שינויים ביניהם:\nא) במשנה הלשון \"לא נקרא שלם עד שמל\", ובברייתא \"לא נקרא תמים אלא על שם מילה\". ולכאורה היינו הך, דהיינו שלם היינו תמים. [דדוחק לומר שכוונת הברייתא היא לתקן לשון המשנה \"שלא נקרא שלם\", להתאימו ללשון המקרא \"והי' תמים\"<sup data-n=\"389\">8</sup>].\nב) במשנה הלשון \"לא נקרא שלם עד שמל\", משא\"כ בברייתא \"לא נקרא תמים אלא על שם מילה\" — שזהו שינוי עיקרי בתוכן: לפי סגנון המשנה \"כל המצות שעשה אברהם אבינו\" שייכות ל\"שלימותו\" של אברהם, אלא שאין ביכולתן לבדן לפעול בו שיהי' שלם, \"עד שמל\", ש(רק) בצירוף מצות מילה נעשה \"שלם\"; משא\"כ בברייתא מפורש, ש\"לא נקרא תמים אלא על שם מילה\", שמצות מילה בלבד היא הפועלת שיהי' \"נקרא תמים\"<sup data-n=\"390\">9</sup>.\nב. והנה בכלל יש לומר, שבמשנה וברייתא מדובר אודות שני ענינים שונים שישנם במצות מילה.\nדהנה מבואר בכ\"מ שבמצות מילה יש ב' ענינים: א) שלא יהי' ערל, ב) שיהי' מהול<sup data-n=\"391\">10</sup> (ויש ביניהם כמה נפק\"מ לדינא גם למעשה, וכמבואר בארוכה בצפע\"נ להרגצובי<sup data-n=\"392\">11</sup>).\nולפ\"ז י\"ל, שבמשנה מדובר בעיקר במעלת ענין הא' שבמצות מילה (שלא",[["382","1","לא, ב."],["383","2","פרשתנו יז, א."],["384","3","וכן הוא הלשון בתוספתא שם פ\"ב, ו."],["385","4","יז, ב."],["386","5","ובכ\"י דהמשנה (ראה שינויי נוסחאות במשניות עה\"ג ודק\"ס השלם לנדרים שם) הובא זה בפירוש. וכ\"ה ברמב\"ם הל' מילה פ\"ג ה\"ח. סמ\"ג עשין כח. וראה תויו\"ט למשנה נדרים שם. ואכ\"מ."],["387","6","לב, א."],["388","7","לפנינו גם במשנה הוא מאמר רבי, כבברייתא שבגמ'. אבל להעיר, שלכמה גי' במשנה הוא מאמר ר' מאיר (כמצויין על גליון הש\"ס שלפנינו נדרים שם. וראה שינויי נוסחאות למשניות ודק\"ס השלם למס' נדרים). אבל לאידך, גם בברייתא יש כמה גי' שהוא מאמר ר' מאיר (ראה דק\"ס השלם שם)."],["389","8","ובפרט להגי' (ראה הערה הקודמת) שהוא אותו המ\"ד."],["390","9","ראה מלאכת שלמה למשניות נדרים שם (בסוף הפרק) בשם ספר חן טוב (מהר' טובי' הלוי) פרשתנו, שמדייק כמה חילוקים בין לשון המשנה והברייתא."],["391","10","וראה לקמן ס\"ט בנוגע ענין הג' שבמילה — עצם פעולת המילה."],["392","11","ראה צפע\"נ ריש הל' מילה (טז, א. שם, בג). הל' ברכות (טו, ג). הל' כלאים (יב, ב). ועוד. וראה לקו\"ש ח\"ג (ע' 759 ואילך, 761 ואילך)."]]],[1301410109,"יהי' ערל), ובברייתא מוסיף ע\"ד מעלת ענין הב' (שיהי' מהול):\nבמשנה מדייק ואומר \"גדולה מילה שכל המצות שעשה אברהם אבינו לא נקרא שלם עד שמל\" (ולא \"על שם המילה\") — כי הכוונה היא לענין הסרת הערלה שבמילה, ובא בהמשך לתחילת המשנה ששם מדובר בשלילת הערלה, \"קונם שאני נהנה לערלים מותר בערלי ישראל ואסור במולי עכו\"ם כו' שאין הערלה קרוי' אלא לשם עכו\"ם כו' ר\"א בן עזרי' אומר מאוסה היא הערלה כו'\" [וכן משמע ברמב\"ם, שבסוף הל' מילה<sup data-n=\"393\">12</sup> כ' \"מאוסה היא הערלה שנתגנו בה הגוים. . וגדולה היא המילה שלא נקרא אברהם אבינו שלם עד שמל שנאמר כו'\", הרי שכתב \"גדולה היא המילה\" דאברהם באותה ההלכה ובהמשך ל\"מאוסה היא הערלה\", ובוא\"ו החיבור<sup data-n=\"394\">13</sup>];\nאבל בברייתא מבאר מעלת המילה עצמה (שיהי' מהול), ולכן מדייק \"ולא נקרא תמים אלא על שם מילה\" (ולא \"עד שמל\").\nאבל עדיין צ\"ב איך מתבארים בזה שאר השינויים בין המשנה והברייתא.\nג. ויש לומר הביאור בזה:\nב\"תמים\" מצינו שני ענינים: (א) שלילת מום וחסרון, (ב) תמימות ושלימות נוספת, שלא רק שלא חסר בו שום דבר, אלא שהוא \"תמים\".\nע\"ד דין \"תמים\" בקרבנות, שמצינו בו שני ענינים אלה: שלילת חסרון<sup data-n=\"395\">14</sup> — שאין בו מום הפוסל<sup data-n=\"396\">15</sup>; אבל יש בכלל זה גם תמימות יתירה, כמ\"ש הרמב\"ם<sup data-n=\"397\">16</sup> \"מצות עשה להיות כל הקרבנות תמימין ומובחרין שנאמר<sup data-n=\"398\">17</sup> תמים יהי' לרצון זו מצות עשה\" [ועד\"ז כ'<sup data-n=\"399\">18</sup> לגבי נסכין ועצי המערכה \"כשם שמצוה להיות כל קרבן תמים ונבחר כך הנסכין יהיו תמימים ונבחרין שנאמר<sup data-n=\"400\">19</sup> תמימים יהיו לכם ונסכיהם כו' וכן עצי המערכה לא יהיו אלא נבחרין ולא כו'\"].\nהרי דאף ש\"מובחרין\" הוא דין בפ\"ע, כמו שהביא הרמב\"ם<sup data-n=\"401\">20</sup> שלמדין זה ממש\"נ<sup data-n=\"402\">21</sup> \"מבחר נדריך\", מ\"מ נכלל גם בלשון \"תמים יהי'\", ובהביאו קרבן מן המובחר מקיים לא רק דין מובחר שבקרבנות, אלא גם הא דתמים יהי'<sup data-n=\"403\">22</sup>, והוא — כי ב\"תמים\" יש שני פרטים, \"תמים\" בניגוד לבעל מום, והיינו שאין בו חסרון<sup data-n=\"404\">23</sup>, ותמים שיש בו תוספת שלימות ותמימות, אף שגם בלא\"ה הוא שלם<sup data-n=\"405\">24</sup>.",[["393","12","פ\"ג ה\"ח."],["394","13","וממשיך באותה ההלכה במאמר ממקום אחר (אבות פ\"ג מי\"א) \"וכל המפר בריתו של אברהם אבינו והניח ערלתו כו' אע\"פ שיש בו תורה ומע\"ט אין לו חלק לעוה\"ב\", וב' המאמרים האחרים שבמשנה נדרים שם (כמה חמורה מילה שלא נתלה למשה וכו', ועל המילה נכרתו י\"ג בריתות כו' — ל' הרמב\"ם) כתבם בהלכה בפ\"ע (הלכה שלאח\"ז). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251056\" data-slug=\"likkutei-sichot\" data-id=\"1300251056\">לקו\"ש חכ\"ה ע' 56</a> ואילך — בביאור דברי הרמב\"ם בב' הלכות אלו."],["395","14","וכפשטות הכתובים בפ' אמור כב, יט ואילך (וראה פרש\"י שם, יט)."],["396","15","להעיר מבכורות לט, א: תמים יהי' לרצון אמר רחמנא תמים אין חסרון לא. ע\"ש האיבעי בגמ'. וראה רמב\"ם הל' איסורי מזבח פ\"ב הי\"א."],["397","16","ריש הל' איסורי מזבח."],["398","17","אמור כב, כא."],["399","18","רפ\"ו שם."],["400","19","פינחס כח, לא."],["401","20","שם פ\"ב ה\"ח."],["402","21","פ' ראה יב, יא (כ\"ה ברמב\"ם \"נדריך\". ובכתוב \"נדריכם\")."],["403","22","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121130\" data-slug=\"likkutei-sichot\" data-id=\"1300121130\">לקו\"ש חי\"ב ע' 130</a> הערה 8. וש\"נ."],["404","23","וראה הנסמן לעיל הערה 15."],["405","24","להעיר משני אופני עבודה (יומא כד, א. וראה זבחים קטו, ב): עבודה שאינה תמה שיש אחרי' עבודה ועבודה תמה \"שהיא גומרת ומתממת את הדבר ולא שיש אחרי' עבודה כגון שחיטה וקבלה והולכה כו'\" (פרש\"י יומא שם ד\"ה עבודה תמה). ולהעיר גם משני האופנים בצדקה (כתובות סז, ב): די מחסורו אשר יחסר לו (אפילו סוס לרכוב עליו ועבד לרוץ לפניו), ולעשרו (שאינו דבר החסר)."]]],[1301410110,"וי\"ל, שזהו החילוק בין שתי הלשונות \"תמים\" ו\"שלם\", דאף שבכללות הם שמות נרדפים, בפרטיות יש חילוק ביניהם, ד\"שלם\" פירושו העדר החסרון<sup data-n=\"406\">25</sup>, ואילו \"תמים\" מורה על תמימות יתירה.\nוי\"ל שזהו ע\"ד שמצינו בנוגע ל\"שנה\": שנה רגילה היא שנה של י\"ב חודש, וכאשר חשון וכסלו מלאים קורין לה שנה \"שלימה\"<sup data-n=\"407\">26</sup>. אבל \"שנה תמימה\"<sup data-n=\"408\">27</sup> פירשו רז\"ל<sup data-n=\"409\">28</sup> \"להביא את חודש העיבור\". ונמצא, שאף שגם בלי חודש העיבור נקראת שנה<sup data-n=\"410\">29</sup> שלימה שלא חסר בה, מ\"מ<sup data-n=\"411\">30</sup>, ע\"י חודש העיבור נתוסף בה ענין התמימות<sup data-n=\"412\">31</sup>.\nד. וזוהי נקודת החילוק בין המשנה והברייתא במס' נדרים שם:\nבמשנה מדובר בגדר הא' שב\"תמים\" הנפעל על ידי המילה, ולכן מדייקת המשנה (ומשנה מלישנא דקרא) \"גדולה מילה כו' לא נקרא שלם עד שמל\", דהיינו שלם בלי מום וחסרון;\nובברייתא מוסיף על המשנה — \"גדולה מילה כו' ולא נקרא תמים אלא על שם מילה\", שמלבד זאת שמצות מילה פעלה שאברהם אבינו יהי' \"שלם\" (בלי מום), הנה עוד זאת, שפעלה בו שיהי' \"תמים\", שלימות נוספת (ע\"ד חודש העיבור).\nומדוייק השינוי בלשון המשנה והברייתא — במשנה \"לא נקרא שלם עד שמל\", ואילו בברייתא \"לא נקרא תמים אלא על שם מילה\" — כי גדר \"שלם\" (בלי חסרון) לא נפעל על ידי מצות מילה לחוד, אלא בצירוף \"כל המצות שעשה אברהם אבינו\", שעל ידי כולם יחד נעשה שלם, וזהו מ\"ש במשנה ש\"עד שמל\" עדיין לא נקרא שלם [כי מלבד זאת שהי' חסר אצלו קיום מצוה אחת — מצות מילה<sup data-n=\"413\">32</sup>, הרי כל זמן שהאדם ערל, ה\"ה חסר (ובעל מום) בעצם]; משא\"כ בברייתא שמדובר בגדר \"תמים\", שהוא תמימות ושלימות נוספת — ומעלה זו לא באה לו \"אלא על שם מילה\", שמצוה זו היא שהביאה תמימות ושלימות חדשה בכל עניני אברהם.\nוכמו\"כ מובן השינוי בתחילת לשון המאמר — במשנה \"שכל המצות שעשה אברהם אבינו\", ובברייתא \"אין לך מי שנתעסק במצות כאברהם אבינו\":\nבמשנה שמדובר בגדר ד\"שלם\" (לא בעל מום) הנפעל על ידי מצות מילה,",[["406","25","להעיר מפרש\"י וישלח (לג, יח): \"שלם, שלם בגופו שנתרפא מצלעתו שלם בממונו שלא חסר כלום. . שלם בתורתו שלא שכח תלמודו\"."],["407","26","טור או\"ח ר\"ס תכח."],["408","27","בהר כה, ל."],["409","28","ערכין לא, א (במשנה)."],["410","29","ראה ר\"ן נדרים סג, א (בשם הרשב\"א). שו\"ת נוב\"י מהד\"ק אה\"ע ס\"כ."],["411","30","ולהעיר מפרש\"י נח ח, יד: אלו יא ימים שהחמה יתירה על הלבנה שמשפט דור המבול שנה תמימה הי'. וראה דעת רבי במשנה ערכין שם ובפרש\"י."],["412","31","וראה אוה\"ת לתהלים (יהל אור) יט, ח (ס\"ד. ס\"ז) — ב' ענינים אלו בספירת העומר (שנאמר בה (אמור כג, טו) \"שבע שבתות תמימות תהיינה\") ובכמה ענינים. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121097\" data-slug=\"likkutei-sichot\" data-id=\"1300121097\">לקו\"ש חי\"ב ע' 97</a> ובהערה 12 שם."],["413","32","שזה לחוד אינו מספיק, ד\"דלמא אילו הי' חסר מצוה אחרת לא הי' ג\"כ תמים אלא ע\"י אותה המצוה\" — תויו\"ט נדרים שם. וראה הרי\"ף לע\"י שם. שו\"ת כתב סופר יו\"ד סקי\"ט. ועוד."]]],[1301410111,"מודגש ענין השלימות שהיתה אצל אברהם אבינו גם לפני קיום מצות מילה, ש\"כל המצות שעשה אברהם אבינו\" (דהיינו כל התורה כולה, שקיים אברהם אבינו עד שלא ניתנה<sup data-n=\"414\">33</sup>) לא הי' בכחם לפעול אצל אברהם שיהי' \"שלם\", \"עד שמל\";\nמשא\"כ בברייתא, שהכוונה להגדר ד\"תמים\", שזוהי שלימות ותמימות נוספת (יותר משלימות במובן דהעדר החסרון) — צריך להדגיש, שאף שגם לפני קיום מצות מילה הי' אצל אברהם (לא רק קיום כל המצות, אלא גם) קיום מצות באופן של הידור (תמימות ושלימות נוספת)<sup data-n=\"415\">34</sup> — \"אין לך מי שנתעסק במצות כאברהם אבינו\", באופן של עסק וטירחא יתירה, עד למסירת נפש — מ\"מ, \"לא נקרא תמים אלא על שם מילה\", כי א\"א להגיע למעלה ד\"תמים\" אלא על ידי ה\"מילה\", כשהאדם הוא \"מהול\".\nועפ\"ז יש לבאר גם הקשר לשני הענינים שבמילה — שלא יהי' ערל, ושיהי' מהול — כמודגש בשינוי ל' המשנה והברייתא, \"עד שמל\" או \"על שם מילה\":\nהענין ד\"לא יהי' ערל\" שבמצות מילה, פועל שהאדם יהי' שלם בלי מום, כי הערלה ה\"ה מום<sup data-n=\"416\">35</sup>, והסרת הערלה מבטלת חסרון זה ונעשה \"שלם\"<sup data-n=\"417\">36</sup> (זה גופא מתירו לאכול בתרומה כמבואר ברמב\"ם<sup data-n=\"418\">37</sup>); וזהו מ\"ש במשנה \"לא נקרא שלם עד שמל\", שהכוונה להסרת הערלה, שעי\"ז \"נקרא שלם\";\nאבל זה שהאדם נעשה בגדר \"מהול\", אין זה רק ענין שלילי, שאין לו ערלה, אלא זוהי שלימות ומעלה נוספת, שמלבד זאת שאין לו ערלה (מום) — יש ענין חיובי שהוא מהול. וזהו מה שמוסיף בברייתא, שענינה ופעולתה של מילה הוא לא רק שפועלת שלימות אצל אדם החסר — אלא שמוסיפה תמימות גם באדם השלם, \"לא נקרא תמים אלא על שם מילה\", כי הענין ד\"תמים\" (לא רק \"שלם\") נפעל על ידי הענין החיובי שבחפצא דמילה<sup data-n=\"419\">38</sup>, זה שהאדם \"מהול\"<sup data-n=\"420\">39</sup>.",[["414","33","יומא כח, ב. קידושין בסופה."],["415","34","עפ\"ז יומתק הלשון \"אין לך מי שנתעסק\", היינו שלא מצינו זה אצל שאר בנ\"א השלימים בעבודתם [משא\"כ במשנה ההשוואה היא לגבי שאר המצות שלו, \"כל המצות שעשה\"]. ולהעיר מהגי' בע\"י שם, כללי המילה לר\"י הגוזר (ע' 7) ועוד (ראה דק\"ס שם): שאין לך צדיק גמור בעולם כאברהם כו'."],["416","35","כלשון רש\"י פרשתנו עה\"פ \"אתה בעל מום\". וראה ב\"ר פמ\"ו, א (בסופו) ושם, ד (לגבי \"התהלך לפני והי' תמים\" דאברהם) \".. הערלה (הזאת) העבר אותה ובטל המום\". ובכללי המילה שם (ע' 8): מלמד שהערלה מום לו לאדם יותר מכל המומין עד שיעבירנה כו'. וראה תוי\"ט נדרים שם. ועוד."],["417","36","ראה במדב\"ר (פי\"ב, ח) בפי' \"צאינה וראינה גו' במלך שלמה, במלך שהוא חפץ בשלמים כמה דתימא התהלך לפני והי' תמים שהערלה מום הוא בגוף\"."],["418","37","הל' תרומות פ\"ז ה\"י (מיבמות עב, א)."],["419","38","ואולי י\"ל שזהו גם הפירוש במאמר ר\"י אמר רב בהמשך הגמ' שם \"בשעה שאמר לו הקב\"ה לאברהם אבינו התהלך לפני והי' תמים אחזתו רעדה אמר שמא יש בי דבר מגונה כיון שאמר לו ואתנה בריתי ביני ובינך נתקררה דעתו\" — שהקב\"ה אמר לו שעיקר ענין המילה אצלו הוא (לא בשביל הסרת הערלה, \"דבר מגונה\", אלא) ענין השלימות והתמימות, שיתוסף בו \"שיהי' מהול\". וראה עיון יעקב לע\"י שם. ועוד."],["420","39","וי\"ל שזהו בהתאם להטעמים השונים שבמילה (ראה בארוכה מטה משה חלק שביעי עניני מילה): א) למעט תאות כו' ולהחליש זה האבר כו' (מו\"נ ח\"ג פמ\"ט), והיינו הסרת כל המדות הפחותות אשר בכל הגוף כו' — מתאים לענין הא', שלם מבלי חסרון — שלא יהי' ערל; ב) למאמיני יחוד השם אות אחת כו' (מו\"נ שם), שנעשה אות קבוע בבשר על אמונת היחוד לא ישונה ולא יסור לעולם כו' (רבינו בחיי בכד הקמח), ועוד — מתאים לענין הב', תמימות ושלימות יתירה — שיהי' מהול."]]],[1301410112,"ה. והנה מצינו בסוגיא דנדרים שם<sup data-n=\"387\">6</sup> עוד פירוש ב\"והי' תמים\" — \"כל המתמים עצמו הקב\"ה מתמים [מתמם<sup data-n=\"422\">40</sup>] עמו כו' כל המתמים עצמו שעה עומדת לו שנא' התהלך לפני והי' תמים וכתיב והיית לאב המון גוים\".\nולפירוש זה, \"תמים\" אינו ענין השלימות, כ\"א הליכה בתמימות<sup data-n=\"423\">41</sup>, והוא ע\"ד הציווי<sup data-n=\"424\">42</sup> \"תמים תהי' עם ה' אלקיך\"<sup data-n=\"425\">43</sup> וכפרש\"י<sup data-n=\"426\">44</sup> \"התהלך עמו בתמימות ותצפה לו ולא תחקור אחר העתידות אלא כל מה שיבוא עליך קבל בתמימות כו'\"<sup data-n=\"427\">45</sup>. והיינו שאינו מתנהג בתחבולות ובהתחכמות, ויתירה מזו שאינו שואל ואינו חוקר אלא מאמין בפשיטות בדברי ה' ומתנהג בתמימות בהתאם לזה.\nומזה שגם פירוש זה הובא בסוגיא דנדרים ע\"ד מצות מילה, משמע, שגם ענין זה אצל אברהם, שהלך בתמימות, שייך למצות מילה.\nבפשטות י\"ל ע\"פ פירוש הראב\"ע<sup data-n=\"428\">46</sup> (ועוד מפרשים<sup data-n=\"429\">47</sup>), ד\"התהלך לפני והי' תמים\" היינו \"שלא תשאל למה המילה\", \"שיקבל<sup data-n=\"430\">*47</sup> בסתם אי זה דבר שיצוהו, עם שהי' קשה, ושיקבלהו בתמימות לא ישאל מה זה ועל מה זה\". אבל יותר מסתבר, שיש גם שייכות לתוכן מצות מילה, שדוקא היא היא המצוה שפעלה אצל אברהם ענין ההליכה בתמימות.\nזאת ועוד: נת' כמ\"פ<sup data-n=\"431\">48</sup> שכל הפירושים בפסוק אחד (או תיבה אחת) שייכים זל\"ז. וכן בנדו\"ד, שגם הפירוש הג' ב\"הי' תמים\", הליכה בתמימות, שייך לענין ד\"שלם\" ו\"תמים\".\nועפ\"ז יש ג' אופנים במעלת ה\"תמימות\" שבמצות מילה: א) ביטול כל החסרונות. ב) שלימות ותמימות בהידור. ג) קבלת עול מלכות שמים שלמעלה מטעם ודעת.\nו. ויובן זה ע\"פ תוספת ביאור בג' ענינים הנ\"ל ב\"תמים\" — \"שלם\", \"תמים\", והליכה בתמימות. ובהקדם, שג' דרגות אלו בעבודת ה' י\"ל שהם כנגד העבודות דאברהם יצחק ויעקב (אף שבכלל כל ג' ענינים הנ\"ל היו אצל כאו\"א מהאבות):\nמעלת התמימות מצינו בכל ג' האבות<sup data-n=\"432\">49</sup>, באברהם — \"התהלך לפני והי' תמים\", יצחק נקרא \"עולה תמימה\"<sup data-n=\"433\">50</sup>, וביעקב נאמר<sup data-n=\"434\">51</sup> \"ויעקב איש תם יושב אהלים\".\nובפשטות, הם הם שלשת הענינים הנ\"ל ד\"שלם\" \"תמים\" והליכה בתמימות:\nהפירוש הפשוט ד\"הי' תמים\" אצל אברהם אבינו היינו שיהי' שלם (בלי",[["387","6","לב, א."],["422","40","כ\"ה בע\"י ועוד — ראה דק\"ס שם."],["423","41","ראה גם חדא\"ג מהרש\"א שם."],["424","42","שופטים יח, יג."],["425","43","וראה רמב\"ן עה\"ת פרשתנו, ובפ' שופטים שם. השגות הרמב\"ן לסהמ\"צ בסוף חלק המ\"ע ששכח הרמב\"ם מצוה ח [אלא שפירושו הוא לא כפי' רש\"י וכו' דלקמן בפנים]."],["426","44","שופטים שם. וראה פסחים קיג, ב וברשב\"ם. חדא\"ג נדרים שם."],["427","45","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141077\" data-slug=\"likkutei-sichot\" data-id=\"1300141077\">לקו\"ש חי\"ד ע' 65</a> ואילך."],["428","46","פרשתנו עה\"פ."],["429","47","פירוש הר\"ן עה\"ת, הובא באברבנאל כאן (בשינויים קלים): תולדות יצחק (לזקנו של הב\"י) כאן. ועוד."],["430","*47","ל' הר\"ן שם."],["431","48","לקו\"ש ח\"ג ע' 782 (ע\"ש הראי' מהדין דשעטנז). ובכ\"מ."],["432","49","בחיי פרשתנו עה\"פ. ושם: והוא השבח הגדול האמור בכל הצדיקים כו'."],["433","50","ב\"ר פס\"ד, ג. פרש\"י תולדות כה, כו. כו, ב."],["434","51","תולדות כה, כז."]]],[1301410113,"חסרון ומום), וככל ג' הפירושים שבפרש\"י עה\"פ<sup data-n=\"435\">52</sup> \"הי' שלם בכל נסיונותי ולפי מדרשו. . ובדבר הזה תהי' תמים שכל זמן שהערלה בך אתה בעל מום לפני<sup data-n=\"436\">53</sup> ד\"א כו' עכשיו אתה חסר ה' אברים כו'\";\nהלשון \"עולה תמימה\" מורה (לא רק על העדר החסרון, אלא) על שלימות ותמימות נוספת. שהרי \"עולה\" גופא כבר מורה שכולה לגבוה, הקרבה שלימה (כלומר: קרבן בכלל ה\"ה תמים ולא בעל מום; נוסף על זה \"עולה\" — שהיא עולה כליל לה', הקרבה שלימה), והתואר \"(עולה) תמימה\" מוסיף תמימות גם בזה, הוספת שלימות בעולה שכולה לגבוה בלא\"ה;\nו\"יעקב איש תם\" פירושו — הליכה בתמימות, וכפרש\"י<sup data-n=\"434\">51</sup> \"כלבו כן פיו, מי שאינו חריף לרמות קרוי תם\".\nז. ביאור השייכות של ג' הענינים ד\"שלם\" \"תמים\" והליכה בתמימות — לאברהם יצחק ויעקב:\nאברהם הי' בנו של תרח, \"ולא הי' לו מלמד ולא מודיע דבר אלא מושקע באור כשדים בין עכו\"ם הטפשים ואביו ואמו וכל העם עובדי כוכבים והוא עובד עמהם ולבו משוטט ומבין עד שהשיג דרך האמת כו' מתבונתו הנכונה. . וידע שכל העולם טועים. . ובן ארבעים שנה הכיר אברהם את בוראו\" (כמבואר ברמב\"ם<sup data-n=\"438\">54</sup>), שמזה מובן, שעיקר עבודת אברהם היתה לשלול ענין החסרון (שמצד תרח אביו והעולם סביבו כו')<sup data-n=\"439\">55</sup>, ובזה עלה מחיל אל חיל בעבודת השם עד שהגיע לדרגת השלימות בעבודתו ית', וכדאיתא בזהר עה\"פ<sup data-n=\"440\">56</sup> ואברהם זקן בא בימים, שאצל אברהם היו יומין שלימין, שלא הי' חסר לבושא חדא ויומא חדא כו'.\nאבל יצחק נולד מטיפה קדושה<sup data-n=\"441\">57</sup>, שתיכף בלידתו כבר הי' קדוש מבטן<sup data-n=\"442\">*57</sup> (והי' הראשון שנולד יהודי)<sup data-n=\"443\">58</sup>, ועבודתו היתה — ענין התמימות, היינו הוספה בשלימות הקדושה והיהדות שהיתה בו.\n[ולהעיר, שגם בענין המילה, הרי דוקא יצחק נימול לשמונה<sup data-n=\"444\">59</sup>, היינו קיום מצות מילה בשלימותה (כפי שהיא אחר מ\"ת), משא\"כ באברהם שנימול לצ\"ט].\nאלא שעדיין אין זו תכלית השלימות, כי יצחק לא יצא מחוץ לגבול הקדושה, כציווי ה' \"אל תרד מצרימה שכון בארץ גו'\"<sup data-n=\"445\">60</sup>; וזהו חידושו של יעקב, שאצלו נאמר<sup data-n=\"446\">61</sup> \"ויצא יעקב מבאר שבע וילך חרנה\", חרון אף של מקום<sup data-n=\"447\">62</sup> בעולם,",[["435","52","וראה גם פי' ר\"י בכור שור וחזקוני פרשתנו עה\"פ. ועוד."],["436","53","ואולי יש לפרש, שבפרטיות זהו החילוק בין ב' הפירושים ברש\"י: \"והי' תמים — הי' שלם בכל נסיונותי\", הכוונה לגדר השלימות, ו\"לפי מדרשו התהלך לפני במצות מילה ובדבר הזה תהי' תמים\" היינו ענין התמימות (ומה שממשיך \"שכל זמן שהערלה בך אתה בעל מום לפני\", י\"ל שההדגשה היא ב\"לפני\" ולא מצ\"ע — ראה משכיל לדוד לפרש\"י. ואכ\"מ). וראה משכיל לדוד שם, שגם פי' הג' ברש\"י בא בהמשך לזה."],["434","51","תולדות כה, כז."],["438","54","הל' ע\"ז פ\"א ה\"ג."],["439","55","עיי\"ש ברמב\"ם בארוכה פעולת אברהם בעולם."],["440","56","ח\"ש כד, א. זח\"א רכד, א."],["441","57","ב\"ר פמ\"ו, ב."],["442","*57","פרש\"י פרשתנו יז, יט."],["443","58","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011027\" data-slug=\"likkutei-sichot\" data-id=\"1300011027\">לקו\"ש ח\"א ע' 27</a> ואילך."],["444","59","ראה ב\"ר פנ\"ה, ד. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251086\" data-slug=\"likkutei-sichot\" data-id=\"1300251086\">לקו\"ש חכ\"ה ע' 86</a> ואילך. וש\"נ."],["445","60","תולדות כו, ב."],["446","61","ר\"פ ויצא."],["447","62","פרש\"י ס\"פ נח."]]],[1301410114,"וכפשוטו שהוצרך לברוח מעשו, ולהיות בבית לבן הארמי כ' שנה ואח\"כ עברה עליו \"צרת יוסף וכו'\", ובכל מצבים אלו נשאר תמים בעבודתו, \"עם לבן הרשע גרתי כו' ולא למדתי ממעשיו הרעים\"<sup data-n=\"448\">63</sup>, וכמבואר בארוכה במדרשי רז\"ל.\nוענין זה הוא מצד הענין הג' בתמימות, ש\"איש<sup data-n=\"449\">64</sup> תם וישר. . הוא סור מרע ועשה טוב בפועל ממש בבחי' התמימות שלא ישונה לעולם, ואינו נוגע לו הזמן והמקום שמפני תוקף הדבר והתמימות שבנפשו שכך צריך לעשות ואינו שייך כלל באופן אחר ע\"כ בכל זמן ובכל מקום שהוא ה\"ה עושה כן בלי שום שינוי כלל, ולא יחוש משום מנגד ומסית להדיחו ח\"ו מצד עוצם התוקף בנפשו כו'<sup data-n=\"450\">*64</sup>, עד שגם אינו נחשב אצלו לנסיון כלל מאחר שאופן אחר ח\"ו אינו שייך כלל\"<sup data-n=\"451\">65</sup>.\nוזהו ענינו של יעקב \"איש תם\"<sup data-n=\"452\">66</sup>, מדת האמת<sup data-n=\"453\">67</sup>, בריח התיכון שמבריח מן הקצה אל הקצה<sup data-n=\"454\">68</sup>, שבכל הפרטים והמצבים הוא בשווה ממש, ואינו מתפעל משום מנגד<sup data-n=\"455\">69</sup>.\nח. וזהו גם הקשר בין ענין ההליכה בתמימות (\"תם\") לענין ד\"שלם\" ו\"תמים\" — כי ההליכה בתמימות אינה ענין שונה, אלא הוא דרגא עליונה יותר ב\"שלימות\", שהוא שלם בכל זמן ובכל מקום ובכל המצבים [וכדאיתא בזהר<sup data-n=\"456\">70</sup> שיעקב \"הוה שלים מכולהו וע\"ד כתיב בי' ויעקב איש תם שלים מכלא, אברהם תמים אקרי ולא הוה כ\"כ שלים אבל תם שלים מכולא\"].\nוהביאור בזה:\nגדר השלימות ד\"שלם\" נוצר ע\"י הפרטים השונים שיש בו, שבצירוף כולם",[["448","63","וישלח לב, ה ובפרש\"י שם."],["449","64","ל' אדמו\"ר (מהורש\"ב) נ\"ע בהמשך תער\"ב ח\"א פפ\"ב (ס\"ע קנו). וראה גם ד\"ח ז, ב ואילך. סה\"מ תש\"ג (ע' 58, 68 ואילך). וראה במעלת תמים על צדיק וכו' בתורת שלום ע' קעח ואילך. ועוד."],["450","*64","במאמרים שם נאמר ענין הנ\"ל בתמימות לגבי תמימות במעשה, ולפני זה מבואר שישנו ענין התמימות בכל הציור קומה, תמים בשכל, תמימות בלב שהוא בלי התפעלות שתוכו כברו ולבבו שלם בדבר ולא ישונה לעולם [וע\"ש בסה\"מ תש\"ג (ע' 58) כשהתמימות היא בלב נק' תמים סתם, כמ\"ש באברהם התהלך לפני והי' תמים ופרש\"י הי' שלם בנסיונותי שלא יהרהר אחרי מדותיו, וזהו התמימות בלב שאינו מהרהר כלל והוא תמים בהדבר]. ע\"ש. אבל מהמבואר בהמשך הענין (בתער\"ב וד\"ח) שם ד\"נעוץ תחלתן בסופן כי המעשה הוא סוף ושרשו בראש ותחלת הכל שהוא נקודת הרצון שזהו עיקר האמת דמדת התמימות שהוא בסוף המעשה בפו\"מ בתמימות העשי'\", מובן, שהמעלה ד\"תמים במעשיו\" היא גם לגבי התמימות בכל הציור קומה, תמימות בשכל ותמימות בלב."],["451","65","ובסה\"מ תש\"ג ע' 70, ש\"התמים עם ה' ותורתו אינו צריך לתת שום מקום למנגד לתומ\"צ לא רק שלא לענות לו על דבריו. . אלא גם שלא לשמוע את דבריו כי בזה גופא הרי נותנים לו איזה מקום וכמו שאנו רואים במוחש בטבע החצוף שכאשר אין עונים לו. . ה\"ה משתתק וכשעונים לו הנה החשיבות שנותנים מקום לדבריו. . זה עצמו נותן לו כח לחצוף יותר\"."],["452","66","להעיר דיעקב איש תם שייך למילה, כמ\"ש באדר\"נ (פ\"ב, ה) דלמדין מזה ד\"יעקב יצא מהול\". וראה לקמן הערה 78 — השייכות ליעקב דוקא."],["453","67","זח\"א קלט, סע\"א. קסא, א. תניא רפי\"ג. ועוד — ראה בהנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251255\" data-slug=\"likkutei-sichot\" data-id=\"1300251255\">לקו\"ש חכ\"ה ע' 255</a>."],["454","68","תרומה כו, כח. זח\"א א, ב. תניא שם. ועוד."],["455","69","וי\"ל שלכן דוקא יעקב מטתו שלימה<sup data-n=\"e8\">*</sup> (ויק\"ר פל\"ו, ה. זח\"ב רעו, רע\"א. רש\"י ויחי מז, לא. ועוד). וראה בארוכה בכהנ\"ל ספר הליקוטים דא\"ח צ\"צ ערך יעקב בתחלתו. לקו\"ש שם (וש\"נ). ועוד."],["456","70","ח\"ג קסה, סע\"ב."],["e8","*","וראה ספרי האזינו (לב, ט) דזה שיעקב מטתו שלימה נלמד מהכתוב ויעקב איש תם."]]],[1301410115,"יחדיו נעשה ענין שלם; וגדר \"תמים\" אינו נפעל מצד הצטרפות הפרטים יחד, אלא מצד ענין חדש שמוסיף על שלימות הדבר מצ\"ע, שדבר חדש זה פועל בו שיהי' \"תמים\". וכמו לדוגמא בזמן, ששנת הלבנה יש בה י\"ב חדשי הלבנה, שנה שלמה. ושנה תמימה נעשית ע\"י הוספת חודש העיבור. ואף שכל השנה נקראת שנה תמימה, שנעשה מציאות אחת (לא שנה וחודש י\"ג), מ\"מ, הרי מציאות אחת זו נוצרה על ידי חודש הי\"ג.\nוכן הוא באדם, דאף שהחילוק בין אדם השלם שאין בו חסרון לאדם סתם הוא לא רק בזה שאדם השלם יש בו יותר מעלות פרטיות (וכן אדם תמים יש בו תוספת מעלות גם לגבי אדם השלם), אלא שהאדם נעשה מציאות של \"אדם השלם\" (ויתירה מזו בשייכות לתמים, שהאדם נקרא תמים) — מ\"מ, גדר דאדם השלם הוא שכל כחות נפשו וכל פרטי עבודתו הם כדבעי, היינו צירוף כל הפרטים שבו; ו\"תמים\" הוא הוספת מעלה מסויימת שהיא היא הפועלת ויוצרת שם \"תמים\".\nמשא\"כ הענין הג' שב\"תמימות\" הרי הוא למעלה ממעלות פרטיות, כי זה שהוא תמים בעבודתו, ואינו מתפעל ואינו משתנה, הוא לא מצד מעלות ושלימות הפרטים שיש לו, או מצד הוספת מעלה יתירה, אלא, מצד הפשטות שלו שאינה שייכת לפרטים ומעלות מסויימות, ולכן ענין התמימות מתבטא בביטול והנחת עצמותו (הכולל ביטול פרטי מעלותיו), שזהו עצם נקודת הרצון שיש בכל יהודי (כמ\"ש הרמב\"ם<sup data-n=\"457\">71</sup>) שאינו משתנה לעולם<sup data-n=\"458\">72</sup>.\nולכן בכל המצבים ובכל הזמנים ובכל המקומות הוא בשלימות ובתמימות.\nט. ע\"פ כל הנ\"ל יש לבאר גם השייכות בין מצות מילה לענין ההליכה בתמימות (וכנ\"ל סעיף ה, שגם פירוש הג' ב\"והי' תמים\" — הליכה בתמימות — נפעל על ידי מצות מילה) — דיש לומר, שזה שייך לענין הג' שבמצות מילה, שהוא עצם פעולת המילה (והנפק\"מ להלכה, שגם מי שנולד מהול צריך הטפת דם ברית<sup data-n=\"459\">73</sup>, עצם פעולת המילה<sup data-n=\"460\">74</sup>).\nוהיינו משום שעצם פעולת המילה",[["457","71","הל' גירושין ספ\"ב."],["458","72","המשך תער\"ב וסה\"מ שבהערה 64."],["459","73","שו\"ע יו\"ד סרס\"ג ס\"ד. וראה לקמן הערה 78."],["460","74","ראה רש\"י (שבת קלד, סע\"א) \"והטפת דם ברית מצוה\". כללי המילה לר\"ג (בר\"י) הגוזר (ע' 120). ובצפע\"נ הל' מילה (פ\"א ה\"ז) כ' דהרמב\"ם \"ס\"ל גבי קטן שנולד כשהוא מהול, הטפת דם ברית הוא רק משום גדר מצוה ולא<sup data-n=\"e9\">*</sup> משום ספק ערלה כבושה (שבת קלה, א), כדמוכח ממ\"ש רבינו ז\"ל בהל' תרומות פ\"ז הי\"א דמותר לאכול בתרומה אם נולד מהול. . וכדמוכח בירוש' בשבת וביבמות דיש על זה פסוק בפ\"ע. . ונ\"ל דכן ס\"ל התוס' שבת דכ\"ה ע\"ב\" (ע\"ש בצפע\"נ. וכ\"כ בשו\"ת משכנות יעקב יו\"ד סי' סג בדעת הרמב\"ם).\n— בענין חיוב הטפת דם ברית ראה שו\"ע אדה\"ז או\"ח סשל\"א ס\"ו. שו\"ת צ\"צ יו\"ד סר\"ב ס\"ו. וראה אנציקלופדי' תלמודית ערך הטפת דם ברית. וש\"נ. ואכ\"מ."],["e9","*","וי\"ל שמפורש הוא בדב\"ר רפ\"ו: כך שנו חכמים תינוק שנולד מהול צריך להטיף ממנו דם ברית מפני בריתו של אברהם אבינו ומנין אתה למד מן התורה שנאמר המול ימול כו'. דלכאורה מהי ההוספה \"מפני בריתו של א\"א\", הרי כל מצות מילה היא להכניסו בבריתו של א\"א שנצטווה על המילה. וי\"ל שזה קמ\"ל בהוספה זו, שהוא גדר מצוה, ולא משום ספק ערלה כבושה. וראה מפרשי המדרש שם. שו\"ת כתב סופר שבהערה 32 קרוב לסופו. ולהעיר מרד\"ק פרשתנו עה\"פ."]]],[1301410116,"(ואולי י\"ל שזהו קשור עם צערא דינוקא), דורשת שיהי' אצל האב (המל את בנו) תמימות — ביטול והנחת עצמו<sup data-n=\"461\">75</sup>.\nוליתר ביאור — וע\"פ ביאור הפנימי בתוכנם הרוחני של ג' ענינים הנ\"ל שבמצות מילה:\nהתוכן הרוחני ד\"לא יהי' ערל\" הוא — להשתחרר משליטת היצה\"ר בתאוות הגוף והיצר<sup data-n=\"462\">76</sup>, שעי\"ז ה\"ה בגדר \"שלם\";\nהתוכן הרוחני ד\"מהול\" הוא, שגם אדם שהוא סר מרע ואינו תחת שליטת היצר, מוסיף תמיד בעבודתו בעלייתו בקודש, ומגלה את הטוב שנמצא בו<sup data-n=\"463\">77</sup>, שעי\"ז נעשה \"תמים\", שלא רק שאין בו חסרון אלא יש בו הוספת מעלה ושלימות (גם לגבי מי שהוא שלם מבלי חסרון בלא\"ה).\nאבל שני ענינים אלו, העבודה שלא יהי' ערל ושיהי' מהול, ענינם עבודה שיש בהם טעם ומעלה — \"שלא יהי' ערל\" היינו שיהי' אדם השלם מבלי חסרון, ו\"שיהי' מהול\" היינו שיהי' אדם בשלימות ותמימות יתירה, ולכן אין צורך (כ\"כ) לענין התמימות והביטול בעבודה זו.\nמשא\"כ עצם פעולת המילה, שהיא מעשה ועבודה כזו שלא נרגש בה מעלה ושלימות, כ\"א רק עצם מעשה המצוה מצד ציווי ה', זה בא מצד התמימות והביטול שבנפשו, שמבטל ומניח את עצמו, וכן שכלו ומדותיו, לקיים רצון ה' למעלה מטעם ודעת<sup data-n=\"464\">78</sup>.\nועל ידי עבודה זו פועלים ש\"כל המתמים עצמו הקב\"ה מתמים עמו כו' כל המתמים עצמו שעה עומדת לו שנאמר התהלך לפני והי' תמים וכתיב והיית לאב המון גוים\", עד ל\"והיו<sup data-n=\"465\">79</sup> מלכים אומניך ושרותיהם מניקותיך\", שיהי' בתכלית השלימות בביאת משיח צדקנו, בקרוב ממש, בשנה תמימה זו<sup data-n=\"466\">80</sup>.\n<span data-k=\"q\">(משיחות ש\"פ לך תשמ\"א, ליל ב' וג' דחג הסוכות תשמ\"ט) </span>",[["461","75","להעיר ממשנ\"ת במ\"א (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101044\" data-slug=\"likkutei-sichot\" data-id=\"1300101044\">לקו\"ש ח\"י ע' 44</a> ואילך) בנוסח ברכת להכניסו בבריתו של א\"א, שמצד הצער וכו' שבמילה כל אחד הוא בדוגמת אברהם אבינו."],["462","76","ראה לעיל הערה 39."],["463","77","וראה בארוכה לקו\"ש ח\"ג ע' 762 ואילך."],["464","78","וי\"ל שזה שייך ל\"יעקב איש תם\" שיצא מהול (ראה לעיל הערה 66). ועפ\"ז נמצא שהי' ביעקב רק הענין דהטפת דם ברית (והצער שבזה), כי ענין התמימות מתבטא בעיקר בפעולת המילה לחוד, כבפנים. ולכן נולד מהול, ולא הוצרך לפעולה שלא יהי' ערל, ושיהי' מהול (שזה הי' אצלו בלא\"ה) — ראה לעיל הערה 74 — ורק פעולת המילה לחוד.\n[ולהעיר, שגם אצל דוד מצינו ע\"ד זה, כג' הפירושים בגמ' (סוטה י, ב) עה\"פ לדוד מכתם (תהלים נו, א): שהי' תם לכל דבר (תמים בדרכיו. רש\"י), שהי' מכתו תמה שנולד כשהוא מהול (וראה חדא\"ג מהרש\"א שם), כשם שבקטנותו הקטין עצמו אצל מי שגדול ממנו כו' כך בגדלותו כו' (ענין הביטול)]."],["465","79","ישעי' מט, כג. וראה זבחים יט, רע\"א."],["466","80","ה'תשמ\"ט (שנת הדפסת השיחה)."]]],[1301410117,"<h3>שיחה ג</h3>\nא. כתב הרמב\"ם בספר המצות: \"מצוה רטו היא שצונו למול את הבן, והוא אמרו ית' לאברהם<sup data-n=\"467\">1</sup> המול לכם כל זכר\". אמנם במנין המצות בריש ספר היד<sup data-n=\"468\">2</sup> כתב \"למול את הבן שנאמר וביום השמיני ימול בשר ערלתו\" — שהוא כתוב בפ' תזריע<sup data-n=\"469\">3</sup>.\nוצריך להבין טעם השינוי, שבמנין המצות הביא המקור למצוה זו מהכתוב דפ' תזריע ולא (כבספר המצות) מהציווי שנאמר לאברהם<sup data-n=\"470\">4</sup>.\nועוד תמוה: במנין המצות מדייק הרמב\"ם<sup data-n=\"471\">5</sup> בלשונו לומר \"למול את הבן\"<sup data-n=\"472\">6</sup>, שבפשטות כוונתו שהחיוב על האב למול את בנו [ובפרט ששינה ממ\"ש (בל' סתמי) בהכותרת להל' מילה \"למול הזכרים ביום השמיני\"]<sup data-n=\"473\">7</sup>; וא\"כ לכאורה הו\"ל להרמב\"ם להביא הכתוב דאברהם, ששם מוכח שהאב מצווה למול את בנו<sup data-n=\"474\">8</sup>, ולא הכתוב \"וביום השמיני ימול בשר ערלתו\" שלא נזכר בו שהחיוב הוא על האב<sup data-n=\"475\">9</sup>.\nלכאורה י\"ל ששינוי זה תלוי בפלוגתת הבבלי וירושלמי, שבבבלי<sup data-n=\"476\">10</sup> למדו החיוב שעל האב למול את בנו ממש\"נ<sup data-n=\"477\">11</sup> באברהם \"וימל אברהם את יצחק בנו\", ובירושלמי<sup data-n=\"478\">12</sup> למדו ממש\"נ \"וביום השמיני",[["467","1","פרשתנו יז, י."],["468","2","מ\"ע רטו — הובא גם בכס\"מ ריש הל' מילה."],["469","3","יב, ג."],["470","4","ובפרט ע\"פ תי' הא' בסנהדרין (נט, ריש ע\"ב) דנשנית בפ' תזריע רק למישרי שבת. וראה מנ\"ח מצוה ב בתחלתה.\nבהערות הר\"ח העליר לסהמ\"צ שם, מביא גירסא מכת\"י, שגם במנין המצות בריש ס' היד הובא הכתוב ד\"המול לכם כל זכר\". אבל הנוסח בדפוסים הנפוצים (ושהי' לפני הכס\"מ) הוא כבפנים, וכ\"ה לכל הגירסאות בס' המדע (ירושלים, תשכ\"ד)."],["471","5","גם בסהמ\"צ לפנינו איתא \"למול את הבן\". אבל בתרגום קאפח שם \"שנצטוינו להמול\" (ולא \"למול את הבן\")."],["472","6","ותיבות אלו נמצאות בכל הגירסאות בס' המדע (ירושלים, תשכ\"ד)."],["473","7","אבל בביאור הרי\"פ פערלא לסהמ\"צ רס\"ג מ\"ע לאלב (קפ, רע\"ג), שכוונת הרמב\"ם \"למול את הזכר, כידוע דפעמים הרבה תבוא הוראת בן במקום זכר כו'\" (ונכלל בזה גם הציווי למול עבדים. ומתרץ עפ\"ז קושיית הכס\"מ ריש הל' מילה). ע\"ש."],["474","8","אלא שבכתוב שהביא הרמב\"ם בסהמ\"צ \"המול לכם כל זכר\" לא מפורש לכאורה חיוב האב למול את בנו. — ובקידושין (כט, א) הובא הכתוב (וירא כא, ד) \"וימל אברהם את יצחק בנו\" (וראה מהרי\"ט, פני יהושע ועוד — קידושין שם).\nאבל ראה רש\"י שבת (קלב, ב ד\"ה בינוני) — \"ואביו מצווה עליו נפקא לן מהמול לכם כל זכר\", היינו שבהציווי דפרשתנו נכלל גם חיוב האב למול את בנו. וכבר העירו מיל\"ש וירא שם (רמז צב. וראה ב\"ר פנ\"ג, ז וברש\"י שם) \"וימל גו' בן שמונת ימים כאשר דבר<sup data-n=\"e10\">*</sup>. . והיכן דבר ובן שמונת ימים ימול לכם כל זכר\" (פרשתנו שם, יב). ואכ\"מ."],["475","9","ראה עצמות יוסף לקידושין שם. ולהעיר ממראה הפנים לירושלמי קידושין פ\"א ה\"ז."],["476","10","קידושין כט, א."],["477","11","וירא כא, ד. וראה לעיל הערה 8."],["478","12","קידושין פ\"א ה\"ז."],["e10","*","כ\"ה ביל\"ש ורש\"י לב\"ר שם. אבל בפ' וירא שם נאמר \"כאשר צוה\" (וראה יל\"ש עם שינויי נוסחאות כו' — ירושלים, תשל\"ג). — הלשון \"כאשר דבר\" נמצא לעיל סוף פרשתנו (יז, כג) במילת ישמעאל בנו כו'."]]],[1301410118,"ימול בשר ערלתו\" (ש\"ודאי דלאו אקטן מוטל לעשות רק על האב\" — קרבן העדה), ובספר היד נקט הרמב\"ם כדרשת הירושלמי.\nאבל הא גופא טעמא בעי, מדוע נקט הרמב\"ם בס' היד כהירושלמי ולא כהבבלי<sup data-n=\"479\">13</sup> (ובפרט ע\"פ הכלל הידוע<sup data-n=\"480\">14</sup> שהרמב\"ם מביא הדרשה הפשוטה יותר, והרי בכתובים דאברהם מפורש ופשוט (יותר) חיובא דאב<sup data-n=\"481\">15</sup>).\nב. והנה בפשטות יש לבאר זה ע\"פ דברי הרמב\"ם הידועים בפירוש המשניות שלו<sup data-n=\"482\">16</sup>, וז\"ל:\n\"ושים לבך על העיקר הגדול. . שכל מה שאנו מרחיקים או עושים היום אין אנו עושין אלא במצות הקב\"ה ע\"י משה רבינו ע\"ה לא שהקב\"ה אמר זה לנביאים שלפניו כגון. . אין אנו מלין מפני שאברהם אבינו ע\"ה מל עצמו ואנשי ביתו אלא מפני שהקב\"ה צוה אותנו ע\"י משה רבינו שנמול כמו שמל אברהם אבינו ע\"ה. וכן גיד הנשה אין אנו הולכים אחר איסור יעקב אבינו אלא מצות משה רבינו ע\"ה הלא תראה מה שאמרו תרי\"ג מצות נאמרו לו למשה מסיני וכל אלו מכלל המצות\".\nולכן לא נקט הרמב\"ם בס' היד הכתוב שנאמר לאברהם (היינו \"נביאים שלפניו\" דמשה) אלא דפ' תזריע<sup data-n=\"483\">17</sup>, שהוא הציווי ש\"הקב\"ה צוה אותנו ע\"י משה רבינו\"<sup data-n=\"484\">18</sup>.\nאבל עפ\"ז קשה יותר זה שבספר המצות מביא הכתוב דאברהם ולא הזכיר כלל הכתוב דפ' תזריע?\nויתירה מזו: בספר המצות מדגיש הרמב\"ם \"והוא אמרו ית' לאברהם המול לכם כל זכר\" — היינו שלא זו בלבד שמביא הכתוב דאברהם, אלא שמוסיף ומדגיש שהציווי לישראל (שצונו) למול",[["479","13","וראה ביאור פלוגתת הבבלי והירושלמי (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111054\" data-slug=\"likkutei-sichot\" data-id=\"1300111054\">לקו\"ש חי\"א ע' 46</a> הערה 26) — אם הוא חיובי' דאב או דבן. ע\"ש. וראה שם ע' 45 שוה\"ג הב' להערה 19. לקמן הערה 62. ואכ\"מ."],["480","14","יד מלאכי כללי הרמב\"ם אות ד."],["481","15","ראה לעיל הערה 8."],["482","16","חולין ספ\"ז. — וכבר העיר בבית האוצר (להר\"י ענגל) כלל א (אות ז ד\"ה וע\"ע רמב\"ם) מל' הרמב\"ם הל' מלכים רפ\"ט \"ונשלמה תורה על ידו\"."],["483","17","ומובן שאי\"ז סתירה שלמדים הרבה פרטי חיובים דמילה מכתובים דאברהם (קידושין שם) — כי (נוסף על המבואר בהערה הבאה, הרי) זהו רק בנוגע לפרטי המצוה, אבל כללות המצוה צ\"ל נשנית לאחר מ\"ת. — ולהעיר מהשקו\"ט בהכלל דאין למדין מקודם מתן תורה (ראה אנציקלופדי' תלמודית בערכו. וש\"נ. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251142\" data-slug=\"likkutei-sichot\" data-id=\"1300251142\">לקו\"ש חכ\"ה ע' 142</a> ובהערות שם)."],["484","18","וראה ביאור הרי\"פ פערלא לסהמ\"צ רס\"ג שם (קפ, אב) — ע\"פ מ\"ש הרשב\"ץ בזהר הרקיע (עשין ספ\"ה) — שאם מילה לא היתה נשנית בסיני, אין ראוי למנותה במנין המצות ולכן הביא הרמב\"ם הכתוב דפ' תזריע. ע\"ש באורך.\nאבל ראה אגרות הרמב\"ם (לפסיא טו, ד ואילך) שגם על הכתובים דאברהם אפ\"ל שהם ציווי שהקב\"ה ציוה אותנו ע\"י משה, כי גם כתובים אלו הם חלק מתורה שניתנה לנו ע\"י משה בסיני<sup data-n=\"e11\">*</sup> [וכמחז\"ל (חולין ק, ב במשנה) בגיד הנשה — שעליו קאי הרמב\"ם בפיהמ\"ש שם — \"שנכתב במקומו\"]. — אבל גם לפ\"ז י\"ל שהרמב\"ם נקט הכתוב שהוא בפשטות ציווי הקב\"ה ע\"י משה, ע\"ד הכלל הנ\"ל שהרמב\"ם נקט הדרשה הפשוטה יותר."],["e11","*","ולכאורה עכצ\"ל כן במצות פו\"ר שהביא בה הרמב\"ם (מ\"ע ריב) הכתוב דלפני הדיבור [אבל ראה ביאור הרי\"פ פערלא שם (קעט, ד) — ע\"פ הרשב\"ץ שם — דגם בפו\"ר אפ\"ל ד\"מעיקרא לישראל נאמרה ולא לב\"נ אלא שנכתבה אצל בני נח משום איזה טעם כדאמרינן בגיד הנשה\". וצ\"ע]. ואכ\"מ."]]],[1301410119,"כו' הוא הוא הציווי שהי' לאברהם — היפך ה\"עיקר הגדול\" שבפירוש המשניות, \"שכל מה שאנו. . עושים היום אין אנו עושין אלא במצות הקב\"ה על ידי משה רבינו ע\"ה לא שהקב\"ה אמר זה לנביאים שלפניו\".\nג. ויש לומר בהקדם תוס' ביאור בדברי הרמב\"ם הנ\"ל בפירוש המשניות, שלכאורה יש להקשות<sup data-n=\"485\">19</sup>:\nמכיון שמצות מילה המוטלת עלינו אינה מצות מילה שנצטווה אברהם אבינו, אלא יסודה וענינה הוא — \"מצות הקב\"ה על ידי משה רבינו ע\"ה\" — מדוע נקראת מצוה זו בשם \"בריתו של אברהם אבינו\", ועד שנקבע שם זה בנוסח הברכה<sup data-n=\"486\">20</sup> — \"להכניסו בבריתו של אברהם אבינו\"?\nומצינו ג\"כ ששייכותה של מצוה זו לבריתו של אברהם אבינו מוזכרת ומודגשת בספר היד, בכתבו ע\"ד גודל העילוי של ברית מילה וחומר הפרתה — \"לא<sup data-n=\"487\">21</sup> נקרא אברהם אבינו שלם עד שמל. . וכל המפר בריתו של אברהם אבינו. . וכל מצות התורה נכרתו עליהן שלש בריתות. . ועל המילה נכרתו שלש עשרה בריתות עם<sup data-n=\"488\">22</sup> אברהם אבינו\".\nוכעין הדגשה זו מצינו גם בפירוש המשניות שם גופא, וז\"ל: \"(אין אנו מלין מפני שאברהם אבינו ע\"ה מל. . אלא מפני שהקב\"ה צוה אותנו ע\"י משה רבינו) שנמול כמו שמל אברהם אבינו ע\"ה\" — דלכאורה<sup data-n=\"489\">23</sup> מה טעם הוספה זו \"שנמול כמו שמל אאע\"ה\", לאחר שקבע שאין אנו מלין אלא מפני שהקב\"ה צוה אותנו ע\"י משה? [וכמו בההמשך תומ\"י במצות גיד הנשה, שלא כתב הרמב\"ם ש\"מצות משה רבינו ע\"ה\" היתה שלא לאכול גיד הנשה כמו שלא אכלו יעקב ובניו<sup data-n=\"490\">24</sup>].\nד. וי\"ל הביאור בזה — בפשטות:\nבה\"עיקר הגדול\" שכתב הרמב\"ם — דזה שאנו מקיימים את המצות אינו מפני הציוויים שקדמו להציוויים על ידי משה רבינו בסיני — כוונתו לומר שכל החיוב המוטל עלינו בקיום כל המצות בא אך ורק מהציווי של הקב\"ה ע\"י מרע\"ה, בלי קשר וזיקה להציוויים שנאמרו ע\"י ה\"נביאים שלפניו\"; אבל אין זה נוגע לגוף המצות ומהותן, ויתכן שפיר שגדרן ומהותן של המצות דלאחר מ\"ת יש להן קשר ודמיון לענינן שלפני מ\"ת — ועד שיתכן שמהותן וענינן אחד.\nובנדו\"ד — מצות מילה: ודאי שרק ציוויו של הקב\"ה ע\"י משה רבינו הוא המחייב אותנו לקיים מצוה זו, ולא הציווי לאברהם; וביחד עם זה מהותה של מצות מילה שנצטווינו היא היא בריתו של אברהם אבינו — הקב\"ה ציונו (ע\"י משה רבינו) להכניס את הבן (ע\"י ברית מילה) בהברית שכרת הוא ית' עם אברהם אבינו.",[["485","19","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101044\" data-slug=\"likkutei-sichot\" data-id=\"1300101044\">לקו\"ש ח\"י (ע' 44</a> ואילך) — בפנימיות הענינים."],["486","20","שבת קלז, ב. רי\"ף שם. רמב\"ם הל' מילה רפ\"ג."],["487","21","הל' מילה פ\"ג ה\"חט."],["488","22","ובפרט שתיבות אלו (\"עם כו'\") הן הוספת הרמב\"ם (על ל' הש\"ס — נדרים לא, ב במשנה (וראה ר\"נ שם: בפרשת מילה). וראה ירושלמי שם פ\"ג ריש ה\"ט: כתיב ביום ההוא כרת ה' ברית את אברם לאמר וגו' עד ואת בריתי. . י\"ג בריתות). וראה גם פיהמ\"ש להרמב\"ם נדרים שם."],["489","23","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101047\" data-slug=\"likkutei-sichot\" data-id=\"1300101047\">לקו\"ש שם ע' 47</a> הערה 29 (ולקו\"ש ח\"ה שצויין בהערה הבאה) — בפנימיות הענינים."],["490","24","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051101\" data-slug=\"likkutei-sichot\" data-id=\"1300051101\">לקו\"ש ח\"ה (ע' 89</a> הערה 25) ע\"ד לשון הרמב\"ם שם בנוגע לאבר מן החי \"שיתקיים איסור אבר מן החי\". ע\"ש."]]],[1301410120,"ועפ\"ז נמצא, שבמצות מילה יש חידוש גדול לגבי שאר המצות שנצטוו עליהן קודם מ\"ת:\nבשאר המצות הרי המצוה כפי שניתנה במ\"ת היא מצוה חדשה שאינה קשורה עם הציווי שהי' לפני מ\"ת, וע\"ד \"ניתנה תורה ונתחדשה הלכה\"<sup data-n=\"491\">25</sup>; ואפילו כאשר גוף המצוה לא נשתנה — הרי אין לתוכן וענין המצוה שאנו מקיימים קשר ושייכות להמצוה שהיתה קודם מ\"ת, ולדוגמא — אבר מן החי: זה שאנו אסורים באכילת אבר מן החי אין לו קשר לאיסור אבר מן החי שהי' נוהג לפני מ\"ת.\nוגם באיסור גיד הנשה שמפורש בגמ'<sup data-n=\"492\">26</sup> \"שנכתב במקומו (בפ' וישלח) לידע מאיזה טעם נאסר להם\", שהטעם שהוזהרנו (לאחר מ\"ת) שלא לאכול גיד הנשה הוא מפני \"(על כן. . ) כי נגע בכף ירך יעקב בגיד הנשה\"<sup data-n=\"493\">27</sup> — הרי זה רק טעם המצוה, שאיסור אכילת גיד הנשה הוא זכר להמאורע שאירע עם יעקב, אבל בגוף ועצם המצוה אין קשר ביניהם.\nמשא\"כ במילה, שהקשר של מצוה זו שאנו מקיימים למצות מילה דאברהם אבינו אינו רק טעם וזכר, אלא שהוא אותו הענין ממש<sup data-n=\"494\">28</sup>, שתוכן מצות מילה שלנו הוא מה שמכניסים את הנמול \"בבריתו של אברהם אבינו\".\n[וזהו עוד יותר ממ\"ש הב\"ח<sup data-n=\"495\">29</sup> גבי מצות סוכה, שכוונת המצוה — \"למען ידעו דורותיכם כי בסוכות הושבתי את בנ\"י בהוציאי אותם וגו'\"<sup data-n=\"496\">30</sup> — היא חלק מהמצוה עצמה, ובלי כוונה זו \"לא קיים המצוה כתיקונה\" (דאף שתלה הכתוב \"הרבה מצות\"<sup data-n=\"497\">31</sup> ביציאת מצרים, מ\"מ, בשאר המצות הם רק טעם וזכר, משא\"כ במצות סוכה הרי כוונה זו היא חלק מעצם המצוה),\nדשם הרי סו\"ס אין זה אלא כוונה וזכר, אלא שהם חלק ופרט מקיום המצוה; משא\"כ בנדו\"ד — מצות מילה, שהענין ד\"בריתו של אברהם אבינו\" אינו רק פרט וחלק מהמצוה, אלא הוא מהותה של המצוה, שע\"י מצוה זו מכניסים את הנמול \"לבריתו של אברהם אבינו\", כנ\"ל].\nוזוהי כוונת הרמב\"ם בהוסיפו \"שהקב\"ה צוה אותנו ע\"י משה רבינו שנמול כמו שמל אברהם אבינו ע\"ה\" — להדגיש החידוש במצות מילה שאנו מקיימים, שה\"ברית\" הנפעלת על ידי המילה שלנו היא אותה ה\"ברית\" שכרת הקב\"ה עם אברהם אבינו.\nויש לומר, שזה מודגש עוד יותר בזה שרוב פרטי החיובים דמילה נלמדו מהכתובים דאברהם<sup data-n=\"498\">32</sup>, ועד שגם חיוב כרת נאמר (ורק) גבי אברהם<sup data-n=\"499\">33</sup> (ולא בפ'",[["491","25","שבת קלה, סע\"א (בנוגע למילה. וראה הערה 28). ב\"ב קי, ב. — ועד כ\"כ שהציוויים שקודם מ\"ת נתבטלו (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081068\" data-slug=\"likkutei-sichot\" data-id=\"1300081068\">לקו\"ש ח\"ח ע' 57</a> ואילך ובהערות שם)."],["492","26","חולין קא, ב."],["493","27","וישלח לב, לג."],["494","28","אף שפרטי דיני מילה שלנו אינם בדיוק כבאברהם, כי ניתנה תורה ונתחדשה הלכה (שבת שם). ואחז\"ל (יבמות עא, ב) דלא ניתנה פריעת מילה לאברהם, אף שלאחרי מ\"ת מל ולא פרע כאילו לא מל (שבת קלז, ריש ע\"ב במשנה). ועוד."],["495","29","לטאו\"ח סי' ח (ד\"ה ונקראים). שם סי' תרכ\"ה."],["496","30","אמור כג, מג."],["497","31","ל' הטור סתרכ\"ה שם."],["498","32","ראה קידושין שם."],["499","33","פרשתנו יז, יד (וראה הערה 35). — ולהעיר שלשון הכתוב שם הוא \"ונכרתה גו' מעמי'\". ומובן ממשנ\"ת לקמן סעיף ז, שהתחלת עם ישראל היא מאברהם (אף שמצות התורה הן רק מסיני)."]]],[1301410121,"תזריע) — להדגיש שמצות מילה שלנו היא היא \"בריתו של אברהם אבינו\".\nה. ועפ\"ז יש לבאר טעם השינוי בין ספר המצות, ששם הביא הרמב\"ם הכתוב דאברהם, ומנין המצות בריש ספר היד, ששם הביא הכתוב דפ' תזריע:\nמהחילוקים בין ספר המצות ומנין המצות שבספר היד הוא:\nספר המצות אינו ספר הלכה, אלא רק ביאור של התרי\"ג מצות, תיאור קצר של המצוה ומקורה בתושב\"כ ודיני' (בכללות) בתושבע\"פ<sup data-n=\"500\">34</sup>; וכמו\"כ בנדו\"ד, מכיון שעיקר פרשת מילה הוא — הכתובים דאברהם שמשם נלמדים רוב פרטי', ושם מבואר מהותה של המצוה, שהיא \"ברית\" בין ישראל להקב\"ה (בריתו של אברהם) — מביא הרמב\"ם הכתוב \"המול לכם כל זכר\"; ולכן מדגיש שם שהציווי הי' \"לאברהם\" — כי זהו ענינה של מצות מילה, \"בריתו של אברהם אבינו\", כנ\"ל<sup data-n=\"501\">35</sup>.\nמשא\"כ במנין המצות שבריש ס' היד — ספר \"הלכות הלכות\"<sup data-n=\"502\">36</sup> — מביא הרמב\"ם הכתוב שעיקרו (לא מהותה וגדרה של המצוה, אלא) מקור החיוב לקיים מצוה זו בתור אחת מתרי\"ג מצות שנאמרו למשה בסיני; והיות \"שכל מה שאנו מרחיקים או עושים היום אין אנו עושין אלא במצות הקב\"ה ע\"י משה רבינו ע\"ה לא שהקב\"ה אמר זה לנביאים שלפניו\", מובן, שצריך להביא הכתוב שלאחרי מ\"ת, שהיא (בפשטות<sup data-n=\"503\">37</sup>) \"מצות הקב\"ה ע\"י משה רבינו\", כי חלות החיוב דמצוה זו היא מכתוב זה דוקא.\nו. חידוש זה שבמצות מילה (שמהותה של ברית מילה היא — \"בריתו של אברהם אבינו\", שלפני הדיבור) — יובן יותר ממשנ\"ת במק\"א<sup data-n=\"504\">38</sup>, שבמצות מילה יש שני ענינים:\nא) מצוה פרטית, אחת מתרי\"ג מצות התורה.\nב) ענין כללי — \"ברית\" בין ישראל והקב\"ה, \"זאת בריתי. . ביני וביניכם\"<sup data-n=\"505\">39</sup>, שברית מילה שייכת לעצם קדושת ישראל. וי\"ל שזהו גם עיקר כוונת הרמב\"ם במ\"ש (בחותם הל' מילה<sup data-n=\"506\">40</sup>) \"מאוסה היא הערלה שנתגנו בה הגוים שנאמר<sup data-n=\"507\">41</sup> כי כל הגוים ערלים\", להדגיש, שענין המילה נוגע לכללות \"ישראל\" [שלכן, גם איש ישראל שאינו יכול לקיים מצות מילה בפועל (מפני שאחיו מתו מחמת מילה וכיו\"ב<sup data-n=\"508\">42</sup>) נק' \"מהול\"<sup data-n=\"509\">43</sup>, שי\"ל הטעם, כי עיקר שם \"מהול\" הוא לא מפני פעולת המילה, אלא מפני חיובו להכנס לברית זו, שישנו גם במי שאינו יכול לקיים המצוה בפועל<sup data-n=\"510\">44</sup>].\nוליתר ביאור: גם ה\"מצוה פרטית\" דמילה נקראת בשם \"ברית\" — אלא שישנם שני ענינים בה\"ברית\" שבין ישראל והקב\"ה: א) הברית על קיום התומ\"צ<sup data-n=\"511\">45</sup>,",[["500","34","ראה הקדמת הרמב\"ם לספר המצות."],["501","35","ולהעיר, שבריש הל' מילה מביא הרמב\"ם (לא מקור המצוה, הכתוב דפ' תזריע, אלא) \"מילה מ\"ע שחייבין עלי' כרת שנאמר (באברהם) וערל זכר גו' ונכרתה גו'\". וראה לקמן הערה 50, שבזה מודגש תוכנה הכללי של מצות מילה."],["502","36","ל' הרמב\"ם בסוף הקדמתו לס' היד."],["503","37","ראה לעיל הערה 18."],["504","38","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251058\" data-slug=\"likkutei-sichot\" data-id=\"1300251058\">לקו\"ש חכ\"ה ע' 58</a> ואילך. וראה גם לקו\"ש חל\"ה ע' 56 ואילך."],["505","39","פרשתנו יז, י. וראה שם, יגיד. ועוד."],["506","40","והוא ממשנה נדרים לא, ב."],["507","41","ירמי' ט, כה."],["508","42","ראה רש\"י ועוד נדרים שם. וראה ע\"ז כז, א."],["509","43","משנה נדרים שם."],["510","44","ראה ע\"ז שם."],["511","45","ראה רד\"ק ירמי' שם. ועוד. ולהעיר מב' הפירושים בפסוק (ירמי' לג, כה) \"אם לא בריתי גו'\" — אם קאי על תורה או על מילה (שבת לג, א. קלז, ב. נדרים לא, ב (במשנה). שם לב, א)."]]],[1301410122,"ב) ה\"ברית\" והקשר שבין הקב\"ה וישראל מצד מהותם דישראל<sup data-n=\"512\">46</sup>. וזהו הענין הכללי שבברית מילה, שנוסף על היותה מצוה פרטית (אחת מתרי\"ג מצות התורה) הרי היא אות הברית השייכת לישראל. וכמפורש במאמר חז\"ל<sup data-n=\"513\">47</sup> שמביא הרמב\"ם (בהמשך ל\"מאוסה היא הערלה כו'\") \"וכל<sup data-n=\"514\">48</sup> המפר בריתו של אברהם כו' אע\"פ שיש בו תורה ומעשים טובים אין לו חלק לעולם הבא\" — כי הברית דמילה קדמה לברית דתורה ומעשים טובים, שקודם צ\"ל<sup data-n=\"515\">49</sup> המציאות דישראל (והברית עמו), ואח\"כ<sup data-n=\"515\">49</sup> שייך הברית דתורה<sup data-n=\"517\">50</sup>.\n[וי\"ל שזוהי כוונת המדרש<sup data-n=\"518\">51</sup> \"אם אין אדם נמול אינו יכול ללמוד תורה שנאמר<sup data-n=\"519\">52</sup> מגיד דבריו ליעקב למי שהוא מל כיעקב לא<sup data-n=\"519\">52</sup> עשה כן לכל גוי משום שהם ערלים\" — דברית מילה קדמה לתורה, כי תורה ומצות ניתנו לישראל דוקא ולא לאומות העולם, וישראל שייך לברית מילה].\nז. ובזה יש לבאר הטעם שלא זו בלבד שמצות מילה התחילה מאברהם אבינו, אלא עוד זאת — שמצות מילה שאנו מקיימים לאחרי מ\"ת קשורה לאברהם ועד שנקראת \"בריתו של אברהם אבינו\":\n\"בריתו של אברהם אבינו\" אינה כריתת ברית על קיום התורה ומצות, כי ענין התורה מתחיל מזמן מתן תורה, וכנ\"ל מהרמב\"ם שאין המצוות שלנו באות מהציוויים שלפני הדיבור; אלא ה\"ברית\" עם אברהם, \"ביני וביניכם ובין זרעך אחריך\", היא עם ישראל, דהתחלת עם ישראל היא מאברהם יצחק ויעקב<sup data-n=\"521\">53</sup>, ומאז הותחלה ברית וקדושת ישראל\n[לא מיבעי להדיעות<sup data-n=\"522\">54</sup> שהאבות יצאו מכלל ב\"נ, אלא אפילו להדיעות<sup data-n=\"522\">54</sup> שלא יצאו מכלל ב\"נ — ה\"ז רק בנוגע לקיום המצות שלהם וכיו\"ב, אבל מציאות עם ישראל התחילה מהאבות].\nונמצא, שאף שהמצות שלנו אינן קשורות להמצות שלפני הדיבור — מ\"מ מציאות עם ישראל מתחילה מהאבות.\nומזה — שני הענינים שבמצות מילה: גוף המצוה והחובה של מצות מילה (כאחת מתרי\"ג מצות) אינו שייך לציווי הקב\"ה לאברהם, כי אם רק למצות",[["512","46","ראה לבוש יו\"ד סו\"ס רס, שהמילה היא \"אות חתום בבשרינו ומעידה בנו שבחר בנו מכל העמים ואנחנו עמו כו' חייבים לעובדו כו'\". וראה חינוך מצוה ב. ועוד. וראה סידור עם דא\"ח ש' המילה (קמג, גד). ועוד."],["513","47","אבות פ\"ג מי\"א."],["514","48","ל' הרמב\"ם."],["515","49","ע\"ד מחז\"ל (ב\"ר פ\"א, ד. וראה תדבא\"ר פי\"ד) דישראל קדמו לתורה, שנאמר צו את בני ישראל דבר אל בני ישראל.\nולהעיר ג\"כ ממחז\"ל (ברכות מח, סע\"ב ואילך. רמב\"ם הל' ברכות פ\"ב ה\"ג. וראה משנה נדרים שם. רמב\"ם סוף הל' מילה) \"צריך שיקדים ברית לתורה שזו נתנה בג' בריתות וזו נתנה בי\"ג בריתות\". וראה תו\"א סוף פרשתנו."],["515","49","ע\"ד מחז\"ל (ב\"ר פ\"א, ד. וראה תדבא\"ר פי\"ד) דישראל קדמו לתורה, שנאמר צו את בני ישראל דבר אל בני ישראל.\nולהעיר ג\"כ ממחז\"ל (ברכות מח, סע\"ב ואילך. רמב\"ם הל' ברכות פ\"ב ה\"ג. וראה משנה נדרים שם. רמב\"ם סוף הל' מילה) \"צריך שיקדים ברית לתורה שזו נתנה בג' בריתות וזו נתנה בי\"ג בריתות\". וראה תו\"א סוף פרשתנו."],["517","50","ועפ\"ז מובן בפשטות הטעם שמילה היא מ\"ע שחייבים עלי' כרת, שאין זה עונש רק על ביטול מ\"ע אחת, אלא בעיקר מפני שזה נוגע לעצם ענין ישראל."],["518","51","תנחומא משפטים ד."],["519","52","תהלים קמז, יטכ."],["519","52","תהלים קמז, יטכ."],["521","53","ראה גם רמב\"ם הל' ע\"ז ספ\"א: ונעשית בעולם אומה כו' (וראה לקו\"ש חלק לא ע' 10 ואילך, הטעם שלידת עם ישראל היא ביצי\"מ דוקא). וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>: האבות. . זכו להמשיך נר\"נ לבניהם אחריהם עד עולם."],["522","54","ראה בארוכה פרשת דרכים בתחלתו. בית האוצר להר\"י ענגל בתחלתו. וש\"נ."],["522","54","ראה בארוכה פרשת דרכים בתחלתו. בית האוצר להר\"י ענגל בתחלתו. וש\"נ."]]],[1301410123,"הקב\"ה על ידי משה רבינו; אבל תוכן הברית הנפעל על ידי מצוה זו — השייך לעם ישראל — ה\"ז \"בריתו של אברהם אבינו\", היא המשך להברית שכרת הקב\"ה עם אברהם, \"זאת בריתי. . ביני וביניכם ובין זרעך אחריך\".\nח. עפ\"ז יש לבאר עוד הלכה ברמב\"ם:\nבנוגע לברכת המילה פסק הרמב\"ם בהל' מילה<sup data-n=\"524\">55</sup>: ואבי הבן מברך ברכה אחרת כו' להכניסו בבריתו של אברהם אבינו, מצוה על האב למול את בנו יתר על מצוה שמצווין ישראל שימולו כל ערל שביניהן לפיכך אם אין שם אביו אין מברכין אחרי' ברכה זו. ויש מי שהורה שיברכו אותה ב\"ד או אחד מן העם ואין ראוי לעשות כן.\nכלומר: לדעת הרמב\"ם, הברכה \"להכניסו בבריתו של אברהם אבינו\" נתקנה במיוחד עבור אבי הבן, מפני מצוותו הנוספת והמיוחדת שיש לו (\"יתר על מצוה שמצווין (כל) ישראל\") למול את בנו. ולכן \"אם אין שם אביו אין מברכין אחרי' ברכה זו\".\nומשמעות הענין היא, שזה שע\"י ברית מילה מכניסים את הנמול \"בבריתו של אברהם אבינו\", שייך (בעיקר) למצות האב דוקא.\nיש שביארו<sup data-n=\"525\">56</sup> לפי מה דיליף בקידושין<sup data-n=\"526\">57</sup> דמצות האב למול את בנו הוא מדכתיב<sup data-n=\"527\">58</sup> וימל אברהם את יצחק בנו, ונמצא שמצות האב שייכת ל\"בריתו של אברהם אבינו\" (שממנו ילפינן חיובא דאב).\nאבל מלבד זאת שבס' היד (במנין המצות) מביא הרמב\"ם (כנ\"ל) הכתוב דפ' תזריע ולא הכתוב דאברהם<sup data-n=\"528\">59</sup> — הנה גם הביאור עצמו צ\"ע, שהרי גם החיוב שעל ב\"ד, וכן החיוב של הבן עצמו, נלמדים בקידושין שם מהכתובים גבי אברהם, וא\"כ גם החיוב של כל ישראל (ב\"ד) ושל הבן עצמו שייכים ל\"בריתו של אברהם אבינו\", ואין חובת האב שונה מחיובם בענין זה.\nט. אמנם ע\"פ משנת\"ל בביאור הלשון \"בריתו של אברהם אבינו\" — יש לבאר השייכות למצות האב דוקא:\nשם \"ישראל\" תלוי בלידה, שבא להנולד בירושה מאביו ואמו, דלהיותו בן אברהם יצחק ויעקב (ובת שרה רבקה רחל ולאה) יש לו ממילא שם ישראל בפועל [משא\"כ ה\"ברית\" דתורה, אף שמתחייב בתורה ומצוות בדרך ממילא להיותו איש (ואשה ד)ישראל — מ\"מ, קיום התומ\"צ בפועל תלוי בבחירתו].\nונמצא, שמהותה של מצות מילה (היינו הענין הכללי שבה — \"בריתו של אברהם אבינו\") הרי היא המשך ללידת הבן, שאז נכנס (בדרך ממילא, מצד הלידה) לכלל ישראל, ושלימות שם ישראל באה לו בעת ברית מילה (ואשה כמאן דמהילא דמיא<sup data-n=\"529\">60</sup>).\nויש לומר שזהו הטעם שבמצות מילה יש מצוה מיוחדת על האב \"יתר על מצוה שמצווין ישראל\" [ופשטות הלשון היא, שזה שהמצוה היא על האב אינו רק משום שאא\"פ לקטן למול א\"ע ולכן",[["524","55","רפ\"ג."],["525","56","הגהות בני בנימין לרמב\"ם שם."],["526","57","כט, א."],["527","58","וירא כא, ד."],["528","59","וכמ\"ש בהגהות בני בנימין שם, שביאורו אינו לפי הירושלמי שנלמד מהכתוב דפ' תזריע."],["529","60","ע\"ז כז, א."]]],[1301410124,"הטילה התורה חיוב זה על האב<sup data-n=\"530\">61</sup>, אלא שזוהי בעצם חובת ומצות האב<sup data-n=\"531\">62</sup>]:\nהחיוב של כל ישראל \"שימולו כל ערל שביניהן\" הוא בעיקר מצד גדר חיוב המצוה, שמפני חומרת מצוה זו, הטילה התורה חובה על כל ישראל (ב\"ד) \"שימולו כל ערל שביניהן\"; משא\"כ המצוה שעל האב היא המשך להולדת הבן, דלהיות שהורי הבן<sup data-n=\"532\">63</sup> הם שהכניסו אותו לכלל ישראל (ע\"י לידתו<sup data-n=\"533\">64</sup>), לכן על האב לגמור ו\"להשלים\" אצלו כניסה זו לישראל, על ידי ברית מילה.\nולכן תיקנו הנוסח \"להכניסו בבריתו של אברהם אבינו\" במצות האב דוקא — כי ההכנסה \"בבריתו של אברהם אבינו\", שלימות ענין ישראל, שייכת בעיקר להאב, שהכניסו לכלל ישראל.\n<span data-k=\"q\">(משיחות פורים וט\"ז אדר תשמ\"ז) </span>",[["530","61","ראה ביאור הרי\"פ פערלא לסהמ\"צ רס\"ג שם בסופו. חמדת ישראל קונט' נר מצוה לסהמ\"צ מ\"ע רטו. כלי חמדה פרשתנו יז, י (אות ד)."],["531","62","וכן מוכח מפסק הרמב\"ם שהאב מברך \"למול\" (ראה לקו\"ש חי\"א שצויין לעיל הערה 13). וראה כלי חמדה שם."],["532","63","אלא שהוציאה תורה את האם מחיוב זה ואמרה \"כאשר צוה אותו אלקים, אותו ולא אותה\" (קידושין כט, א. וראה ע\"ז כז, א ובתוד\"ה אשה שם. ובמדרש הגדול פרשתנו (יז, יג) למדו מ\"המול ימול\")."],["533","64","אף שהיותו ישראל (יהודי) תלוי' בהאם ולא בהאב."]]],[1301410125,"<h3>שיחה א</h3>\nא. איתא בגמ'<sup data-n=\"534\">1</sup>: שלשה סימנים יש באומה זו הרחמנים והביישנין<sup data-n=\"535\">2</sup> וגומלי חסדים, רחמנים דכתיב<sup data-n=\"536\">3</sup> ונתן לך רחמים ורחמך והרבך, ביישנין דכתיב<sup data-n=\"537\">4</sup> בעבור תהי' יראתו על פניכם [כד\"אמרינן<sup data-n=\"538\">5</sup> בנדרים<sup data-n=\"539\">6</sup> בעבור תהי' יראתו על פניכם גו' זו הבושה וכו', כי היראה הניכרת בפנים היא הבושה\"], גומלי חסדים דכתיב<sup data-n=\"540\">7</sup> למען אשר יצוה את בניו ואת ביתו גו', כל שיש בו שלשה סימנים הללו ראוי להדבק באומה זו<sup data-n=\"541\">8</sup>. וכן נפסק להלכה ברמב\"ם לענין משפחות הכשרות (כדלקמן סעיף ב).\nוהנה מאמר זה הובא גם בירושלמי<sup data-n=\"542\">9</sup>, אבל שם (וכן בכמה מדרשים<sup data-n=\"543\">10</sup>) לא נלמד הסימן ד\"גומלי חסדים\" מהכתוב (באברהם) \"למען אשר יצוה את בניו ואת ביתו גו'\", אלא ממ\"ש<sup data-n=\"544\">11</sup> \"ושמר ה' אלקיך לך את הברית ואת החסד\"<sup data-n=\"545\">12</sup>.\nויש לומר, ששינוי זה קשור עם חילוק אחר בין דרשת הבבלי ודרשת הירושלמי: בבבלי נאמר \"שלשה סימנים יש באומה זו\", אבל בירושלמי (ועד\"ז בכמה מדרשים הנ\"ל<sup data-n=\"546\">13</sup>) הלשון \"ג' מתנות טובות נתן הקב\"ה לישראל\":\nלהבבלי, עיקר ההדגשה הוא בזה שהמדות הללו הן \"סימנים\" על האופי העצמי של בני \"אומה זו\", ולכן מביא ראי' ממ\"ש באברהם (\"למען אשר יצוה גו'\"), שאברהם (מצד עצמו) הי' גומל חסד וכן צוה לביתו אחריו<sup data-n=\"547\">14</sup>, שמזה מוכח שאברהם הי' חסדן מצד עצם טבע נפשו<sup data-n=\"548\">15</sup>, ובמילא, שהחסד הוא סימן על עצם טבע נפשם של בני אומה זו<sup data-n=\"549\">16</sup>;",[["534","1","יבמות עט, א."],["535","2","כ\"ה בגמ' שלפנינו. ובע\"י: רחמנין וביישנין."],["536","3","פ' ראה יג, יח."],["537","4","יתרו כ, יז."],["538","5","ל' המהרש\"א בחדא\"ג יבמות שם."],["539","6","כ, א."],["540","7","פרשתנו יח, יט."],["541","8","כ\"ה בגמ' לפנינו. ובע\"י \"להדבק בו (ומסיים) אין בו שלשה סימנין הללו אין ראוי להדבק בו\". וראה לקמן סעיף ב."],["542","9","קידושין פ\"ד ה\"א."],["543","10","דב\"ר פ\"ג, ד. מדרש תהלים מזמור א ומזמור יז. מדרש שמואל פכ\"ח. — ובבמדב\"ר פ\"ח, ד הביא שני הכתובים (וראה כלי יקר לש\"א (כא, ב) — צויין באוה\"ת פרשתנו צו, ריש ע\"ב)."],["544","11","ר\"פ עקב."],["545","12","בדוחק י\"ל שהירושלמי ס\"ל שאין ראי' מהכתוב \"למען אשר יצוה גו'\" כיון שלא נזכר בכתוב בפירוש חסד, רק משפט וצדקה (וראה חדא\"ג מהרש\"א יבמות שם). וראה פי' מהרז\"ו לדב\"ר שם.\nולהעיר, שלכאורה אדרבה, הראי' מ\"ושמר לך גו'\" קלושה, שהרי בפשטות קאי על חסדו של הקב\"ה — משא\"כ הראי' מ\"ונתן לך רחמים\" מובנת, כי על רחמי הקב\"ה לא מתאים (כ\"כ) הלשון \"ונתן לך\" (וראה אוה\"ח עה\"פ). וראה גם אלשיך ר\"פ עקב (ומתרץ שנלמד מריבוי ד\"את (החסד)\" — \"לרבות גם את מדת חסד אשר לישראל\")."],["546","13","במדב\"ר, מדרש תהלים ומדרש שמואל הנ\"ל (אלא שבמד\"ש לפנינו \"מדות\" במקום \"מתנות\". אבל בהוצאת באבער שם \"מתנות\"). — ובדב\"ר שם \"ג' מדות טובות יש ביד ישראל\"."],["547","14","וראה כתובות ח, ב: גומלי חסדים בני גומלי חסדים המחזיקים בבריתו של אברהם אבינו שנאמר כי ידעתיו גו', וברש\"י וחדא\"ג מהרש\"א שם."],["548","15","ראה ספר הערכיםחב\"ד ערך אברהם אבינו סעיף ג. וש\"נ. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא ספ\"א</a> שזהו טבעה גם של נפש הבהמית שבישראל."],["549","16","כלומר: אף שגם אם ג' מדות הללו באות במתנה מהקב\"ה ה\"ה סימנים על אומה זו, מ\"מ, עדיף יותר להביא ראי' שזהו אופי בני האומה מצד טבע נפשם, מזה שהן בדרך מתנה (ודבר נוסף על מציאותם)."]]],[1301410126,"משא\"כ בירושלמי מדייק, שמדות אלו הן \"מתנות טובות (ש)נתן הקב\"ה לישראל\", וא\"כ אין המדובר במדת החסד הטבועה בנפשו של אברהם (וזרעו אחריו) מצד עצמה, אלא מדת חסד כזו שהיא מתנה מיוחדת מהקב\"ה לישראל, ולכן מביא הכתוב ד\"ושמר ה\"א לך את הברית ואת החסד\".\nוצריך ביאור:\nא) מהו תוכן החילוק בין הבבלי והירושלמי, אם המדובר במדת החסד הטבעית של אברהם, או במדת החסד שניתנה במתנה מלמעלה — למאי נפק\"מ?\nב) בנוגע לרחמים ובושה, הרי גם בבבלי הובאו כתובים המורים שהם מתנה מהקב\"ה לישראל: ברחמים — \"ונתן לך רחמים\", וכן בבושה \"בעבור תהי' יראתו על פניכם\", דקאי על מ\"ת, שהקולות והלפידים כו' דמ\"ת פעלו ש\"תהי' יראתו על פניכם גו'\".\nבשלמא גבי בושה מובן, ע\"פ המבואר במהרש\"א<sup data-n=\"550\">17</sup> שטבע הבושה אכן נקבע בנפש בני ישראל אך ורק ע\"י מ\"ת, כי בנ\"י מצ\"ע הרי הם, אדרבה, \"עזין\" שבאומות<sup data-n=\"551\">18</sup> [שלכן דייקו חז\"ל<sup data-n=\"552\">19</sup> ד\"מי שאין לו בושת פנים בידוע שלא עמדו אבותיו על הר סיני\"]:\nאבל בנוגע לרחמים, הרי זהו טבע נפשם של בני אומה זו, שירשו מאברהם אבינו, וכמפורש בחז\"ל<sup data-n=\"553\">20</sup> \"כל המרחם על הבריות בידוע שהוא מזרעו של אברהם אבינו\", שבפשטות נקט \"זרעו של א\"א\" משום שאברהם אבינו הי' רחמן בטבעו, וכמבואר במהרש\"א<sup data-n=\"554\">21</sup> ש\"נקט במלתי' זרעו של אברהם. . דבאברהם מפורש מדת הצדקה כי ידעתיו למען אשר יצוה את בניו וגו'\"<sup data-n=\"555\">22</sup> — והבבלי הביא הכתוב ד\"ונתן לך רחמים גו'\" (שמשמעו שהמדובר במדת הרחמים שהיא מתנה מלמעלה).\nב. והנה עוד חילוק מצינו בין הבבלי והירושלמי:\nבבבלי מסיים \"כל שיש בו שלשה סימנים הללו ראוי להדבק באומה זו\", משא\"כ בירושלמי<sup data-n=\"556\">23</sup> מסיים \"ואלו (הגבעונים) אין בהן אחד מהן מיד עמד וריחקן\", והיינו שבירושלמי מפורש שלא הי' לגבעונים אף אחד מג' סימנים הללו<sup data-n=\"557\">24</sup>.\nולפ\"ז י\"ל לכאו' נפק\"מ להלכה בין הבבלי והירושלמי, דלהירושלמי אין מרחקים את האדם אלא כשאין אצלו אף אחת מג' המדות הללו (אבל אם חסרה אצלו רק אחת (או שתים) מהן אין מרחקים אותו<sup data-n=\"558\">25</sup>); משא\"כ פשטות ל' הבבלי \"כל שיש בו שלשה סימנים הללו ראוי",[["550","17","חדא\"ג יבמות שם. וראה אוה\"ת פרשתנו (שם, סע\"א). ליקוט פירושים כו' לתניא פ\"א (ע' מו)."],["551","18","ביצה כה, ב."],["552","19","נדרים כ, א. והובא ג\"כ בירושלמי קידושין שם. במדב\"ר, מדרש תהלים ומדרש שמואל שצויינו בהערה 10."],["553","20","ביצה לב, ב."],["554","21","חדא\"ג ביצה שם."],["555","22","וראה גם רמב\"ם הל' מתנות עניים רפ\"י. טיו\"ד ר\"ס רמז ובפרישה שם סק\"ד. פי' מהרז\"ו לדב\"ר שם."],["556","23","וכן במדרשים שצויינו בהערה 19."],["557","24","ראה קרבן העדה שם. יפה תואר לבמדב\"ר שם (הועתק בעץ יוסף לע\"י יבמות שם). וראה הערה הבאה."],["558","25","וכן פסק בב\"ש אה\"ע ס\"ב סק\"ה — אלא ש\"הוא אמר זה מסברא דנפשי'\" (עץ יוסף שבהערה הקודמת)."]]],[1301410127,"להדבק באומה זו\", משמעה, שצריכים להיות אצלו כל שלשת הסימנים<sup data-n=\"559\">26</sup>.\nאבל י\"ל שאין הדברים מוכרחים, כי:\nא) הגירסא בעין יעקב היא \"(כל שיש בו. . ראוי כו') אין בו שלשה סימנים הללו אין ראוי להדבק בו\"<sup data-n=\"560\">27</sup> — שבזה יש לפרש (כהירושלמי) שרק אם אין בו כל שלשת הסימנים אין ראוי להדבק בו, ואין לאפושי פלוגתא בין הבבלי והירושלמי, כידוע הכלל בזה<sup data-n=\"561\">28</sup>.\nב) ברמב\"ם<sup data-n=\"562\">29</sup> כ' ש\"סימני ישראל האומה הקדושה ביישנין רחמנים וגומלי חסדים ובגבעונים הוא אומר<sup data-n=\"563\">30</sup> והגבעונים לא מבני ישראל המה לפי שהעיזו פניהם. . ולא רחמו על בני שאול ולא גמלו לישראל חסד כו'\", הרי שהרמב\"ם מדייק (כהירושלמי) שלא הי' אצל הגבעונים \"אחד מהן\", שמזה משמע, שאין מרחקין אא\"כ חסרות כל ג' מדות הללו\n[וכלשון הרמב\"ם שם<sup data-n=\"562\">29</sup> — לפי כתבייד מדוייקים<sup data-n=\"565\">31</sup>: \"כל מי שיש בו עזות פנים ואכזריות (לא \"או אכזריות\", כבספרי הרמב\"ם הנפוצים) ושונא את הבריות ואינו גומל להם חסד חוששין לו ביותר שמא גבעוני הוא\" (וכ\"ה גירסת הטור ושו\"ע<sup data-n=\"566\">32</sup>) — כי אין חוששין לו רק אם אין אצלו אף א' מג' המדות<sup data-n=\"567\">33</sup>],\nוא\"כ, את\"ל שזוהי פלוגתת הבבלי והירושלמי — למה הכריע הרמב\"ם כהירושלמי נגד הבבלי (ובפרט שנקט לשון הבבלי \"סימני ישראל\")?\nולכן מסתבר לומר, שגם הבבלי ס\"ל שהטעם שריחק דוד את הגבעונים הוא מפני ש\"אין בהן (אף) אחד מהן\". ועפ\"ז צע\"ק, מדוע לא מצינו בבבלי הדגשה זו בפירוש כ\"א רק בירושלמי?\nגם יש לדייק בלשון הרמב\"ם הנ\"ל — \"שסימני ישראל. . ביישנין רחמנים כו'\" — ששינה מסדר המדות שבש\"ס (הן בבלי והן ירושלמי)<sup data-n=\"556\">23</sup>, והקדים \"ביישנין\" ל\"רחמנים\"<sup data-n=\"569\">34</sup>. ואף שמצינו גירסא כזו במקום א' במדרש<sup data-n=\"570\">35</sup> — צ\"ע, אמאי לא נקט הרמב\"ם הגירסא הרווחת בש\"ס (ומדרשים)?\nג. ויש לומר הביאור בכל זה:\nנקודת החילוק בין הבבלי והירושלמי היא: בבבלי מדייק \"שלשה סימנים יש",[["559","26","ראה גם אפי זוטרי לשו\"ע אה\"ע שם, ומדייק כן מפרש\"י יבמות שם \"והני גבעונים כיון דלא מרחמי\", ותו לא (אבל ראה לקמן ס\"ו והערה 48). ועוד. ע\"ש."],["560","27","וכן הועתק בב\"ש שם."],["561","28","יד מלאכי כללי שני התלמודים אות יו\"ד."],["562","29","הל' איסורי ביאה פי\"ט הי\"ז."],["563","30","ש\"ב כא, ב."],["562","29","הל' איסורי ביאה פי\"ט הי\"ז."],["565","31","ראה רמב\"ם מהדורת פרענקל שם (ולהעיר מרמב\"ם הל' איסו\"ב פי\"ב הכ\"ד: שראה עזות ואכזריות. ובסוף הל' עבדים: ואין האכזריות והעזות מצוי' כו'). וראה השקו\"ט באפי זוטרי שם גם לפי הגירסא הנפוצה ברמב\"ם \"או אכזריות\". ואכ\"מ."],["566","32","אה\"ע סי' ב ס\"ב."],["567","33","ורק איש שהוא \"עז פנים ביותר\" חוששין לו (רמב\"ם הל' איסו\"ב פי\"ט שם. וכן בטושו\"ע שם). וצע\"ק ברמב\"ם הל' מת\"ע שם ה\"ב \"וכל מי שהוא אכזרי ואינו מרחם יש לחשוש ליחסו\", ולא הזכיר השאר (וראה לקמן הערה 48)."],["556","23","וכן במדרשים שצויינו בהערה 19."],["569","34","וכ\"ה ברמב\"ם בפיהמ\"ש שלו אבות פ\"ה מ\"כ (אלא שי\"ל דשם הקדים ביישנים לפי שקאי על מאמר המשנה שם \"עז פנים לגיהנם\")."],["570","35","דב\"ר שם. ולהעיר שכ\"ה סדרם גם בב\"ש אה\"ע שם. — באלשיך ר\"פ עקב \"שהזכירן על סדר המקראות שהביא מהם ראי'\" [כהגירסא שהראי' על גמ\"ח היא מהכתוב דר\"פ עקב]. וצ\"ע שהרי \"ונתן לך רחמים\" נאמר בפ' ראה והו\"ל להקדים גמ\"ח לרחמים. ובכל אופן מובן שאא\"פ לתרץ כן ברמב\"ם, ובפרט שלא הביא הראיות מהכתובים."]]],[1301410128,"באומה זו\" (ולא \"שלש מדות\"<sup data-n=\"571\">36</sup> וכיו\"ב), והיינו שאין המדובר במעלות מדות אלו כשלעצמן, אלא בכך שהן משמשות כ\"סימנים\" (על ענין אחר); וכיון שכולן הן סימן על דבר אחד, מובן מזה, שכל שלשת המדות נובעות מתכונה אחת מסויימת; משא\"כ בירושלמי אומר \"ג' מתנות טובות נתן הקב\"ה לישראל\", היינו שהמדובר בג' מדות אלו כשלעצמן, וא\"כ י\"ל שכל אחת מעלה לעצמה (דאל\"כ, ה\"ה אחת אלא שמתחלקת לג' מתנות).\nויש לומר, שזהו חילוק גם באופן ההנהגה בג' מדות אלו, שאפ\"ל בשני אופנים (וכפי שרואים בפשטות):\nא) ע\"ד הרגיל, שלש המדות תלויות זו בזו, באופן שמדה אחת מביאה בדרך ממילא את השני', כגון שמי שיש בו בושה ורכות הנפש ה\"ה רחמן, ומצד מדת הרחמים שבו ה\"ה גומל חסד לנצרכים.\nב) לפעמים ג' מדות אלו בלתי תלויות זב\"ז, שגומל חסד להזולת בגלל שרוצה להטיב לו ולא בגלל שמרחם עליו (וכן בהשאר) — כי סו\"ס, בושה, רחמים וחסד ה\"ה שלש מדות שונות זמ\"ז, ולכן תתכן מדה אחת בלי השני'.\nוזהו החילוק בין הבבלי והירושלמי: בירושלמי מדגיש שכל אחת מג' המדות היא מעלה (ומתנה) בפ\"ע, כי המדובר בעצם המדות שכל אחת מחולקת מחברתה; משא\"כ בבבלי הם \"ג' סימנים\" על תכונה אחת, שאז באות המדות (בדרך כלל) כולן יחד בדרך סיבה ומסובב זמ\"ז<sup data-n=\"572\">37</sup>.\nד. וי\"ל שזהו הטעם שהבבלי הביא הכתוב ד\"למען אשר יצוה גו'\" (באברהם) רק בנוגע לגומלי חסדים ולא לענין רחמנים:\nהיחס ד\"גומלי חסדים\" למדות הרחמים והבושה (כשהן באות יחד בדרך סיבה ומסובב) הוא באופן שגמ\"ח היא התוצאה מהרחמים והבושת, כלומר: הכוונה ב\"גומלי חסדים\" אינה לרגש החסד שבלב, אלא למעשה החסד<sup data-n=\"573\">38</sup> שעושה עם רעהו (כפירוש הפשוט ב\"גומלי חסדים\"), שסיבת עשיית חסד היא רגש הרחמים שבלב וטבע הבושה שבנפש (כדלקמן סעיף ה באורך); ולכן אין להביא את הכתוב ד\"למען אשר יצוה את בניו ואת ביתו גו'\" אלא בנוגע לגומלי חסדים (שהוא מעשה החסד כנ\"ל) ולא לענין רחמים ובושה (שהן הרגש שבלב וטבע הנפש<sup data-n=\"574\">39</sup>), כי בפשטות, ציווי אברהם לביתו אחריו הי' שיתנהגו בחסד ורחמים כו' (ולא על הרגש שבלב וטבע שבנפש שאין שייך בזה ציווי)<sup data-n=\"575\">40</sup>.",[["571","36","כהלשון בדב\"ר שם \"ג' מדות טובות (יש ביד ישראל)\". וכן במד\"ש שם (ראה הערה 13)."],["572","37","ראה גם כלי יקר לש\"א שם."],["573","38","ראה גם פי' מהרז\"ו לדב\"ר שם."],["574","39","אף שמובן, ש\"רחמנים וביישנין\" קאי (בעיקר) על הנהגה של רחמים ובושה (וע\"ד מ\"ש הרמב\"ם בגבעונים, ג' פעולות שונות) — ועכצ\"ל כן, כיון שכולם נק' \"סימנים\", ששייך רק על דבר שבגלוי (ולא על דבר שבלב, שאין אדם יודע מה בלבו של חבירו) — מ\"מ, ה\"ז כולל ג\"כ המדות שבלב המביאות לעשיית חסד, כבפנים."],["575","40","וי\"ל שזהו החילוק בין דברי הרמב\"ם בהל' איסו\"ב פי\"ט שם לדבריו בסוף הל' עבדים, שכתב שם \"ואין האכזריות והעזות מצוי' אלא בעכו\"ם כו' אבל זרעו של אברהם אבינו כו' שהשפיע להם הקב\"ה טובת התורה וצוה אותם בחוקים ומשפטים צדיקים רחמנים הם על הכל\" — שמדייק שמדת הרחמנות היא תוצאה מציוויי התורה כו', והיינו משום ששם הכוונה (לא על רגש הרחמים שבלב, אלא) על ההנהגה באופן של רחמים (כמפורט שם לענין ההנהגה עם עבדו), שע\"ז צונו בתורה כו', משא\"כ בהל' איסו\"ב שהכוונה לרגש הרחמים שבלב, לא הזכיר שזה שייך לציווי התורה. וראה בארוכה לקו\"ש חל\"ז בהר (תש\"נ)."]]],[1301410129,"[ואתי שפיר מדוע לא הביא בירושלמי הכתוב ד\"למען אשר יצוה גו'\" לראי' על \"גומלי חסדים\", כי בירושלמי הכוונה בגומלי חסדים היא למדת החסד שבלב, שזה שיש בכל ישראל רגש של חסד בלב אינו מפני ציווי אברהם לבניו וביתו אחריו אלא משום שהקב\"ה נטע כן בלבו של כל איש ישראל, \"ושמר ה\"א לך את הברית ואת החסד\"].\nוע\"פ החילוק הנ\"ל בין הבבלי והירושלמי מובן גם הטעם שדוקא בירושלמי הוזקק לפרש שהגבעונים \"אין בהן אף אחד\", משא\"כ בבבלי ליכא הדגשה זו:\nגם להבבלי לא היו אצל הגבעונים אף \"אחד מהן\", אלא כיון שמדייק שהם \"שלשה סימנים\", דהיינו כנ\"ל שכולן הן תוצאה מנקודה אחת [והחילוק בין ג' הסימנים הוא רק ב\"מקומם\" בנפש האדם, דגומלי חסדים הוא במעשה; רחמנים — הרגש שבלב, ובושה — טבע הנפש], הרי מובן מאליו שהן מציאות אחת שאינה ניתנת להפרד זמ\"ז. דכאשר ישנה נקודה (תכונה) זו, יבואו בדרך ממילא כל שלשת ה\"סימנים\" — המדות (בכל חלקי הנפש), ובאם חסרה — יבוא ההיפך, שהעזות שבו תוליד רגש אכזריות בלב, שזו תגרום שנאת הבריות והעדר עשיית החסד<sup data-n=\"576\">41</sup>. ובמילא אין צורך להדגיש שאצל הגבעונים \"אין בהן (אף) אחד מהן\" כי כולם הן חפצא אחת.\nמשא\"כ בירושלמי שמדבר במדות הללו כפי שכל אחת מהן היא (מעלה ו)מתנה בפ\"ע — אז יש צורך להדגיש שאצל הגבעונים לא היתה אף אחת מהג' מדות, כי יתכן שתמצא אחת בלי השתים.\nה. ע\"פ כל הנ\"ל יש לומר, שזוהי כוונת הרמב\"ם במה ששינה סדרן של המדות והקדים ביישנין לרחמנים — כדי להדגיש, שהמדובר כאן (ב\"סימני ישראל\") בג' המדות כפי שהן באות בדרך סיבה ומסובב זמ\"ז, שאז סדרן הוא — ביישנין רחמנים וגומלי חסדים, וכנ\"ל, שגומלי חסדים היינו מעשה החסד, שסיבתו היא — רגש הרחמים שבלב, והדבר הגורם שהלב יתעורר ברחמים על הזולת הוא עצם טבע הרכות שבנפש — ביישנין.\nוי\"ל שסדר זה נוגע גם לתוכן ענינם של ה\"סימנים\", דאימתי הוי שלש מדות אלו סימנים לישראל, רק כאשר הגמ\"ח היא תוצאה מרחמים, והרחמים הן תולדות הבושה:\nיתכן הענין דגמילות חסדים (לא מצד רחמנות וביישנות, אלא להיפך) מצד ישות וגאווה, כחסד דישמעאל<sup data-n=\"577\">42</sup>, וכמחז\"ל<sup data-n=\"578\">43</sup> שכל צדקה וחסד שאוה\"ע עושין אינן אלא להתגדל בו ולהתייהר בו; ועד\"ז ישנם רחמים הבאים דוקא מצד הגאווה, דכיון שמחשיב עצמו לגדול ומרומם מעם, הרי הוא רואה את הזולת כאיש שפל שיש לרחם עליו<sup data-n=\"579\">44</sup>.\nוזהו שמשמיענו הרמב\"ם, שהסימנים",[["576","41","וכמודגש בגירסת הע\"י \"כל שיש בו שלשה סימנין הללו כו' אין בו שלשה סימנין הללו כו'\" — היינו או שיש בו כולם או שאין בו אף א' [ועפ\"ז אין מהבבלי הכרע להשקו\"ט הנ\"ל (ס\"ב) אם צריכים להרחיק מי שרואים בו בפועל רק ב' או מדה אחת. ואכ\"מ]."],["577","42","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380784\" data-slug=\"likkutei-torah\" data-id=\"4001380784\">לקו\"ת עקב יז, ג</a> ואילך. תו\"ח תולדות ד, רע\"א ואילך. אוה\"ת פרשתנו צג, א ואילך. ועוד."],["578","43","ב\"ב י, ב."],["579","44","ראה סה\"מ תש\"א ע' 37 ואילך — ההפרש בין רחמים מצד הרוממות או מצד ההרגש. ע\"ש."]]],[1301410130,"ל\"האומה הקדושה\" תלויים בזה, שסיבת החסד היא הרחמים, והרחמים מקורם בטבע הבושת והרכות של האדם<sup data-n=\"580\">45</sup>.\nובעומק יותר יש לומר: נת\"ל, ששלש המדות הן \"סימנים\" על נקודה אחת — שהיא נקודת מהותו של איש ישראל, ונקודה זו הוא ענין הביטול, שאינו מציאות לעצמו אלא כל ענינו הוא לשמש את קונו, וכמו שאמר אברהם אבינו<sup data-n=\"581\">46</sup> \"ואנכי עפר ואפר\".\nוזהו שהקדים הרמב\"ם מדת הבושה לפני הרחמנות והחסד — כי רגש הבושה (שמורה על טבע הרכות ושלילת העזות כו') מבטא את נקודת הביטול באופן גלוי, ולכן זהו הסימן הראשון והעיקרי של ישראל, ושלימות הסימן היא כאשר נקודת הביטול חודרת בכל מציאותו, עד שגם הרחמים והחסד שלו אינם מצד הגאוה אלא רק מצד הביטול, \"ואנכי עפר ואפר\"<sup data-n=\"582\">47</sup>.\nו. אלא שעפ\"ז קשה לאידך גיסא — מדוע מקדים בגמ' \"רחמנים\" ל\"ביישנין\"?\nבפשטות י\"ל, כי עיקר העוול של הגבעונים שמשום כך ריחקם דוד המלך הי' האכזריות שלהם, שלא היו רחמנים, והרגו את בני שאול<sup data-n=\"583\">48</sup>.\nאבל יש לומר עוד טעם (ע\"ד המוסר)<sup data-n=\"584\">49</sup> — שבזה שוללת הגמ' רגש של גאוה שיכול לבוא כתוצאה מרחמנות (אמיתית): כאשר האדם מתעורר ברגש של רחמנות אמיתית על הזולת (עד שגומל חסד עמו) — אזי, מצד ההתבוננות במצבו של הזולת, יכול לבוא לידי רגש של ישות, כיון שע\"י התבוננות זו רואה ומכיר את ריחוק הערך של הזולת; ולפיכך, דוקא לאחרי הרחמנות צריך לעורר בעצמו רגש של בושה וביטול.\nובעומק יותר י\"ל — שיש \"בושת\" שהיא תוצאה ובאה בדרך סיבה ומסובב מהרחמנות גופא. והוא ע\"פ המבואר במדרש<sup data-n=\"585\">50</sup> שהטעם שברא הקב\"ה עניים בעולם כי \"חסד ואמת מן ינצרוהו\"<sup data-n=\"586\">51</sup>,",[["580","45","אלא שלא תמיד אפשר להבחין סיבת החסד והרחמים (כי הרגש שבלב וטבע הנפש אינם דבר שבגלוי), ולכן ה\"סימנים\" להלכה הם ההנהגה באופן של בושה רחמים וחסד (כנ\"ל הערה 39). וראה לעיל ס\"ב (ובהערות) השקו\"ט אם מרחקים כשיש רק סימן א'. ואכ\"מ."],["581","46","פרשתנו יח, כז."],["582","47","ראה בארוכה לקו\"ת, תו\"ח ואוה\"ת (צ, סע\"א ואילך) הנ\"ל בענין חסד דאברהם. וראה תניא אגה\"ק ס\"ב."],["583","48","ראה רמב\"ם הל' איסו\"ב פי\"ב הכ\"ד \"שראה עזות ואכזריות. . בעת שבקשו כו' והרגום ולא רחמו עליהם\" (ותו לא), ועד\"ז הוא ברש\"י יבמות שם (כנ\"ל הערה 26). וראה מדרש תהלים מזמור יז \"והגבעונים שלא נקראו בשם יעקב שנאמר בו (מקץ מג, יד) וא-ל שדי יתן לכם רחמים ולא רחמו עליהם עמד דוד וריחקן כו'\" (אף שהביא לפנ\"ז הא ד\"ג' מתנות כו'\"). ועד\"ז בבמדב\"ר שם \"ראה שהיו אכזרים ריחקן\".\nולהעיר מביצה (לב, ב — הובא לעיל ס\"א) \"כל המרחם על הבריות בידוע שהוא מזרעו של א\"א וכל מי שאינו מרחם על הבריות בידוע שאינו מזרעו של א\"א\". וברמב\"ם הל' מת\"ע פ\"י ה\"ב (וראה רמב\"ם הל' תשובה פ\"ב ה\"י) \"וכל מי שהוא אכזרי ואינו מרחם כו' שאין האכזריות מצוי' אלא בעכו\"ם\", ולא הזכיר מדת העזות או שנאת הבריות כו', כבהל' איסו\"ב פי\"ט שם."],["584","49","הטעם ע\"ד החסידות — כי \"הם ג' מדות של האבות מתתא לעילא\" (צוואת הריב\"ש (קה\"ת) סקל\"ט ואו\"ת להה\"מ (קה\"ת) סר\"ס. וראה אלשיך ר\"פ עקב. מגלה עמוקות אופן י\"א בסופו. נתיבות עולם למהר\"ל נתיב הבושה פ\"א. ועוד). ולהעיר מהר\"ת \"גבר\" (מגלה עמוקות שם. של\"ה חלק תושב\"כ פ' שמות (שז, א). ערכי הכינויים (לבעל סה\"ד) מע' גבר. ועוד) — כסדר האבות מלמעלמ\"ט."],["585","50","תנחומא משפטים ט. שמו\"ר פל\"א, ה ובידי משה שם."],["586","51","תהלים סא, ה."]]],[1301410131,"\"אם יהיו כולם עשירים. . מי יוכל לעשות חסד\". ונמצא, שזה שהזולת הוא במצב שזקוק לרחמים הוא רק כדי לזכות את העשיר שיוכל לקיים מצות צדקה<sup data-n=\"587\">52</sup>, כך, שהוא הוא הגורם שחבירו ימצא במצב של צער ולחץ! וכאשר יתבונן היטב בזה, הרי תיכף יתעורר במדה של בושה אמיתית — כי כדי לזכות אותו במצוה של גמ\"ח מצערים חבירו שיהי' במעמד ומצב שיצטרכו לרחם עליו!...\n— שמעתי מכ\"ק מו\"ח אדמו\"ר, שכשהי' בספינה בדרכו מביקורו בארץ הקודש (בשנת תרפ\"ט), והגיעה אליו הידיעה אודות הפרעות שאירעו אז בחברון ר\"ל, נחלה מגודל הצער כו'. בספינה הי' עמו רופא ירא שמים שטיפל בו ברפואות כו' עד שחזר לאיתנו<sup data-n=\"588\">53</sup>. אחרי זמן נכנס הרופא לכ\"ק מו\"ח אדמו\"ר כדי לבקש תיקון, ולשאלת כ\"ק מו\"ח אדמו\"ר על מה ולמה, השיב: דבר ברור הוא, שהרבי, להיותו מנהיג ישראל שרבים צריכים לו, חייב להיות בריא, וא\"כ, אילו לא הייתי בספינה ביחד עם הרבי, שאז לא היתה אפשרות לרפואה בדרך הטבע, לא הי' הרבי נחלה מלכתחילה, ונמצא, שהעובדא שהייתי בספינה גרמה לזה שהרבי יצטער משך זמן, ועל כך (סיים את דבריו) באתי לבקש תיקון...\nוזהו הסדר ד\"רחמנים\" ואח\"כ \"ביישנין\" — דכאשר איש ישראל יש בו ביטול, הרי הרחמים עצמם מולידים אצלו רגש של בושה וביטול אמיתי.\n<span data-k=\"q\">(משיחת ש\"פ ויק\"פ תשמ\"ז) </span>",[["587","52","ראה בארוכה סה\"מ תרכ\"ז ע' שצט. סה\"מ קונטרסים ח\"א קיט, א ואילך."],["588","53","ראה אגרות קודש אדמו\"ר מהוריי\"צ נ\"ע ח\"ב ע' רא."]]],[1301410132,"<h3>שיחה ב</h3>\nא. כתב הרמב\"ם בריש פ\"ב מהל' בית הבחירה: \"המזבח מקומו מכוון ביותר, ואין משנין אותו ממקומו לעולם, שנאמר<sup data-n=\"589\">1</sup> זה מזבח לעולה לישראל, ובמקדש נעקד יצחק אבינו שנאמר<sup data-n=\"590\">2</sup> ולך לך אל ארץ המורי' ונאמר בדברי הימים<sup data-n=\"591\">3</sup> ויחל שלמה לבנות את בית ה' בירושלים בהר המורי' אשר נראה לדויד אביהו אשר הכין במקום דויד בגורן ארנן היבוסי\"<sup data-n=\"592\">4</sup>. ובהלכה שלאח\"ז: \"ומסורת ביד הכל שהמקום שבנה בו דוד ושלמה המזבח בגורן ארונה הוא המקום שבנה בו אברהם המזבח ועקד עליו יצחק והוא המקום שבנה בו נח וכו'\".\nוכתב היעב\"ץ<sup data-n=\"593\">5</sup>, שזה שבהלכה א' נקט הרמב\"ם \"ובמקדש<sup data-n=\"594\">6</sup> נעקד כו'\" ובה\"ב כ' \"שהמקום שבנה בו. . המזבח. . הוא המקום שבנה בו אברהם המזבח כו'\", הוא משום \"שתחלה ביאר (הרמב\"ם) שהכתוב מוכיח שבמקדש היתה העקידה, ואח\"כ הוסיף לבאר שדבר זה מסורת הוא שבמקום המזבח בנה אברהם מזבח ועקד כו' אמנם הוא דבר מקובל בלי הכרח מהכתובים\" (כי מהכתוב מוכח רק שהעקידה היתה במקום המקדש בכלל (בהר המורי')).\nולפ\"ז, המקור שמביא הרמב\"ם לענין זה (ש\"המזבח מקומו מכוון ביותר\" להיותו מקום העקידה) הוא, מן הכלל אל הפרט: בתחילה (בה\"א) מביא ראי' (מהכתובים) שבמקום המקדש היתה עקידת יצחק, ואח\"כ מוסיף להוכיח שמקום המזבח (במקדש גופא) הוא מקומה של עקידת יצחק (ע\"פ ה\"מסורת ביד הכל\").\nויש להבין מדוע כתב הרמב\"ם את הראי' לפרט הב' (\"מסורת ביד הכל\") בהלכה בפ\"ע<sup data-n=\"595\">7</sup>, מכיון שזהו סיום ופירוט הראי' (שבהלכה א')<sup data-n=\"596\">8</sup>?\nונוסף לזה: כיון שהרמב\"ם כאן בא ללמדנו רק ע\"ד מקומו המכוון והמדוייק של המזבח, כלשונו בתחלת ההלכה \"המזבח מקומו מכוון ביותר ואין משנין",[["589","1","דה\"א כב, א."],["590","2","פרשתנו כב, ב."],["591","3","דה\"ב ג, א."],["592","4","ברמב\"ם דפוס רומי ר\"מ (וקושטא רס\"ט) ישנם כמה שינויים בהלכה זו. ואולי הלשון שם משובש (בט\"ס). ואכ\"מ."],["593","5","חידושים וביאורים להיעב\"ץ להל' בית הבחירה כאן."],["594","6","ולא כ\"המגי' (ש)הגי' (נדפס על גליוני הרמב\"ם שבדפוס) שצ\"ל ובמקום המזבח נעקד יצחק. . (כי) לא הבין כלל לשון הר\"מ ז\"ל שלשונו מדוקדק מאד\" (יעב\"ץ שם).\nולהעיר שלכאורה יש מקום להגי' (ולהוסיף תיבת \"ובמקום\") \"ובמקום המקדש\", שהרי בזמן העקידה לא הי' \"מקדש\" עדיין."],["595","7","דחלוקת ההלכות נעשתה ע\"י הרמב\"ם עצמו (הקדמת הרמב\"ם לס' היד בסופו. וכ\"כ בהקדמתו לסהמ\"צ). וראה הל' ת\"ת לאדה\"ז פ\"א קו\"א סק\"א (בהוצאת קה\"ת — ג, א [תתכז, א]) ובכ\"מ ע\"ד דיוק פיסוק ההלכות ברמב\"ם."],["596","8","ולכאורה גם לפי ההגהה (הנ\"ל הערה 6) \"ובמקום כו' נעקד יצחק\", י\"ל שאין הכוונה שבהלכה זו מוכיח הרמב\"ם שבמקומו המדוייק של המזבח נעקד יצחק, אלא שזוהי הקדמה כללית, וממשיך להוכיח מהכלל אל הפרט: בתחלה מוכיח (מהכתובים) שמקומו הכללי הוא בהר המורי', ובהלכה ב' (ע\"פ המסורה \"ביד הכל\") ע\"ד מקומו הפרטי. וא\"כ גם לפ\"ז צריך ביאור, דהול\"ל ב' הענינים בהלכה אחת. וראה לקמן הערה 22."]]],[1301410133,"אותו ממקומו לעולם\", למה הביא בכלל כללות הענין (\"ובמקדש נעקד יצחק אבינו שנאמר. . ונאמר כו'\"), ולא כתב (בקיצור) רק ע\"ד המקום בדיוק, ש\"מסורת ביד הכל שהמקום שבנה בו דוד ושלמה המזבח כו' הוא המקום שבנה בו אברהם המזבח ועקד עליו יצחק\".\nב. גם יש להעיר על כמה דיוקים ושינויים בדברי הרמב\"ם כאן:\nא) בה\"א כותב \"ובמקדש נעקד יצחק\", ובהלכה ב' מאריך — \"שבנה בו אברהם המזבח ועקד עליו יצחק\", ולכאורה הול\"ל (גם) כאן \"הוא המקום שנעקד עליו יצחק\" — ומדוע מוסיף בה\"ב שאברהם בנה בו מזבח<sup data-n=\"597\">9</sup>? ובפרט שאין הרמב\"ם מסתפק בתיבות ש\"בנה בו אברהם המזבח\", אלא מוסיף \"ועקד עליו יצחק\"<sup data-n=\"598\">10</sup> (דלא כבהמשך ההלכה \"והוא המקום שבנה בו נח כשיצא מן התיבה\", ואינו מוסיף \"והקריב עליו קרבן\")<sup data-n=\"599\">11</sup>.\nב) בה\"א כ' \"במקדש נעקד יצחק אבינו\", ובה\"ב סתם \"שבנה בו אברהם. . יצחק\". ואף שבנוגע ליצחק י\"ל שאין צורך לכתוב עוה\"פ תיבת \"אבינו\", אבל צע\"ק מדוע סתם באברהם.\nגם צע\"ק כוונת הרמב\"ם בהמשך דבריו בה\"ב: \"והוא המקום שבנה בו נח כו' והוא המזבח שהקריב עליו קין והבל ובו הקריב אדם הראשון כו'\" — מאי בדיוק נוגע זה לקדושת המקדש והמזבח שבו<sup data-n=\"600\">12</sup>?\nההודעה שהמקום שבנה בו דוד ושלמה המזבח הוא המקום שבנה אברהם כו' מובנת, כי המקום שבו נעקד יצחק אבינו ראוי ורצוי שבו תשרה שכינה ובו יקריבו בנ\"י (בניו של יצחק) קרבנות (\"מזבח לעולה לישראל\") — כמפורש בכתוב<sup data-n=\"601\">13</sup> \"ויקרא אברהם שם המקום ההוא ה' יראה אשר יאמר היום בהר ה' יראה\", וכתרגום אונקלוס עה\"פ שאברהם הת",[["597","9","ודוחק לומר שכ\"כ רק משום שיפור הסגנון בלשון מקביל, שהמקום שבנה בו דוד ושלמה המזבח הוא המקום שבנה בו אברהם."],["598","10","בזה י\"ל לכאורה שהוסיפו הרמב\"ם כדי לשלול שאר מזבחות דאברהם (המפורשים בפ' לך יב, ז. שם, ח. יג, יח), ולהדגיש שכאן הכוונה היא למזבח העקידה. אבל בפשטות זה מובן כבר מהלשון \"המזבח\", ובפרט שזה בא בהמשך להלכה א'."],["599","11","להעיר שבפרקי דר\"א (פל\"א), מקורו דהרמב\"ם (כס\"מ כאן), הלשון שוה בכולם — ש\"הראהו הקב\"ה (מקום עקידת יצחק) לאברהם וא\"ל זה הוא המזבח, הוא המזבח שהי' אדם הראשון מקריב כו' הוא המזבח שהקריבו בו קין והבל הוא המזבח שהקריבו בו נח ובניו\"."],["600","12","לכאורה הי' אפ\"ל, שבזה בא הרמב\"ם לתרץ (וראה תוד\"ה כל מקום — ע\"ז מה, א (מירושלמי ע\"ז פ\"ג סה\"ה)) איך הותר לבנות שם המקדש והמזבח — והרי איתא במשנה (ע\"ז שם. וראה גם ירושלמי שם) \"כל מקום שאתה מוצא הר גבוה וגבעה נשאה ועץ רענן דע שיש שם עבודת כוכבים\"?\nוע\"ז מתרץ הרמב\"ם, דמכיון שמסורת ביד הכל שבמקום זה בנה אברהם מזבח ועקד עליו יצחק, הי' זה מקום חשוב אצל בני עשו (בנו של יצחק) ובני ישמעאל (בנו של אברהם), והיות דשם בנה גם נח וכן קין והבל ואדם הראשון מזבחות, החשיבו והעריצו אותו כל אוה\"ע, ולכן שום אומה לא השתמשה במקום הזה לעבוד שם ע\"ז (ולכן גם לא הביא הא דיעקב, כי אי\"ז נוגע לאוה\"ע); דלפי תחלת טעות דור אנוש שהאמינו בשיתוף (ראה רמב\"ם ריש הל' ע\"ז), י\"ל שהבינו שמקום זה שייך לאלקי האלקים כו', והדורות שלאח\"ז, אף שעבדו ע\"ז ממש (כדברי הרמב\"ם שם) המשיכו בדרך זו, שלא השתמשו בהר זה.\nאבל לכאורה דוחק לתרץ כן — וראה שו\"ת חת\"ס או\"ח סר\"ח (ד\"ה בדף ד' ע\"ג); מעשי למלך לרמב\"ם כאן וברפ\"ה מהל' ביהב\"ח. ולהעיר ממו\"נ ח\"ג רפמ\"ה דמשמע שם ש(בנ\"י ו)אוה\"ע לא ידעו ע\"ד מקום זה שיהי' מקום המקדש. ואכ\"מ."],["601","13","פרשתנו כב, יד."]]],[1301410134,"פלל \"הכא יהון פלחן דריא\", וברש\"י<sup data-n=\"602\">14</sup> \"ה' יבחר. . את המקום הזה להשרות בו שכינתו ולהקריב כאן קרבנות\". אבל זה ש\"הוא המקום שבנה בו נח כו' והוא המזבח שהקריב עליו קין כו' ובו הקריב אדם הראשון קרבן כשנברא ומשם נברא\" — מאי שייך לענין \"זה מזבח לעולה לישראל\"<sup data-n=\"603\">15</sup>?\nואם כוונתו להדגיש שייכות המקום למזבח ע\"י ריבוי המזבחות שנבנו במקום זה — הי' צריך להביא גם שיעקב אבינו בנה מזבח במקום זה (בהר המורי'), כמרז\"ל<sup data-n=\"604\">16</sup> \"לא כאברהם שכתוב בו הר. . ולא כיצחק שכתוב בו שדה. . אלא כיעקב שקראו בית\"<sup data-n=\"605\">17</sup>, שמזה מוכח שגם יעקב בנה בו<sup data-n=\"606\">18</sup> מזבח<sup data-n=\"607\">19</sup>.\nג. ויש לומר הביאור בזה:\nבאריכות לשונו של הרמב\"ם ע\"ד מקום המזבח, שהוא מקום עקידת יצחק וכו' [אף שאין דרכו של הרמב\"ם להביא (בכ\"מ) טעמי ההלכות, ומה גם האריכות ע\"ד המזבחות שנבנו במקום המזבח, שלכאורה אינם אלא דברי אגדה], וחלוקת הענין לשתי הלכות — כוונת הרמב\"ם להשמיענו שני גדרים שישנם בדין מקומו המכוון של המזבח:\n(א) שמקומו של המזבח הוא (מכוון בזה שהוא) בהר המורי' — היינו לא (רק) משום שהמזבח הוא בכלל הבית (המקדש) שאין לבנותו כ\"א \"בירושלים בלבד ובהר המורי'\" (כמ\"ש הרמב\"ם לעיל<sup data-n=\"608\">20</sup>), אלא שזהו דין מיוחד במזבח מצ\"ע: מקומו הוא דוקא בהר המורי'.\nושייכותו של המזבח להר המורי' (בכלל) מסביר ומטעים הרמב\"ם בהל' א, מהכתובים, ש\"במקדש נעקד יצחק אבינו שנאמר ולך לך אל ארץ המורי' ונאמר. . ויחל שלמה. . בהר המורי' וגו'\" — היינו דלהיות שבהר המורי' היתה עקידת יצחק, לכן הוא הוא מקומו של המזבח<sup data-n=\"609\">21</sup> (ושל \"בית ה'\" בכלל)<sup data-n=\"610\">22</sup>.",[["602","14","עה\"פ. וראה תרגום ירושלמי ומדרשי רז\"ל (ב\"ר פנ\"ו, י. ועוד) עה\"פ."],["603","15","להעיר משו\"ת חת\"ס יו\"ד סרל\"ה: מ\"ש הדר\"ג שכבר נתקדש המקום ע\"י אדה\"ר ונח לא נמצא כן אלא שבנו מזבח והקריבו שם אבל שקדשו המקום לא שמענו רק באאע\"ה שאמר אשר יאמר לדורות הבאים בהר ה' יראה כו'."],["604","16","פסחים פח, א."],["605","17","וראה קרית ספר להמבי\"ט הל' ביהב\"ח פ\"ה דקדושת הר מאברהם, קדושת עזרה מיצחק, וקדושת בית עצמו מיעקב."],["606","18","ראה גם פדר\"א פל\"ה: לקח יעקב י\"ב אבנים מאבני המזבח שנעקד עליו יצחק כו' (ע\"ש בההמשך). וראה פרש\"י ומדרשים עה\"פ ויצא כח, יז. פנים יפות ר\"פ ויצא."],["607","19","ראה ויצא כח, יזיח. וישלח לה, ז: ויבן שם מזבח גו'. וראה בכל הנ\"ל מעשי למלך כאן אות ח ואילך."],["608","20","בהל' ביהב\"ח — פ\"א ה\"ג."],["609","21","וזה שלא כתב הרמב\"ם בפירוש בסגנון של הלכה, שיש דין וחיוב במזבח שיהי' בהר המורי' — י\"ל בפשטות [נוסף לזה שאין דרכו לחדש דינים שלא נתפרשו בגמ' ורק לרמזם<sup data-n=\"e12\">*</sup>], כי לאחר שנבנה המקדש והמזבח במקומה אין בזה נפק\"מ בפועל, כיון שהמזבח \"מקומו מכוון ביותר\" אפילו בהר המורי' גופא. ואולי י\"ל, שמבואר הוא בזה שהביא לעיל שם (פ\"א ה\"ג), לענין \"אין שם בית לדורי הדורות אלא בירושלים בלבד ובהר המורי'\" — הכתוב \"ויאמר דויד זה הוא בית ה' האלקים\", ומוסיף \"וזה מזבח לעולה לישראל\", ודוחק (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161479\" data-slug=\"likkutei-sichot\" data-id=\"1300161479\">לקו\"ש חט\"ז ע' 466</a> הערה 12, הפי' בהוספה זו. וראה לקמן בפנים ס\"ד). וראה הערה הבאה."],["610","22","וי\"ל, דאף שבהלכה זו אין הרמב\"ם מפרט בנוגע למקום המזבח, רמזו בזה שהעתיק המשך הכתוב \"אשר נראה לדויד אביהו אשר הכין במקום דויד בגורן ארנן היבוסי\" (דלכאורה מיותר, דהרי הראי' שהוא במקום המקדש מפורשת כבר בתחלת הכתוב \"ויחל שלמה לבנות את בית ה' בירושלים בהר המורי'\", אלא) דהמקום \"אשר נראה לדויד אביהו\" הוא המקום ש\"ויבן שם דוד מזבח לה' וגו' ויענהו באש מן השמים על מזבח העולה\" (דה\"א כא, כו), והוא הוא \"במקום דויד בגורן ארנן היבוסי\" שהי' מקום המזבח, ולא כל ההר — ראה רלב\"ג ורד\"ק ש\"ב כד, כד. רד\"ק דה\"א שם, כה.\nוראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191142\" data-slug=\"likkutei-sichot\" data-id=\"1300191142\">לקו\"ש חי\"ט ע' 142</a> ואילך — ביאור באופן אחר בהנ\"ל, וכן בכללות ביאור ב' הלכות אלו ברמב\"ם."],["e12","*","ראה קו\"א שבהערה 7. וש\"נ."]]],[1301410135,"ועוד זאת<sup data-n=\"611\">23</sup> (ב) שמקומו של המזבח בהר המורי' גופא הוא \"מכוון ביותר ואין משנין אותו ממקומו לעולם\". ודבר זה הוא דין נוסף במזבח שלא נאמר בכללות הבית, שלא מצינו שהבית צ\"ל מקומו מכוון בהר המורי' גופא<sup data-n=\"612\">24</sup> [אלא שע\"י דין זה דמזבח, הוקבע בדרך ממילא מקומו של כל הבית בהר המורי' — כפי שיעורן של מדות הבית בקשר למקום המזבח<sup data-n=\"613\">*24</sup>].\nודין זה מסביר הרמב\"ם בהל' ב: \"ומסורת ביד הכל שהמקום שבנה בו דוד ושלמה המזבח כו' הוא המקום שבנה בו אברהם המזבח כו' והוא המקום שבנה בו נח כו'\", דהיינו מקומו המדוייק של המזבח בהר המורי' גופא (כנ\"ל סעיף א).\nד. ואף ששני הדינים (גם הדין הא' — שמקום המזבח הוא בהר המורי') הם דינים מיוחדים במזבח, כנ\"ל — מ\"מ כ' הרמב\"ם בדין הא' \"ובמקדש נעקד יצחק\", ולא \"ובהר המורי' נעקד יצחק\".\nויש לבאר טעם הדבר, כי דין זה במזבח (שמקומו בהר המורי'), הוא מצד היותו עיקרו של בית המקדש<sup data-n=\"614\">25</sup>, וכמ\"ש הרמב\"ם<sup data-n=\"615\">26</sup> דהמ\"ע ד\"ועשו לי מקדש\"<sup data-n=\"616\">27</sup> היא \"לעשות בית לה' מוכן להיות מקריבים בו הקרבנות\".\nועפ\"ז מבואר זה שהביא הרמב\"ם ש\"במקדש נעקד יצחק\" בהמשך לדין דמקום המזבח, ולא לעיל<sup data-n=\"608\">20</sup> גבי הדין דמקום המקדש, שכ' שם: \"אין שם בית לדורי הדורות אלא בירושלים בלבד ובהר המורי'\" [שלכאורה הי' מתאים שם להמשיך (ע\"ד לשונו כאן) \"ובמקדש נעקד יצחק אבינו שנאמר ולך לך אל ארץ המורי' ונאמר בדה\"י ויחל שלמה לבנות את בית ה' בירושלים בהר המורי' אשר נראה לדויד אביהו אשר הכין במקום דויד גו'\"] —\nכי קביעת מקומו של המקדש בהר המורי' להיותו מקום עקידת יצחק,",[["611","23","ובדוגמת שני הפרטים (דינים) שבמקדש (כדיוק לשון הרמב\"ם לעיל פ\"א שם): (א) \"בירושלים בלבד\", (ב) \"ובהר המורי'\" [דמזה שכתב \"בירושלים בלבד ובהר המורי'\", ולא \"בהר המורי' שבירושלים\", מובן, שהם שני דינים]. וראה מכילתא בתחלתה: עד שלא נבחרה ירושלים כו' עד שלא נבחר בית עולמים היתה ירושלים ראוי' לשכינה משנבחר בית עולמים יצאת ירושלים."],["612","24","ואף ש\"הכל בכתב מיד ה' עלי השכיל\" (דה\"א כח, יט — הובא בהקדמת הרמב\"ם לפיהמ\"ש בנוגע למס' מדות) — הרי כבר שקו\"ט אם הוא לעיכובא (ראה ספר ראבי\"ה חולין (אה\"ק, תשל\"ו) סימן אלף וק\"מ. ועוד). ואכ\"מ."],["613","*24","אבל במק\"א נת' שאינו מוכרח, כי י\"ל דשיעורין של מדות אלו אינם לעיכובא, ויכולים להשתנות ממקדש למקדש (ע\"ד מ\"ש הרמב\"ם לעיל פ\"א ה\"ד. וראה לקמן פ\"ב הי\"ז בנוגע המזבח עצמו, שמדותיו אינן מעכבין. וראה הערה שלפנ\"ז)."],["614","25","ראה מנ\"ח מצוה צה, דבלא מזבח \"אינו קרוי בית המקדש כי עיקר המקדש להקריב קרבנות\". וראה מאירי כתובות קו, ב (בסופו): ומזבח העולה וההיכל והעזרות וכל מה שהוא צורך הבית כו'."],["615","26","ריש הל' ביהב\"ח. וראה גם סהמ\"צ שלו מ\"ע כ ובשורש יב."],["616","27","תרומה כה, ח."],["608","20","בהל' ביהב\"ח — פ\"א ה\"ג."]]],[1301410136,"שייכת (בעיקר) לדין מקום המזבח: מכיון ששם היתה עקידת יצחק (שהי' גדר קרבן), לכן נקבע מקום זה ל\"בית ה'\" שענינו \"להיות מקריבים בו הקרבנות\". ונמצא דזה שמקום המקדש בכלל ה\"ה בהר המורי', הוא משום שהמזבח (מקום עבודת הקרבנות שהוא ענין העיקרי במקדש) מקומו בהר המורי', ולכן הביאו הרמב\"ם כאן גבי מזבח דוקא.\nאמנם בהלכה ב' לא כתב הרמב\"ם \"ובמקדש כו'\" אלא \"המקום שבנה בו כו' המזבח\" — כי בהלכה זו קאי בדינו של המזבח עצמו (לא בתור עיקר המקדש).\nונמצא דשתי ההלכות במקום המזבח (מקומו בהר המורי', ומקומו ה\"מכוון ביותר\" בהר המורי' גופא, במקום העקידה), חלוקות בעצם: א) מקומו (הכללי) בהר המורי' — הוא מפני היותו עיקרו של המקדש, ב) מקומו ה\"מכוון ביותר\" בהר המורי' עצמו, הוא מפני היותו — מזבח, מבלי שייכות לכללות הבית.\nוזהו טעם השינויים והחילוק בין הראיות שהרמב\"ם מביא בההלכות:\nהדין הא' במקום המזבח, שהוא מצד היותו עיקר המקדש, יסודו (אך ורק) במעשה העקידה, \"במקדש נעקד יצחק אבינו\" — כי ענין המקדש שייך לישראל דוקא;\nמשא\"כ בדין השני אין הרמב\"ם מסתפק בזה ש\"הוא המקום שבנה בו אברהם המזבח כו'\" אלא מוסיף \"והוא המקום שבנה בו נח כו' קין והבל כו' אדם הראשון כו' כשנברא\" — כי בזה משמיענו, שייחודו של מקום זה כמקום \"מכוון ביותר\" למזבח (בכלל, לא רק כמזבח שבמקדש), אינו שייך רק לישראל, אלא כן הי' מאז ומקדם (גם לפני האבות), שהוא מקום מיוחד בעצם לבניית מזבח.\nולא עוד אלא שממשיך ומבאר מעלתו של מקום זה — \"ומשם נברא אמרו חכמים אדם ממקום כפרתו נברא\" — שזה שהמקום \"מכוון ביותר\" (למזבח) אינו (רק) תוצאה מהקרבת הקרבנות שם דכל הנ\"ל עד אדם הראשון, אלא שכן הוא מצד הקביעות ע\"י הקב\"ה, שמקום זה הוקבע להקרבת קרבנות מתחלת הבריאה.\nה. ע\"פ הנ\"ל מדוייק מה שבהלכה זו לא כתב הרמב\"ם \"אברהם אבינו. . יצחק אבינו\" — כי מקום המזבח כגדר בפ\"ע אינו ענין רק לישראל אלא נוגע לכל האומות.\nועפ\"ז מובנת הדגשת הרמב\"ם בתחילת הלכה זו \"ומסורת ביד הכל\", כי בפשטות משמעה שמסורת זו היא לא רק ביד ישראל אלא (\"ביד הכל\") גם ביד האומות — כי גדר זה של מקום המזבח שייך גם להם.\nויש לומר, שזהו הטעם שמקריבים קרבנות של נכרים ע\"ג המזבח<sup data-n=\"618\">28</sup>, שאין זה מצד (כללות) בית המקדש (השייך רק לבנ\"י<sup data-n=\"619\">29</sup>), אלא מצד (מקום) המזבח בפ\"ע, השייך גם להם, כנ\"ל<sup data-n=\"620\">30</sup>.",[["618","28","\"איש איש לרבות העו\"כ שנודרים נדרים ונדבות כישראל\" (מנחות עג, ב. וש\"נ. וראה רמב\"ם הל' מעשה הקרבנות פ\"ג ה\"ב. הל' מלכים פ\"י ה\"י). וראה רמב\"ם סוף הל' מעשה הקרבנות. וראה הערה 30."],["619","29","וכמ\"ש (תרומה שם) ועשו לי מקדש ושכנתי בתוכם. ונאמר (עזרא ד, ג) \"לא לכם ולנו לבנות בית לאלקינו\". וראה רמב\"ם הל' שקלים פ\"ד ה\"ח. הל' ערכין וחרמין פ\"א הי\"א. הל' מתנות עניים פ\"ח ה\"ח."],["620","30","עפ\"ז יש לבאר פסק הרמב\"ם (סוף הל' מעשה הקרבנות) השוחט קדשי נכרים בחוץ חייב (כדעת ר\"י במשנה זבחים — מה, א), אף שבנוגע לשאר הדינים בקדשי עכו\"ם פסק (הל' פסולי המוקדשין ספי\"ח) ד\"אין חייבין עליהם משום פגול נותר וטמא\" (כדעת ר\"ש במשנה שם) — וראה נ\"כ הרמב\"ם בהל' פסוה\"מ שם; מפרשי המשנה והגמ' זבחים שם — כי פגול נותר וטמא הם דינים בהקרבן והקרבתו, ולכן חלים רק על קרבן של ישראל; משא\"כ האיסור דשחוטי חוץ שייך למקום המזבח, השייך גם לב\"נ, כבפנים.\nוראה קרית ספר להמבי\"ט סוף הל' מעה\"ק: השוחט קדשי עכו\"ם בחוץ חייב כיון דנודרים נדרים ונדבות כישראל דכתיב איש איש לרבות את העכו\"ם שהם כישראל להביא קרבנות. וראה משנה למלך הל' מלכים פ\"י ה\"ז (ד\"ה ודע שמה שתירצו) שמחלק (ע\"פ תוד\"ה מנין — ע\"ז ה, ב) בין קרבנות ב\"נ שנודרים לה' להקריב בבית המקדש, שבזה י\"ל שמחוייבים לקיים נדרם ואית בהו משום בל יחל, למה שנודרים להקריב בבמה. ע\"ש. ולהעיר מר\"ש משאנץ לתו\"כ אחרי (יז, ג) \"ואין הנכרים חייבין (בשחוטי חוץ) כו' אע\"ג דנודרים נדרים ונדבות כישראל\"."]]],[1301410137,"ו. עפ\"ז יש לבאר עוד דיוק ושינוי בלשון הרמב\"ם, שבה\"א כ' \"ובמקדש נעקד יצחק\", שמדגיש את (א) הנפעל (ב) ביצחק, ואילו בה\"ב כותב \"הוא המקום שבנה בו אברהם המזבח ועקד עליו יצחק\", שמדגיש את (א) הפעולה, (ב) אברהם<sup data-n=\"621\">31</sup>:\nזה שמקום ה\"מקדש\" הוקבע בזמן אברהם, אינו רק מחמת תפלת אברהם \"ויקרא גו' בהר ה' יראה\", אלא גם (ואולי בעיקר) מפני שע\"י עקידת יצחק, שהובא כקרבן ונתקדש בקדושת עולה, נתקדש מקום העקידה (הר המורי')<sup data-n=\"622\">32</sup> והוכשר עי\"ז להיות \"בית לה'\" ש\"מקריבים בו הקרבנות\" — וזהו מ\"ש הרמב\"ם \"ובמקדש נעקד יצחק\".\nמשא\"כ מקומו המכוון ביותר של המזבח, מצד המזבח עצמו, אינו תוצאה ממעשה העקידה, אלא הוא להיותו מקום ראוי וקבוע להקרבת קרבנות (מתחילת הבריאה), וכוונת הרמב\"ם בכתבו \"הוא המקום שבנה בו אברהם המזבח ועקד עליו יצחק\" היא רק להביא ראי' על סגולת המקום. ולכן מדגיש פעולת אברהם — דזה שבנה שם מזבח ועקד עליו יצחק הוא ראי' שמקום זה הי' מוכשר (לפני כן) למזבח וקרבן<sup data-n=\"623\">33</sup>.\nויש להוסיף, שהבאת יצחק על \"אחד ההרים\" (הר המורי' בכלל) היתה ע\"פ ציווי השם (כמו שהביא הרמב\"ם כאן \"שנאמר ולך לך אל ארץ המורי'\"), משא\"כ מקומה המכוון של העקידה לא כ' הרמב\"ם שהי' ע\"פ ציווי<sup data-n=\"624\">34</sup>, ועפ\"ז יומתק חילוק הנ\"ל שע\"י עקידת יצחק נתקדש כללות ההר (להיות מקום המקדש והמזבח), אבל לא המקום המכוון ביותר — כי רק זה הי' ע\"פ ציווי השם.\nז. שני ענינים אלו שבמקום המזבח — מקומו הכללי של המזבח בהר המורי' ומקומו המכוון ביותר, ושייכותם לשני הענינים שבמעשה העקידה (\"במקדש נעקד יצחק\", \"בנה בו אברהם המזבח ועקד עליו יצחק\") — יש לבאר בעומק יותר, ע\"פ מ\"ש הרמב\"ם בספרו מו\"נ<sup data-n=\"625\">35</sup> — שתכליתו של נסיון העקידה היתה לפרסם בעולם שני ענינים גדולים מיסודות התורה:\n(א) \"להודיע אותנו גבול אהבת השם ויראתו עד היכן היא מגעת\",\n(ב) \"להודיע אותנו איך יאמינו הנביאים באמת מה שיבואם מאת השם",[["621","31","וכן זה שבהלכה א' אינו מדבר ע\"ד בנין המזבח (דאברהם), משא\"כ בהלכה ב' מדגיש \"בנה בו. . המזבח\", שעיקרו דין במזבח, כבפנים."],["622","32","ראה שו\"ת חת\"ס שבהערה 15."],["623","33","ראה בביאור דברי הרמב\"ם בהלכות אלו — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191142\" data-slug=\"likkutei-sichot\" data-id=\"1300191142\">לקו\"ש חי\"ט ע' 142</a> ואילך."],["624","34","ולהעיר שהרמב\"ם כאן לא הדגיש כמ\"ש בפדר\"א שם (הנ\"ל הערה 11): כיון שהגיעו לאותו מקום הראהו הקב\"ה לאברהם ואמר לו זה הוא המזבח."],["625","35","ח\"ג פכ\"ד."]]],[1301410138,"בנבואה. . שכל מה שיראה הנביא במראה הנבואה הוא אמת ויציב אצל הנביא לא יסופק בדבר ממנו. . והראי' על זה הסכים אברהם לשחוט בנו יחידו אשר אהב כמו שצווה ואע\"פ שהיתה המצוה ההיא בחלום או במראה. . ולא הי' מוצא בנפשו לעשות זה המעשה הגדול מספק כו'\".\nויש לומר, שמשני ענינים אלו שנתפרסמו בעולם ע\"י מעשה העקידה באים שני הענינים שבבית המקדש (שנבנה במקום העקידה):\nענין אהבת ה' ויראתו שנתגלה ע\"י העקידה, הביא לידי זה, שעיקר הענין דעבודת ה' (שזהו ע\"י מעשה הקרבנות) הוא במקום זה דוקא; ופירסום וגילוי ההתאמתות בתכלית של מראה ה' הבא בנבואה, הביא זה שעל מקום זה יתפלל שיהי' מקום גילוי שכינה, \"ה' יראה. . בהר ה' יראה\" — \"בהר זה יראה הקב\"ה לעמו\"<sup data-n=\"626\">36</sup>.\n[וי\"ל שהם הם שני הענינים שכתב הרמב\"ם בריש הל' בית הבחירה \"בית לה' מוכן להיות מקריבים בו הקרבנות וחוגגין אליו שלש פעמים בשנה\" — ד\"מקריבים בו הקרבנות\" הו\"ע העבודה; \"וחוגגין אליו שלש פעמים בשנה\" הו\"ע הראי', \"שלש<sup data-n=\"627\">37</sup> פעמים בשנה יראה כל זכורך אל פני האדון ה'\"<sup data-n=\"628\">38</sup>].\nוכיון שהמזבח הוא עיקרו של המקדש (כנ\"ל) — לכן גם במזבח עצמו ישנם שני ענינים אלו: (א) קרבנות הו\"ע העבודה (כנ\"ל) מצד מקריבי הקרבן, (ב) ע\"י עבודת הקרבנות של אהרן ובניו נעשית השראת השכינה בביהמ\"ק ובבית קדה\"ק<sup data-n=\"629\">39</sup> [כמשנ\"ת במק\"א<sup data-n=\"630\">40</sup> בפירוש הודאת הסנהדרין<sup data-n=\"631\">41</sup> \"ברוך הוא שבחר באהרן ובבניו לעמוד לשרת לפני ה' בבית קדשי הקדשים\", ששבח זה הוא על המעלה שבעבודת אהרן ובניו, שמביאה השראת השכינה בקדה\"ק].\nויש לומר, שזהו החילוק בין שתי ההלכות הנ\"ל בדין מקומו של המזבח: ההלכה הראשונה אודות מקום המזבח בהר המורי' להיותו עיקרו של המקדש, שייכת לפעולת המזבח בכללות המקדש, דהיינו השראת השכינה שבו; ואילו ההלכה השני', שהוא דין במקום המזבח מצד המזבח עצמו (כנ\"ל בארוכה) — שייכת לתוכן ענין המזבח בפ\"ע, דהיינו ענין העבודה (מעשה הקרבנות).\nח. ועפ\"ז יש להוסיף ביאור בשתי ההלכות ברמב\"ם כאן אודות מקום המזבח, ושייכותן ליצחק ולאברהם:\nשני ענינים הנ\"ל שנקבעו במקום המזבח ע\"י מעשה העקידה — (א) ענין העבודה, (ב) השראת השכינה — שייכים,",[["626","36","ל' רש\"י פרשתנו עה\"פ כב, יד."],["627","37","משפטים כג, יז. תשא לד, כג (וראה גם שם, כד). ראה טז, טז."],["628","38","להעיר מחגיגה ב, א (וש\"נ) כדרך שבא לראות כך בא ליראות. וביד רמ\"ה סנהדדין ד, ב שנלמד מהכתוב ד\"יראה. . יראה\" שבפרשתנו הנ\"ל. וראה כלי יקר עה\"פ. ובארוכה אוה\"ת פרשתנו קב, ב ואילך."],["629","39","וי\"ל שכן הוא בנוגע לתפלות (שבמקום קרבנות תקנום), שבחיוב נוכח המקדש בתפלה (רמב\"ם הל' תפלה פ\"א ה\"ג. פ\"ה ה\"ג) יש ב' דינים (ראה כס\"מ (בב' המקומות ברמב\"ם שם)): מצד הדין ד\"עבדהו במקדשו\" — מקום קרבנות, ומצד זה דשם מקום שכינה ד\"זה שער השמים\" (ויצא כח, יז ובפרש\"י שם). ואכ\"מ."],["630","40","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111131\" data-slug=\"likkutei-sichot\" data-id=\"1300111131\">לקו\"ש חי\"א ע' 123</a> ואילך (חידושים וביאורים להל' ביהב\"ח ע' יא ואילך)."],["631","41","סוף מדות. אלא שבגי' הרמב\"ם ליתא — ראה בארוכה לקו\"ש שם. ואכ\"מ."]]],[1301410139,"בכללות, לההבדל (העיקרי) בין חלקו של אברהם וחלקו של יצחק במעשה העקידה<sup data-n=\"632\">42</sup>:\nמעשה המסירת נפש של העקידה מתייחס (בעיקר) לאברהם<sup data-n=\"633\">43</sup>, שהוא הי' צריך לכבוש את רחמיו מעל בנו יחידו ולהעלהו לעולה ע\"ג מזבח, משא\"כ יצחק, שאמר<sup data-n=\"634\">44</sup> \"ואי' השה לעולה\" [וגם לפרש\"י<sup data-n=\"635\">45</sup> שאחרי תשובת אברהם \"הבין. . שהוא הולך להשחט (ומ\"מ) וילכו שניהם יחדיו בלב שוה\" — מ\"מ, אינה דומה מסנ\"פ דיצחק למסנ\"פ דאברהם בעקידת בנו יחידו שנולד לו לעת זקנותו, וכמו שהאריך במו\"נ שם ד\"לא ידמה לו לא נתינת ממון ולא נתינת נפש\"<sup data-n=\"636\">46</sup>] — וזהו ענין העבודה שבמעשה העקידה;\nואילו חלקו של יצחק במעשה העקידה הי' בעיקר בהנפעל, שהוא נתקדש בקדושת עולה ע\"י שנעקד ע\"ג המזבח — וחלות קדושה שייכת, כמובן, להשראת השכינה.\nוזהו שהרמב\"ם מדייק ומחלק בשתי הלכות אלו:\nבדין הראשון, שהוא דין במזבח מחמת פעולתו בכללות המקדש — ענין השראת השכינה — כתב הרמב\"ם שזהו מפני ש\"במקדש נעקד יצחק\";\nואילו בהלכה שלאח\"ז, דין מקומו ה\"מכוון ביותר\" של המזבח, שהוא מצד גדר המזבח עצמו, ענין העבודה (כנ\"ל) — בזה מדייק הרמב\"ם, שזה שייך למעשה אברהם, ש\"בנה בו המזבח ו(הוא — אברהם) עקד עליו יצחק\".\n<span data-k=\"q\">(משיחות ש\"פ מטו\"מ וש\"פ ראה תש\"מ, ש\"פ מטו\"מ תשמ\"ג) </span>",[["632","42","במו\"נ שם מדובר בב' הענינים שנתגלו במעשה העקידה עצמו, ושניהם נתגלו ע\"י אברהם, ע\"ש (ושם: ובאמת הי' ראוי שיהי' זה ענין על יד אברהם וביצחק כו' כי אברהם אבינו הוא אשר התחיל כו'). והמבואר בפנים הוא בנוגע התוצאות ממעשה העקידה לענין קביעת מקום המזבח כו'."],["633","43","וכמבואר בכ\"מ ד\"פתיחת הצנור\" למסנ\"פ היתה ע\"י אברהם ע\"י נסיון העקידה (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201074\" data-slug=\"likkutei-sichot\" data-id=\"1300201074\">לקו\"ש ח\"כ ע' 74</a> ואילך. וש\"נ) — ולא ע\"י יצחק.\n[ולהעיר מב\"י לטאו\"ח (ס\"א ד\"ה וטוב לומר) שאומרים פ' העקידה בכל יום \"כדי. . להכניע יצרו לעבוד השי\"ת כמו שמסר יצחק נפשו\" — הובא בשו\"ע אדה\"ז שם מהד\"ק ס\"י. אבל: (א) במהד\"ת (שם ס\"ט) השמיטו. (ב) ועיקר בה\"רבש\"ע\" שאומרים אחרי פרשת העקידה מודגשת רק מסנ\"פ דאברהם (כמו שכבש רחמיו כו'), ולא דיצחק. ואכ\"מ]."],["634","44","פרשתנו כב, ז. וראה ראב\"ע שם."],["635","45","פרשתנו שם, ח. וראה ב\"ר פנ\"ו, ד. שם, ח."],["636","46","וראה מאמרי אדה\"ז לפרשיות התורה (פרשתנו ס\"ע קכח): ולכן נזכר בתורה הנסיון של העקידה על אברהם ולא על יצחק כי מפני שלהפקיר א\"ע יכול להיות בקל אבל אברהם שהפקיר את בנו כו'."]]],[1301410140,"<h3>שיחה ג</h3>\nא. על הכתוב<sup data-n=\"637\">1</sup> \"וישא אברהם את עיניו וירא והנה איל גו' ויעלהו לעולה תחת בנו\", מפרש רש\"י: \"תחת בנו, מאחר שכתוב ויעלהו לעולה לא חסר המקרא כלום, מהו תחת בנו, על כל עבודה שעשה ממנו<sup data-n=\"638\">2</sup> הי' מתפלל ואומר יה\"ר שתהא זו כאלו היא עשוי' בבני, כאלו בני שחוט כאלו דמו זרוק כאלו בני מופשט כאלו הוא נקטר ונעשה דשן\".\nוצריך להבין:\nלעיל על הפסוק<sup data-n=\"639\">3</sup> \"קח נא את בנך גו' והעלהו שם לעולה\" פרש\"י \"והעלהו, לא אמר לו שחטהו לפי שלא הי' חפץ הקב\"ה לשחטו אלא להעלהו להר לעשותו עולה ומשהעלהו אמר לו הורידהו\". ודבר זה הודיע הקב\"ה לאברהם לאחר זה, כהובא ברש\"י על הפסוק<sup data-n=\"640\">4</sup> \"ויאמר אל תשלח ידך אל הנער ואל תעש לו מאומה כי עתה ידעתי גו'\", שהקב\"ה אמר לו לאברהם \"לא אחלל בריתי ומוצא שפתי לא אשנה<sup data-n=\"641\">5</sup> כשאמרתי לך קח מוצא שפתי לא אשנה לא אמרתי לך שחטהו אלא העלהו, אסקתי' אחתי'\".\nומכיון שכבר ידע אברהם \"שלא הי' חפץ הקב\"ה לשחטו אלא להעלהו\" — ועד שאא\"פ להיות באופן אחר, כי \"מוצא שפתי לא אשנה\", הקב\"ה הבטיח לאברהם \"כי ביצחק יקרא לך זרע\"<sup data-n=\"642\">6</sup> — צריך המתקה איך זה העלה אברהם את האיל \"תחת בנו\", ש\"הי' מתפלל. . כאלו בני שחוט כו'\", הרי הקב\"ה \"הי' חפץ. . לא לשחטו\"?\nואין לתרץ, דמזה שנזדמן לו האיל בשעה זו (ובפרט ע\"פ פרש\"י<sup data-n=\"643\">7</sup> \"שהי' (האיל) רץ אצל אברהם\") הבין שהקב\"ה רוצה שיקריבנו על המזבח<sup data-n=\"644\">8</sup> — כי זוהי הוכחה שרצונו של הקב\"ה הוא להקריבו ע\"ג המזבח<sup data-n=\"645\">9</sup>, אבל לא לחדש רצון להקריבו \"תחת בנו\"<sup data-n=\"646\">10</sup>.",[["637","1","פרשתנו כב, יג."],["638","2","לכאורה צ\"ל בו (וכבההמשך תומ\"י — בבני). ובא' מכת\"י רש\"י שתח\"י \"שהי' עובד\" (במקום \"שעשה ממנו\"). אבל בדפוסים הנפוצים, וכן בדפוס ראשון ושני דפרש\"י, שאר כת\"י רש\"י שתח\"י ועוד — הוא כבפנים."],["639","3","כב, ב."],["640","4","שם, יב."],["641","5","תהלים פט, לה."],["642","6","פרשתנו כא, יב."],["643","7","כב, יג ד\"ה בקרניו. וראה שם ד\"ה והנה איל \"מוכן הי' לכך מששת ימי בראשית\"."],["644","8","וראה רשב\"ם, אברבנאל, ספורנו ועוד."],["645","9","ולא יהי' המזבח ללא תכלית (אברבנאל כאן) כלל, ובמכל שכן וק\"ו מקייץ המזבח (רש\"י ויקרא א, ב. שבועות יב, א) שלא יהא \"בלא תכלית\" אפילו לזמן קצר. וראה הערה הבאה."],["646","10","ועוד זאת: מאריכות לשון הכתוב \"וישא אברהם את עיניו וירא והנה איל\" משמע, שלא ראה את האיל פתאום, אלא שנשא את עיניו לחפש<sup data-n=\"e13\">*</sup> אחר בהמה כדי להקריבה \"תחת בנו\" (דאל\"כ הו\"ל להכתוב לקצר \"וירא אברהם והנה איל\"). וכן מפורש ברד\"ק כאן. והיינו שההתעוררות להקריב קרבן באה מצד אברהם. וראה לקמן הערה 24.\n[ובאברבנאל כאן מפרש, ש\"הי' קשה (לאברהם) שתהי' ביאתו אל המקום ההוא לבטלה ובנין המזבח ועריכת העצים ללא תכלית ונשא עיניו כו'\" (וראה פסיקתא רבתי פ' בחודש השביעי). אבל ראה רש\"י (כב, יב) דאברהם אמר להמלאך \"לחנם באתי לכאן\", ומוכח מזה ש(המשך) המענה \"כי עתה ידעתי גו'\" ביטל טענה זו, דאין ביאתו לחנם, כי הנסיון גופא הוא התכלית]."],["e13","*","וע\"ד \"וישא עיניו וירא\" בריש פרשתנו (יח, ב) — כי אברהם הי' \"יושב פתח האהל\", \"לראות אם יש עובר ושב\" (יח, א וברש\"י) — שחיפש אורחים; וכן בתחילת מעשה העקידה — \"ויהי ביום השלישי וישא אברהם את עיניו וירא את המקום מרחוק\" — כי הוצרך לחפש את המקום (ראה רש\"י שם \"איחר מלהראותו מיד\"), וגם ראיית המקום היתה ע\"י ש\"ראה ענן קשור על ההר\" (רש\"י שם)."]]]]});
